const SARV_HOME_SKIP_KEY='sarv_home_intro_skip';
function sarvHomeSkipped_(){try{return JSON.parse(localStorage.getItem(SARV_HOME_SKIP_KEY)||'{}')||{};}catch(e){return {};}}
function sarvHomeHelpHtml_(h){
  return '<ul>'+h.points.map(p=>'<li>'+escText(p)+'</li>').join('')+'</ul>';
}
function sarvHomeTipShow_(btn){
  const h=SARV_HOME_HELP[btn.dataset.go];if(!h)return;
  let tip=byId('sarvHomeTip');
  if(!tip){tip=document.createElement('div');tip.id='sarvHomeTip';document.body.appendChild(tip);}
  tip.innerHTML='<b>'+h.icon+' '+escText(h.title)+'</b>'+sarvHomeHelpHtml_(h);
  tip.hidden=false;
  // Beside the button when there is room, otherwise below it.
  const r=btn.getBoundingClientRect(),tw=tip.offsetWidth,th=tip.offsetHeight;
  let x=r.right+12,y=r.top;
  if(x+tw>innerWidth-8){x=Math.max(8,Math.min(r.left,innerWidth-tw-8));y=r.bottom+8;}
  if(y+th>innerHeight-8)y=Math.max(8,innerHeight-th-8);
  tip.style.left=x+'px';tip.style.top=y+'px';
}
function sarvHomeTipHide_(){const t=byId('sarvHomeTip');if(t)t.hidden=true;}
// Shows the Hindi details, then runs `go` once they are dismissed.
function sarvHomeIntro_(key,go){
  const h=SARV_HOME_HELP[key];
  sarvHomeTipHide_();
  if(!h||sarvHomeSkipped_()[key])return go();
  const ov=document.createElement('div');
  ov.id='sarvHomeIntro';
  ov.innerHTML='<div class="card"><div class="hd"><span>'+h.icon+'</span><span>'+escText(h.title)+'</span></div>'
    +'<div class="bd">'+sarvHomeHelpHtml_(h)+'</div>'
    +'<div class="ft"><span class="tap">कहीं भी एक बार क्लिक करें — आगे बढ़ें</span>'
    +'<label class="skip"><input type="checkbox"> ये संदेश दोबारा न दिखाएं</label></div></div>';
  document.body.appendChild(ov);
  const done=()=>{
    document.removeEventListener('keydown',onKey,true);
    ov.remove();
    go();
  };
  const onKey=e=>{if(e.key==='Escape'||e.key==='Enter'){e.preventDefault();done();}};
  // The "don't show again" tick is the one click that doesn't close it.
  const skip=ov.querySelector('.skip');
  skip.addEventListener('click',e=>{
    e.stopPropagation();
    const cb=skip.querySelector('input');
    const s=sarvHomeSkipped_();
    if(cb.checked)s[key]=true;else delete s[key];
    try{localStorage.setItem(SARV_HOME_SKIP_KEY,JSON.stringify(s));}catch(err){}
  });
  ov.addEventListener('click',done);
  document.addEventListener('keydown',onKey,true);
}
/* ── Inward (NB) confirmation code ────────────────────────────────────
   A non-billable receipt carries no bill and no GST, so it must never be
   opened by a mis-click on the home page. The word below has to be typed out
   in full; only then does the Inward (NB) form open. Anything else — a wrong
   word, Cancel or Escape — leaves the user on Home. */
const SARV_NB_GATE_CODE='WITHOUTGSTBILL';
function sarvNbCodeGate_(go){
  const ov=document.createElement('div');
  ov.id='sarvNbGate';
  ov.innerHTML='<div class="card"><div class="hd"><span></span><span>Inward (NB) — Non-Billable</span></div>'
    // SARV_NB_GATE_CODE is never printed anywhere on this card — not as a hint,
    // not as the placeholder, and not in the error below. A passkey shown on
    // screen is no passkey. type="password" keeps it off the screen while it is
    // being typed too.
    +'<div class="bd">Passkey:'
    +'<input type="text" autocomplete="off" spellcheck="false" placeholder="••••••••">'
    +'<div class="err"></div></div>'
    +'<div class="ft"><button type="button" class="cancel">Cancel</button>'
    +'<button type="button" class="ok">Open Form</button></div></div>';
  document.body.appendChild(ov);
  const inp=ov.querySelector('input'), err=ov.querySelector('.err');
  const close=()=>{document.removeEventListener('keydown',onKey,true);ov.remove();};
  const submit=()=>{
    // Case and stray spaces are forgiven; the word itself is not. BOTH sides are
    // folded, so SARV_NB_GATE_CODE can be written in any case and still match —
    // comparing a folded input against an unfolded constant would lock the form
    // shut for good.
    const fold=s=>String(s||'').trim().toUpperCase().replace(/\s+/g,'');
    if(fold(inp.value)===fold(SARV_NB_GATE_CODE)){close();go();return;}
    err.textContent='Incorrect passkey. Please try again.';
    inp.select();inp.focus();
  };
  const onKey=e=>{
    if(e.key==='Escape'){e.preventDefault();close();}
    else if(e.key==='Enter'){e.preventDefault();submit();}
  };
  ov.querySelector('.ok').addEventListener('click',submit);
  ov.querySelector('.cancel').addEventListener('click',close);
  // A click on the backdrop closes it too, but one inside the card must not.
  ov.addEventListener('click',e=>{if(e.target===ov)close();});
  inp.addEventListener('input',()=>{err.textContent='';});
  document.addEventListener('keydown',onKey,true);
  inp.focus();
}
/* ── Nature chooser on the way in from Home ───────────────────────────
   Material Inward / Inward (NB) / Material Outward each ask what KIND of
   movement this is before the form opens, and the answer is then locked on the
   form. Deciding it up front is the point: the Nature drives which fields the
   entry needs (a Repair return needs its outward picked, a Repair dispatch is
   what the Repair Tracker follows), and those used to be reachable only by
   remembering to change a dropdown halfway down a half-filled form.
   Issue is deliberately not here — an ISSUE is always CONSUMABLE. */
const SARV_NATURE_GATE={
  IN:    {kind:'inward', icon:'', title:'Material Inward', q:'Nature of Inward?'},
  IN_NB: {kind:'inward', icon:'', title:'Inward (NB) — Non-Billable', q:'Nature of Inward?'},
  OUT:   {kind:'outward',icon:'', title:'Material Outward', q:'Nature of Dispatch?'},
};
/* v = exactly what the form's own dropdown stores (so "Return" is saved as
   Repaired, the value inwNatureOfInward has always used); l = screen label.
   The Home page's Nature chooser. The values live in Master Data › Dropdown
   Master (keys erp_natureOfInward / erp_natureOfDispatch), the same list that
   feeds the Inward / Outward form select, so the two never disagree. Only the
   presentation of those values is kept here: the screen label, colour and a
   one-line meaning. If the Admin adds a new value it appears in the chooser
   too, in a neutral colour. */
const SARV_NATURE_META={
  inward:[
    {v:'Purchase', l:'Purchase', c:'#0369a1', note:'Material bought from a supplier'},
    {v:'Repaired', l:'Return',   c:'#b45309', note:'Material returned after repair'},
    {v:'Transfer', l:'Transfer', c:'#6d28d9', note:'Stock received from another unit'},
  ],
  outward:[
    {v:'Non-Returnable', l:'Non-Returnable', c:'#0f766e', note:'Will not come back'},
    {v:'Repair',         l:'Repair',         c:'#b45309', note:'Repair Tracker me chalega'},
    {v:'Transfer',       l:'Transfer',       c:'#6d28d9', note:'Dusre unit ko bheja'},
    {v:'Sample',         l:'Sample',         c:'#0369a1', note:'Sample dispatch'},
  ],
};
const SARV_NATURE_DD_KEY={inward:'erp_natureOfInward',outward:'erp_natureOfDispatch'};
function sarvNatureOpts_(kind){
  const meta=SARV_NATURE_META[kind]||[];
  let vals=null;
  try{
    const l=sarvDropdownList(SARV_NATURE_DD_KEY[kind]);
    if(l&&l.length)vals=l;
  }catch(e){}
  if(!vals)return meta;
  return vals.map(v=>meta.find(m=>m.v===v)||{v:v,l:v,c:'#475569',note:''});
}
function sarvNatureLabel_(kind,value){
  const o=sarvNatureOpts_(kind).find(x=>x.v===value);
  return o?o.l:(value||'');
}
/* Asks, then calls go(). Cancel / Escape / a backdrop click answer nothing and
   leave the user on Home — the same rule the Inward (NB) passkey follows. */
function sarvNatureGate_(key,go){
  const cfg=SARV_NATURE_GATE[key];
  if(!cfg)return go();
  const opts=sarvNatureOpts_(cfg.kind);
  const ov=document.createElement('div');
  ov.id='sarvNatureGate';
  ov.innerHTML='<div class="card"><div class="hd"><span>'+cfg.icon+'</span><span>'+escText(cfg.title)+'</span></div>'
    +'<div class="bd"><div class="q">'+escText(cfg.q)+'</div>'
    +'<div class="hint">Choose one option. The form opens locked to it, and it cannot be changed partway through the entry.</div>'
    +'<div class="opts">'
    +opts.map(o=>'<button type="button" data-v="'+escText(o.v)+'" style="border-color:'+o.c+';color:'+o.c+';">'
        +escText(o.l)+'<small>'+escText(o.note)+'</small></button>').join('')
    +'</div></div>'
    +'<div class="ft"><button type="button" class="cancel">Cancel</button></div></div>';
  document.body.appendChild(ov);
  const close=()=>{document.removeEventListener('keydown',onKey,true);ov.remove();};
  const onKey=e=>{if(e.key==='Escape'){e.preventDefault();close();}};
  ov.querySelectorAll('.opts button').forEach(b=>b.addEventListener('click',()=>{
    sarvHomeNature[cfg.kind]=b.dataset.v;
    close();
    go();
  }));
  ov.querySelector('.cancel').addEventListener('click',close);
  ov.addEventListener('click',e=>{if(e.target===ov)close();});
  document.addEventListener('keydown',onKey,true);
  ov.querySelector('.opts button')?.focus();
}
/* What the chooser picked, for as long as this visit to the section lasts.
   Cleared on the way back Home (sarvGoHome) and when an existing record is
   opened for edit — an edit must show that record's own Nature. */
let sarvHomeNature={inward:null,outward:null};
let sarvNatureLockBusy=false;   // applyHomeNatureLocks fires 'change' — don't re-enter
/* Re-asserts the pin. Called wherever something else may have touched these
   two dropdowns: on arrival from Home, after a save clears the form, and at
   the end of setInwardPoLock / populateNatureOfDispatch, both of which
   re-enable their select as part of their own rules. */
function applyHomeNatureLocks(){
  if(sarvNatureLockBusy)return;
  sarvNatureLockBusy=true;
  try{
    const pin=(el,val,kind)=>{
      if(!el||!val)return;
      if(![...el.options].some(o=>o.value===val))el.add(new Option(sarvNatureLabel_(kind,val),val));
      if(el.value!==val){el.value=val;el.dispatchEvent(new Event('change'));}
      el.disabled=true;el.style.background='#f1f5f9';el.style.cursor='not-allowed';
      el.title='"'+sarvNatureLabel_(kind,val)+'" was chosen on the Home page; it cannot be changed in this entry';
    };
    const inw=sarvHomeNature.inward;
    pin(byId('inwNatureOfInward'),inw,'inward');
    /* An inward booked against a PO is always a Purchase receipt — loadPoIntoInward
       forces the Nature back to Purchase. With a Return / Transfer pinned, leaving
       the PO picker live would let that silently overwrite the locked choice, so
       the picker is taken off instead. */
    if(inw){
      const off=inw!=='Purchase', poBtn=byId('poNumberBtn');
      if(off&&sarvSelectedPoNos.length){setSelectedPoNos([]);togglePoNumberPanel(false);}
      if(poBtn){
        poBtn.disabled=off;
        poBtn.style.background=off?'#f1f5f9':'';
        poBtn.style.cursor=off?'not-allowed':'pointer';
        poBtn.title=off?('The Nature of Inward is "'+sarvNatureLabel_('inward',inw)+'"; only a Purchase inward can be made against a PO'):'';
      }
    }
    // ISSUE owns its own Nature (always CONSUMABLE) — a pin never overrides it.
    if((byId('outEntryTypeSelect')?.value||'')!=='ISSUE')pin(byId('outNatureOfDispatch'),sarvHomeNature.outward,'outward');
  }finally{
    sarvNatureLockBusy=false;
  }
}
/* Drops the pins and hands both dropdowns back. Whatever runs next
   (populateNatureOfDispatch / setInwardPoLock) re-applies its own rules. */
function releaseHomeNatureLocks(){
  sarvHomeNature={inward:null,outward:null};
  ['inwNatureOfInward','outNatureOfDispatch'].forEach(id=>{
    const el=byId(id);if(!el)return;
    el.disabled=false;el.style.background='';el.style.cursor='';el.title='';
  });
  const poBtn=byId('poNumberBtn');
  if(poBtn){poBtn.disabled=false;poBtn.style.background='';poBtn.style.cursor='pointer';poBtn.title='';}
}
document.addEventListener('DOMContentLoaded',()=>{
  byId('sarvLoginBtn')?.addEventListener('click',sarvAttemptLogin);
  byId('sarvLoginRole')?.addEventListener('change',()=>sarvFillLoginUsers_().catch(()=>{}));
  byId('sarvLoginPin')?.addEventListener('keydown',e=>{if(e.key==='Enter')sarvAttemptLogin();});
  /* Login by name: fill the datalist, show the roles for a name, and log in
     directly on Enter (pressing Enter on the PIN after filling the name is
     the usual habit, but some people press Enter on the name itself). */
  const nb=byId('sarvLoginNameBox');
  if(nb){
    nb.addEventListener('input',()=>sarvLoginNameHint_());
    nb.addEventListener('change',()=>sarvLoginNameHint_());
    nb.addEventListener('keydown',e=>{
      if(e.key!=='Enter')return;
      const p=byId('sarvLoginPin');
      if(p&&!p.value){p.focus();return;}     // name done, now the PIN
      sarvAttemptLogin();
    });
  }
  // If the login screen is open, fill the name list right away.
  if(byId('sarvLoginGate')&&byId('sarvLoginGate').style.display!=='none')
    sarvFillLoginNames_().catch(()=>{});
  const home=byId('sarvHomeDashboard');
  home?.addEventListener('click',e=>{
    const b=e.target.closest('.sarv-home-row');if(!b)return;
    const go=b.dataset.go;
    const open=()=>sarvNavigateFromHome(go);
    // Inward / Inward (NB) / Outward ask what KIND of movement this is, last of
    // all — the answer is what the form opens locked on.
    const withNature=SARV_NATURE_GATE[go]?(()=>sarvNatureGate_(go,open)):open;
    // Inward (NB) asks for its confirmation word before that: no point choosing
    // a Nature for a form the passkey may not open.
    const proceed=go==='IN_NB'?()=>sarvNbCodeGate_(withNature):withNature;
    // DISABLED: Hindi guidance popup shown on click before the screen opened.
    // To bring it back, replace `proceed();` with the line below.
    // sarvHomeIntro_(go,proceed);
    proceed();
  });
  /* DISABLED: Hindi help card shown on hover / focus of each Home button.
     Uncomment this block to bring it back (SARV_HOME_HELP still holds the text).
  home?.querySelectorAll('.sarv-home-row').forEach(b=>{
    b.addEventListener('mouseenter',()=>sarvHomeTipShow_(b));
    b.addEventListener('mouseleave',sarvHomeTipHide_);
    b.addEventListener('focus',()=>sarvHomeTipShow_(b));
    b.addEventListener('blur',sarvHomeTipHide_);
  });
  */
  // Restore a previous login so the PIN isn't asked again on every reload —
  // only an explicit Logout (sarvLogout, via the role badge) clears it.
  try{
    const savedRole=localStorage.getItem(SARV_LOGIN_STORAGE_KEY);
    if(savedRole&&SARV_ROLE_LABEL[savedRole]){
      sarvCurrentRole=savedRole;
      try{sarvCurrentUser=JSON.parse(localStorage.getItem(SARV_LOGIN_USER_KEY)||'null');}catch(e){sarvCurrentUser=null;}
      /* Roles are kept under a separate key. An old session (from before this
         change) stored only the role; there, roles come from the user row,
         otherwise that single role. So nobody's access changes on reload. */
      try{
        const rr=JSON.parse(localStorage.getItem(SARV_LOGIN_ROLES_KEY)||'null');
        sarvCurrentRoles=Array.isArray(rr)&&rr.length?rr.filter(Boolean)
          :((sarvCurrentUser&&Array.isArray(sarvCurrentUser.roles)&&sarvCurrentUser.roles.length)
              ?sarvCurrentUser.roles.filter(Boolean):[savedRole]);
      }catch(e){sarvCurrentRoles=[savedRole];}
      try{localStorage.removeItem(SARV_LOGIN_SIG_KEY);}catch(e){}
      const badge=byId('sarvRoleBadge');
      if(badge){badge.textContent=''+sarvLoginLabel_();badge.title=sarvRolesTitle_()||badge.title;}
      sarvApplyAccess();
      /* The user's role / app access may have changed on the server while the
         browser still remembers the old one. We ask the session for the
         current state, quietly; if that fails the old one keeps working (the
         app must still open offline). */
      sarvRefreshSsoSession_().catch(()=>{});
      const gate=byId('sarvLoginGate');if(gate)gate.style.display='none';
      if(byId('p_poListBody'))refreshGeneratedPoList().catch(()=>{});
      sarvGoHome();
    }
  }catch(e){}
  /* Remove the splash that prevents the login screen from flashing; the
     decision has been made (either restored, or the gate must be shown). This
     comes from localStorage, so no network call has happened yet and the
     splash lasts only a frame or two. See sso-preboot.js. */
  if(window.sarvSsoPrebootDone)window.sarvSsoPrebootDone();
});

/* ================================================================
   ADMIN PANEL — Users & Roles, role-wise Feature Access, Tab Visibility
   ----------------------------------------------------------------
   Both matrices live in app_settings (keys role_permissions /
   tab_visibility) as {KEY:{ROLE:true|false}}. Anything not saved yet
   falls back to the defaults below, which are what the app did before
   this panel existed — so running the migration changes nothing until
   an Admin saves. Writes go through admin_save_setting() /
   admin_save_user() and are authorised by the Admin PIN on the server
   (ADMIN_PANEL_MIGRATION.sql). mobile.html reads the same
   role_permissions row for its six tabs.
================================================================ */
