let sarvSettings={role_permissions:null,tab_visibility:null};
let sarvSettingsMissing=false;
let sarvAppUsers=[],sarvAppUsersLoaded=false,sarvAppUsersMissing=false;
// Sales › Order Form ke role — app_users.sales_role (ek hi user table).
let sarvSalesRoleReady=false;
/* Whether UNIFIED_USERS_MIGRATION.sql has been run, i.e. whether the roles[] /
   app_access / session columns exist. If false, the Admin Panel hides the
   multi-role and Apps parts (better to say plainly that the migration needs
   running than to show a half-working UI). */
let sarvUnifiedReady=false;
let sarvUnifiedErr='';   // its real reason, shown in the Admin Panel note
/* ── Unit (Unit-1 / Unit-2) + Complaint App profile ──────────────────
   Every user belongs to one factory unit (app_users.cmp_unit). It is asked
   at Signup on the launcher and is REQUIRED here. The Complaint App stamps
   it on every complaint the user raises, and only that unit's hosts /
   triagers get the complaint.

   The Complaint App's own "Users" tab is gone: its role, host types,
   "All units", department and designation are managed here, in the same
   user form (admin_save_user_unit_profile, Admin PIN). The Complaint
   account itself is still created by Apps › Complaint App = ON.

   The unit list comes from `cmp_units` (a Unit-3 later is a row there). */
let sarvUnitReady=false;
let sarvUnits=[{code:'Unit-1',name:'Unit-1'},{code:'Unit-2',name:'Unit-2'}];
async function sarvLoadUnits_(){
  try{
    const r=await SB.from('cmp_units').select('code,name,sort_order').eq('is_active',true).order('sort_order').order('code');
    if(!r.error&&r.data&&r.data.length)sarvUnits=r.data;
  }catch(e){console.warn('[SARV] cmp_units not loaded, using the fallback list:',e.message||e);}
}
const sarvUnitName_=code=>{const x=sarvUnits.find(u=>u.code===code);return x?(x.name||x.code):(code||'');};
// Must stay in step with complaint.html (ROLES / MACHINE_TYPES / FABRIC_TYPES)
// and admin_save_user_unit_profile().
const SARV_CMP_ROLES=['User','Host','Admin','Maintenance','Production Manager'];
const SARV_CMP_TYPE_GROUPS=[
  {label:'Machine',types:['Mechanical','Electrical','Housekeeping','Other']},
  {label:'Fabric',types:['Shade','Weight/GSM','Width','Hole/Cut','Stain','Print Defect','Finishing Defect','Other Fabric Defect']}
];
// "All units" means nothing for a plain User (sees only their own) or the
// Admin (always sees every unit).
const SARV_CMP_ALL_UNIT_ROLES=['Host','Maintenance','Production Manager'];
const SARV_UNIT_ERR={ADMIN_PIN_INVALID:'Incorrect Admin PIN',USER_NOT_FOUND:'User not found. Please refresh.',
  UNIT_REQUIRED:'Please choose the unit',UNIT_INVALID:'That unit is not active',CMP_ROLE_INVALID:'Invalid Complaint App role',
  HOST_TYPES_REQUIRED:'A Host needs at least one complaint type',HOST_TYPE_INVALID:'Unknown complaint type'};
let sarvUsersDenied=false; // true = a missing GRANT (not a missing column)
const SARV_SALES_ROLES=[
  {v:'admin',l:'Admin',hint:'Create, Edit, Status, Emboss catalog'},
  {v:'manager',l:'Manager',hint:'Create, Edit, Status'},
  {v:'executive',l:'Executive',hint:'Create, Edit'},
  {v:'data_entry',l:'Data Entry',hint:'New orders only'},
  {v:'viewer',l:'Viewer',hint:'View only'}
];
const sarvSalesRoleLabel_=v=>{const r=SARV_SALES_ROLES.find(x=>x.v===v);return r?r.l:'';};

function sarvDefOf_(d,role){
  if(d.def==='ALL')return true;
  if(d.def==='W')return role!=='VIEW_PIN';
  return Array.isArray(d.def)&&d.def.includes(role);
}
function sarvMatrixVal_(matrix,defs,key,role){
  const d=defs.find(f=>f.key===key);if(!d)return true;
  if(d.lock&&d.lock.includes(role))return true;
  const m=matrix&&matrix[key];
  if(m&&typeof m[role]==='boolean')return m[role];
  return sarvDefOf_(d,role);
}
function sarvCanRole(role,key){return sarvMatrixVal_(sarvSettings.role_permissions,SARV_FEATURES,key,role);}
/* Access = the UNION of all roles. If any one role says YES, access is granted. */
function sarvCan(key){
  const rs=sarvRoles_();
  return rs.length>0&&rs.some(r=>sarvCanRole(r,key));
}
/* Whether a tab / app shows is decided at three levels, in this order:

     1. The USER's own override (Admin Panel › Users › Apps)
          true  = always show, whatever the role says
          false = always hide, whatever the role says
     2. the role-wise Tab Visibility matrix (union of all roles)
     3. the code default (`def` in SARV_TABS)

   The first level is what lets the Admin "remove this button for this one
   user" without touching their whole role; before, hiding something from
   one person meant creating a new role. */
function sarvTabVisible(key){
  const rs=sarvRoles_();
  if(!rs.length)return true;
  const ov=sarvUserAccessOverride_(key);
  if(typeof ov==='boolean')return ov;
  return rs.some(r=>sarvMatrixVal_(sarvSettings.tab_visibility,SARV_TABS,key,r));
}
/* This user's own decision on this key: true / false, or undefined ("auto",
   i.e. whatever the role gives). */
function sarvUserAccessOverride_(key){
  const a=sarvCurrentUser&&sarvCurrentUser.app_access;
  if(!a||typeof a!=='object')return undefined;
  const v=a[key];
  return typeof v==='boolean'?v:undefined;
}
function sarvNavTargetVisible_(target){
  const ks=SARV_NAV_TARGET_KEYS[target];
  return !ks||ks.some(sarvTabVisible);
}
function sarvFeatureLabel_(key){const d=SARV_FEATURES.find(f=>f.key===key);return d?d.label:key;}
function sarvDeny(key){
  // With several roles, count them all; otherwise the user thinks "but I have another role".
  const rn=sarvRoles_().map(r=>SARV_ROLE_LABEL[r]||r).join(' + ');
  showToast('"'+sarvFeatureLabel_(key)+'": '+(rn||'this role')+' does not have access. Ask the Admin for access under Settings › Admin Panel.','warn');
}
function sarvGuard(key){if(sarvCan(key))return true;sarvDeny(key);return false;}

/* Buttons that are simply hidden when the role lacks the feature, and every
   control that is refused on click. The click check runs in the capture phase,
   so it fires before the button's own handler and covers rows that are
   rendered later as well. */
const SARV_FEATURE_HIDE={
  ADD_ITEM:['[onclick^="openNewItemMasterModal"]'],
  DOWNLOAD_CSV:['[onclick^="exportTableCSV"]','#excelDownloadBtn'],
  ADD_EMPLOYEE:['#p_reqAddEmpBtn','[onclick^="addMasterEmployee"]'],
  ADD_MACHINE:['[onclick^="addMasterMachine"]'],
  EXPORT_CSV:['#itLeCsvBtn','#p_exportCsvBtn','#p_poRepCsvBtn','#pod_csv'],
  PDF_VIEW:['#itLePdfBtn'],
};
const SARV_CLICK_GUARDS=[
  ['#submitBtn','SUBMIT_INWARD'],
  ['#outSubmitBtn',()=>(byId('outEntryTypeSelect')?.value==='ISSUE'?'SUBMIT_ISSUE':'SUBMIT_OUTWARD')],
  ['#itLeRunBtn','ITEM_LEDGER'],
  ['#itLeCsvBtn,#p_exportCsvBtn,#p_poRepCsvBtn,#pod_csv','EXPORT_CSV'],
  ['a[data-doc="PR"]','PR_PDF'],
  ['#itLePdfBtn,#searchResultsBody a[href],#p_poListBody a[href],a.fu-doc[href],#itLeResults a.it-doc','PDF_VIEW'],
  ['[onclick^="exportTableCSV"],#excelDownloadBtn','DOWNLOAD_CSV'],
  ['[onclick^="openNewItemMasterModal"]','ADD_ITEM'],
  ['#p_reqAddEmpBtn,[onclick^="addMasterEmployee"]','ADD_EMPLOYEE'],
  ['[onclick^="addMasterMachine"]','ADD_MACHINE'],
  ['.sarv-po-cancel','PO_CANCEL'],
  ['.sarv-po-shortclose','PO_CLOSE'],
];
document.addEventListener('click',e=>{
  if(!sarvRoles_().length||!e.target||!e.target.closest)return;
  for(const [sel,k] of SARV_CLICK_GUARDS){
    const el=e.target.closest(sel);if(!el)continue;
    const key=typeof k==='function'?k(el):k;
    if(key&&!sarvCan(key)){e.preventDefault();e.stopImmediatePropagation();sarvDeny(key);}
    return;
  }
},true);
function sarvApplyPermCss_(){
  let st=byId('sarvPermStyle');
  if(!st){st=document.createElement('style');st.id='sarvPermStyle';document.head.appendChild(st);}
  const hide=[];
  if(sarvRoles_().length)Object.keys(SARV_FEATURE_HIDE).forEach(k=>{if(!sarvCan(k))hide.push(...SARV_FEATURE_HIDE[k]);});
  st.textContent=hide.length?hide.join(',')+'{display:none !important;}':'';
}
function sarvApplyHomeTiles_(){
  document.querySelectorAll('#sarvHomeDashboard .sarv-home-row[data-go]').forEach(b=>{
    b.style.display=sarvTabVisible('HOME_'+b.dataset.go)?'':'none';
  });
}
function sarvApplySubTabs_(){
  document.querySelectorAll('#masterDataPanel .master-sub-tab[data-subtab]').forEach(b=>{
    const k=SARV_MASTER_SUB_KEY[b.dataset.subtab];
    b.style.display=(!k||sarvTabVisible(k))?'':'none';
  });
  Object.keys(SARV_PO_SUB_KEY).forEach(id=>{
    const b=byId(id);if(b)b.style.display=sarvTabVisible(SARV_PO_SUB_KEY[id])?'':'none';
  });
  document.querySelectorAll('#productionPanel .prod-sub-tab[data-prodsub]').forEach(b=>{
    const k=SARV_PROD_SUB_KEY[b.dataset.prodsub];
    b.style.display=(!k||sarvTabVisible(k))?'':'none';
  });
  const ap=byId('sarvAdminPanel');if(ap)ap.style.display=isAdmin()?'':'none';
  /* The whole Fabric / Brand Master table (columns, chips and row buttons)
     is built from Feature Access and Tab Visibility. If the Admin has just
     saved the matrix, the open screen should reflect it immediately;
     otherwise the old buttons stay visible and only a click says "no
     access". Only the screen that IS OPEN is rebuilt. */
  if(typeof sarvFbmRender==='function'){
    [['fabricMasterSub','FABRIC'],['brandMasterSub','BRAND'],
     ['buyerMasterSub','BUYER'],['buyerMasterSub','AGENCY'],['trimRateMasterSub','TRIMRATE']].forEach(([sub,code])=>{
      const el=byId(sub);
      if(el&&el.style.display!=='none'&&sarvFbmState[code].loaded){
        try{sarvFbmRender(code);}catch(e){}
      }
    });
  }
  // Item Master › New PR Generation — column + button follow Tab Visibility.
  byId('itemMasterTable')?.classList.toggle('im-hide-newpr',!sarvTabVisible('MD_ITEM_NEWPR'));
  if(typeof sarvSyncItemPrSelUi_==='function')sarvSyncItemPrSelUi_();
}
// The section just opened must not sit on a sub-tab this role cannot see.
function sarvEnsureVisibleSubTabs_(){
  sarvApplySubTabs_();
  const mp=byId('masterDataPanel');
  if(mp&&mp.style.display!=='none'){
    const cur=[...mp.querySelectorAll('[id$="Sub"]')].find(x=>x.style.display!=='none');
    const curBtn=cur&&mp.querySelector('.master-sub-tab[data-subtab="'+cur.id+'"]');
    if(!curBtn||curBtn.style.display==='none'){
      const first=[...mp.querySelectorAll('.master-sub-tab[data-subtab]')].find(b=>b.style.display!=='none');
      if(first)switchMasterSubTab(first.dataset.subtab);
    }
  }
  const panels={p_poSubPendingBtn:'p_poPendingPanel',p_poSubListBtn:'p_poListPanel',p_poSubReportBtn:'p_poReportPanel'};
  const shown=Object.keys(panels).find(b=>byId(panels[b])&&byId(panels[b]).style.display!=='none');
  if(shown&&byId(shown)&&byId(shown).style.display==='none'){
    const first=Object.keys(panels).find(b=>byId(b)&&byId(b).style.display!=='none');
    if(first)byId(first).click();
    else Object.values(panels).forEach(p=>{if(byId(p))byId(p).style.display='none';});
  }
}
function sarvApplyAccess(){
  sarvApplyPadPinMode_();
  sarvApplyPermCss_();
  sarvApplyHomeTiles_();
  sarvApplySubTabs_();
  if(byId('sarvHomeDashboard')?.style.display==='none')sarvEnsureVisibleSubTabs_();
}

/* ── Loading ────────────────────────────────────────────────────── */
async function sarvLoadSettings_(){
  if(!SB_READY)return;
  try{
    const q=await SB.from('app_settings').select('key,value').in('key',['role_permissions','tab_visibility']);
    if(q.error)throw q.error;
    sarvSettings={role_permissions:null,tab_visibility:null};
    (q.data||[]).forEach(r=>{sarvSettings[r.key]=r.value||null;});
    sarvSettingsMissing=false;
  }catch(e){
    sarvSettingsMissing=true;
    console.warn('[SARV] app_settings not loaded (has ADMIN_PANEL_MIGRATION.sql been run?):',e.message||e);
  }
  sarvApplyAccess();
}
async function sarvLoadAppUsers_(force){
  if(sarvAppUsersLoaded&&!force)return sarvAppUsers;
  if(!SB_READY)return sarvAppUsers;
  try{
    // signature is deliberately not selectable — only get_user_signature() returns it.
    // sales_role (Order Form Role) comes from ORDER_FORM_USERS_MIGRATION.sql; if
    // that hasn't run, retry without that column so the user list is never empty.
    const cols='id,user_name,role,emp_code,contact_no,has_signature,is_active,created_at,updated_at';
    /* A three-level fallback, from newest to oldest, so that whichever
       migrations a setup has run, its user list is never empty:
         1. + roles / app_access / links  (UNIFIED_USERS_MIGRATION.sql)
         2. + sales_role                  (ORDER_FORM_USERS_MIGRATION.sql)
         3. base columns only             (ADMIN_PANEL_MIGRATION.sql) */
    const uniCols=',roles,app_access,cmp_profile_id,pk_profile_id';
    /* Level 0: unit + Complaint App profile (COMPLAINT_UNITS_MIGRATION.sql +
       UNIT_SIGNUP_ADMIN_MIGRATION.sql). Tried first and dropped on its own,
       so a setup without those two still gets level 1 below. */
    const unitCols=',cmp_unit,cmp_all_units,cmp_role,cmp_host_types,cmp_username,department,designation';
    let q=await SB.from('app_users').select(cols+',sales_role'+uniCols+unitCols).order('user_name');
    sarvUnitReady=!q.error;
    if(q.error){
      console.warn('[SARV] app_users unit columns not readable (run UNIT_SIGNUP_ADMIN_MIGRATION.sql):',q.error.message||q.error);
      q=await SB.from('app_users').select(cols+',sales_role'+uniCols).order('user_name');
    }
    if(sarvUnitReady)await sarvLoadUnits_();
    sarvUnifiedReady=!q.error;
    /* Keep the real reason. Most of the time spent answering "why aren't the
       Extra Roles showing" went into finding this; now the Admin Panel note
       shows this message directly. */
    sarvUnifiedErr=q.error?(q.error.message||String(q.error)):'';
    /* "permission denied" and "column not found" are TWO DIFFERENT things;
       both used to get the same message, which blamed the wrong migration.
       The GRANT mistake is common in Supabase: an RLS policy is created but
       the table-level GRANT is forgotten, and RLS doesn't work without the
       grant. */
    sarvUsersDenied=!!q.error&&/permission denied/i.test(sarvUnifiedErr);
    if(q.error)console.warn('[SARV] app_users read fail ('
      +(sarvUsersDenied?'GRANT missing: run section 1b of UNIFIED_USERS_MIGRATION.sql'
                       :'column missing: has UNIFIED_USERS_MIGRATION.sql been run?')+'):',sarvUnifiedErr);
    sarvSalesRoleReady=!q.error;
    if(q.error){
      q=await SB.from('app_users').select(cols+',sales_role').order('user_name');
      sarvSalesRoleReady=!q.error;
    }
    if(q.error)q=await SB.from('app_users').select(cols).order('user_name');
    if(q.error)throw q.error;
    sarvAppUsers=q.data||[];sarvAppUsersMissing=false;
  }catch(e){
    sarvAppUsers=[];sarvAppUsersMissing=true;
    console.warn('[SARV] app_users not loaded (has ADMIN_PANEL_MIGRATION.sql been run?):',e.message||e);
  }
  sarvAppUsersLoaded=true;
  sarvRefreshPurchaserLists_();
  sarvApplyPadPinMode_();
  return sarvAppUsers;
}
// Purchasers come from Users & Roles; the old fixed names only until the migration has run.
function sarvPurchaserNames_(){
  const p=sarvAppUsers.filter(u=>u.role==='PURCHASER'&&u.is_active).map(u=>u.user_name);
  return p.length?p:SARV_PURCHASER_FALLBACK.slice();
}
function sarvRefreshPurchaserLists_(){
  const names=sarvPurchaserNames_();
  const sel=byId('p_reqGeneratedBy');
  if(sel){
    const keep=sel.value;
    const list=keep&&!names.includes(keep)?names.concat([keep]):names;
    sel.innerHTML='<option value="">-- Select Purchaser --</option>'+list.map(n=>'<option value="'+escText(n)+'">'+escText(n)+'</option>').join('');
    sel.value=keep;
  }
  const og=document.querySelector('#pwdChangeTarget optgroup');
  if(og)og.innerHTML=names.map(n=>'<option value="PURCHASER::'+escText(n)+'">Purchaser &mdash; '+escText(n)+'</option>').join('');
}

/* ── Admin Panel UI ─────────────────────────────────────────────── */
let sarvApPane='users';
let sarvApDraft={perms:null,tabs:null};
function sarvFullMatrix_(matrix,defs){
  const out={};
  defs.forEach(d=>{if(!d.key)return;out[d.key]={};SARV_PERM_ROLES.forEach(r=>{out[d.key][r.code]=sarvMatrixVal_(matrix,defs,d.key,r.code);});});
  return out;
}
function sarvRenderAdminPanel(){
  sarvApplySubTabs_();
  if(!isAdmin())return;
  const note=byId('ap_migrationNote');
  Promise.all([sarvLoadSettings_(),sarvLoadAppUsers_(true)]).then(()=>{
    if(note){
      /* Which migrations are still pending, one by one, by name. Only
         ADMIN_PANEL used to be mentioned, so if UNIFIED hadn't run, "Extra
         Roles / Apps" silently stayed hidden and the Admin assumed the feature
         didn't exist. Now the reason is spelled out. */
      const miss=[];
      /* A missing GRANT first: it looks like "the table doesn't exist" but is
         something quite different, with a different fix. */
      if(sarvUsersDenied)
        miss.push('<b><code>anon</code> has no SELECT GRANT on app_users</b> &mdash; that is why the user list is empty. '
          +'Supabase ne kaha: <code>permission denied for table app_users</code>.<br>'
          +'Fix: run <b>section 1b</b> of <code>UNIFIED_USERS_MIGRATION.sql</code> (it only grants access, '
          +'and deliberately leaves out <code>signature</code> / <code>pin_hash</code>).');
      else if(sarvSettingsMissing||sarvAppUsersMissing)
        miss.push('<code>ADMIN_PANEL_MIGRATION.sql</code> &mdash; until then the defaults are in use and Save will not work');
      else if(!sarvUnifiedReady)
        miss.push('<code>UNIFIED_USERS_MIGRATION.sql</code> &mdash; without it the <b>Extra Roles</b> (one user, several roles) and <b>Apps</b> '
          +'(per-user app access) parts don\'t show in the user form, and the Complaint App / Packing keep asking for their own password');
      note.style.display=miss.length?'block':'none';
      note.innerHTML=miss.length
        ?'Not yet run in Supabase &rsaquo; SQL Editor: '+miss.join('<br>')
          +'<br><small>Already run it and still seeing this? Run <code>notify pgrst, \'reload schema\';</code> in Supabase &rsaquo; SQL Editor '
          +'(the API\'s column cache can be stale), then reload this page.'
          +(sarvUnifiedErr?'<br>Supabase ne kaha: <code>'+escText(sarvUnifiedErr)+'</code>':'')+'</small>'
        :'';
    }
    if(!sarvApDraft.perms)sarvApDraft.perms=sarvFullMatrix_(sarvSettings.role_permissions,SARV_FEATURES);
    if(!sarvApDraft.tabs)sarvApDraft.tabs=sarvFullMatrix_(sarvSettings.tab_visibility,SARV_TABS);
    sarvRenderUsers_();
    sarvRenderMatrix_('ap_permMatrix',SARV_FEATURES,'perms');
    sarvRenderMatrix_('ap_tabMatrix',SARV_TABS,'tabs');
  });
}
// Admin Panel over the whole window (its own page scroll), or back in Settings.
function sarvApFullScreen_(on){
  const ap=byId('sarvAdminPanel');if(!ap)return;
  ap.classList.toggle('ap-full',!!on);
  const b=byId('ap_fullScreenBtn');
  if(b){b.innerHTML=on?'&#10005; Exit Full Screen':'Full Screen';b.title=on?'Back to Settings (Esc)':'Open the Admin Panel full screen (Esc to exit)';}
  if(on)ap.scrollTop=0;
}
function sarvShowApPane_(p){
  sarvApPane=p;
  document.querySelectorAll('#sarvAdminPanel .ap-tab').forEach(b=>b.classList.toggle('active',b.dataset.ap===p));
  document.querySelectorAll('#sarvAdminPanel .ap-pane').forEach(x=>x.style.display=x.dataset.apPane===p?'':'none');
}
function sarvRoleLabelOf_(code){const r=SARV_PERM_ROLES.find(x=>x.code===code);return r?r.label:(SARV_ROLE_LABEL[code]||code);}
function sarvRenderUsers_(){
  const tb=byId('ap_usersBody');if(!tb)return;
  const rf=byId('ap_userRoleFilter');
  if(rf&&rf.options.length<=1)rf.innerHTML='<option value="">All Roles</option>'+SARV_PERM_ROLES.map(r=>'<option value="'+r.code+'">'+escText(r.label)+'</option>').join('');
  if(sarvAppUsersMissing){tb.innerHTML='<tr><td colspan="10" class="ap-empty">The app_users table was not found. Run ADMIN_PANEL_MIGRATION.sql.</td></tr>';return;}
  // Unit filter: rebuilt each time (the unit list loads with the users),
  // keeping the current choice; hidden until the unit columns exist.
  const uf=byId('ap_userUnitFilter');
  if(uf){
    uf.style.display=sarvUnitReady?'':'none';
    const keep=uf.value;
    uf.innerHTML='<option value="">All Units</option>'+sarvUnits.map(x=>'<option value="'+escText(x.code)+'">'+escText(x.name||x.code)+'</option>').join('')
      +'<option value="__none">Unit not set</option>';
    uf.value=keep;
  }
  const unitV=sarvUnitReady&&uf?uf.value:'';
  const role=rf?.value||'',q=(byId('ap_userSearch')?.value||'').trim().toLowerCase();
  const order=SARV_PERM_ROLES.map(r=>r.code);
  const rows=sarvAppUsers.filter(u=>(!role||u.role===role)
      &&(!unitV||(unitV==='__none'?!u.cmp_unit:u.cmp_unit===unitV))
      &&(!q||[u.user_name,u.emp_code,u.contact_no,sarvRoleLabelOf_(u.role),u.cmp_unit,u.cmp_role].join(' ').toLowerCase().includes(q)))
    .sort((a,b)=>order.indexOf(a.role)-order.indexOf(b.role)||String(a.user_name).localeCompare(String(b.user_name)));
  if(!rows.length){tb.innerHTML='<tr><td colspan="10" class="ap-empty">No users yet. Create one with Add User.</td></tr>';return;}
  tb.innerHTML=rows.map((u,i)=>'<tr>'
    +'<td style="color:#94a3b8;">'+(i+1)+'</td>'
    +'<td style="font-weight:800;">'+escText(u.user_name)+'</td>'
    +'<td><span class="ap-pill" style="background:#e0f2fe;color:#0369a1;" title="Primary role, used for signatures / audit">'+escText(sarvRoleLabelOf_(u.role))+'</span>'
      /* The count of extra roles; the full list is in the hover. Writing out
         every pill made the row wide and pushed the name aside. */
      +(((u.roles&&u.roles.length)||0)>1
        ?' <span class="ap-pill" style="background:#ede9fe;color:#5b21b6;" title="'
          +escText(u.roles.map(r=>sarvRoleLabelOf_(r)+(r===u.role?' (primary)':'')).join(', ')
            +'; access is the union of all of these')+'">+'+(u.roles.length-1)+' role</span>':'')
      /* Per-user app override: the Admin sees immediately that something is
         set by hand for this person; otherwise time goes into working out
         "why isn't this button showing for them". */
      +(u.app_access&&Object.keys(u.app_access).length
        ?' <span class="ap-pill" style="background:#fff7ed;color:#9a3412;" title="'
          +escText(Object.keys(u.app_access).map(k=>(SARV_APP_LABEL[k]||k)+': '+(u.app_access[k]?'ON':'OFF')).join(', '))
          +'">'+Object.keys(u.app_access).length+'</span>':'')
      +(u.sales_role?' <span class="ap-pill" style="background:#fef3c7;color:#92400e;" title="Sales › Order Form role">'+escText(sarvSalesRoleLabel_(u.sales_role))+'</span>':'')
      +(u.cmp_profile_id?' <span class="ap-pill" style="background:#f0fdf4;color:#166534;" title="Linked to the old Complaint App account">C</span>':'')
      +(u.pk_profile_id?' <span class="ap-pill" style="background:#f0fdf4;color:#166534;" title="Linked to the old Packing account">P</span>':'')
      +'</td>'
    /* Unit, and the Complaint App role under it for anyone with a complaint
       account (that tab used to live inside the Complaint App). */
    +'<td>'+(!sarvUnitReady?'—'
      :(u.cmp_unit
        ?'<span class="ap-pill" style="background:#ede9fe;color:#5b21b6;">'+escText(sarvUnitName_(u.cmp_unit))
          +(u.cmp_all_units&&SARV_CMP_ALL_UNIT_ROLES.indexOf(u.cmp_role)>=0?' + all':'')+'</span>'
        :'<span class="ap-pill" style="background:#fef3c7;color:#92400e;" title="Required: Edit the user and choose a unit">Not set</span>')
      +(u.cmp_username?'<div style="font-size:10px;color:#64748b;margin-top:2px;" title="Complaint App role'
          +((u.cmp_host_types||[]).length?': '+escText(u.cmp_host_types.join(', ')):'')+'">Complaint: '+escText(u.cmp_role||'User')+'</div>':''))
    +'</td>'
    +'<td>'+escText(u.emp_code||'—')+'</td>'
    +'<td>'+escText(u.contact_no||'—')+'</td>'
    +'<td style="text-align:center;">'+(u.has_signature?'<span style="color:#15803d;font-weight:800;" title="Signature saved; can sign with PIN">&#10004;</span>':'<span style="color:#b45309;font-weight:700;" title="No signature yet">&mdash;</span>')+'</td>'
    +'<td style="text-align:center;"><span class="ap-pill" style="background:'+(u.is_active?'#dcfce7':'#fee2e2')+';color:'+(u.is_active?'#166534':'#dc2626')+';">'+(u.is_active?'Active':'Inactive')+'</span></td>'
    +'<td style="text-align:center;"><button type="button" class="ap-ibtn" data-ap-edit="'+escText(u.id)+'" style="background:#eff6ff;border:1px solid #93c5fd;color:#1d4ed8;" title="Edit user">✎</button></td>'
    +'<td style="text-align:center;"><button type="button" class="ap-ibtn" data-ap-del="'+escText(u.id)+'" style="background:#fef2f2;border:1px solid #fca5a5;color:#dc2626;">&#10005;</button></td>'
    +'</tr>').join('');
}
function sarvRenderMatrix_(tableId,defs,which){
  const t=byId(tableId);if(!t)return;
  const m=sarvApDraft[which]||{};
  const saved=which==='perms'?sarvFullMatrix_(sarvSettings.role_permissions,SARV_FEATURES):sarvFullMatrix_(sarvSettings.tab_visibility,SARV_TABS);
  let h='<thead><tr><th>'+(which==='perms'?'FEATURES':'TABS / SUB TABS')+'</th>'
    +SARV_PERM_ROLES.map(r=>'<th data-ap-col="'+r.code+'" title="Click: the whole column YES / NO">'+escText(r.label)+'</th>').join('')+'</tr></thead><tbody>';
  defs.forEach(d=>{
    if(d.group){h+='<tr class="ap-group"><td colspan="'+(SARV_PERM_ROLES.length+1)+'">'+escText(d.group)+'</td></tr>';return;}
    const dirty=SARV_PERM_ROLES.some(r=>!!(m[d.key]||{})[r.code]!==!!(saved[d.key]||{})[r.code]);
    h+='<tr data-ap-key="'+d.key+'"'+(dirty?' class="ap-dirty"':'')+'><th data-ap-row="'+d.key+'" title="Click: the whole row YES / NO">'+escText(d.label)+(d.hint?'<small>'+escText(d.hint)+'</small>':'')+'</th>';
    SARV_PERM_ROLES.forEach(r=>{
      const locked=!!(d.lock&&d.lock.includes(r.code));
      const on=locked||!!(m[d.key]||{})[r.code];
      h+='<td class="ap-cell'+(on?' yes':'')+(locked?' locked':'')+'"><label title="'+escText(r.label+' — '+d.label)+(locked?' (hamesha YES)':'')+'">'
        +'<input type="checkbox" data-ap-k="'+d.key+'" data-ap-r="'+r.code+'"'+(on?' checked':'')+(locked?' disabled':'')+'></label></td>';
    });
    h+='</tr>';
  });
  t.innerHTML=h+'</tbody>';
  t.dataset.which=which;
}
function sarvMatrixClick_(e){
  const t=e.currentTarget,which=t.dataset.which,defs=which==='perms'?SARV_FEATURES:SARV_TABS,m=sarvApDraft[which];
  if(!m)return;
  const lockedFor=(k,r)=>{const d=defs.find(x=>x.key===k);return !!(d&&d.lock&&d.lock.includes(r));};
  const cb=e.target.closest('input[data-ap-k]');
  if(cb){m[cb.dataset.apK][cb.dataset.apR]=cb.checked;sarvRenderMatrix_(t.id,defs,which);return;}
  const col=e.target.closest('th[data-ap-col]');
  if(col){
    const r=col.dataset.apCol,keys=defs.filter(d=>d.key&&!lockedFor(d.key,r)).map(d=>d.key);
    const allOn=keys.every(k=>m[k][r]);keys.forEach(k=>m[k][r]=!allOn);
    sarvRenderMatrix_(t.id,defs,which);return;
  }
  const row=e.target.closest('th[data-ap-row]');
  if(row){
    const k=row.dataset.apRow,roles=SARV_PERM_ROLES.map(r=>r.code).filter(r=>!lockedFor(k,r));
    const allOn=roles.every(r=>m[k][r]);roles.forEach(r=>m[k][r]=!allOn);
    sarvRenderMatrix_(t.id,defs,which);
  }
}
async function sarvSaveMatrix_(which){
  if(!isAdmin())return showToast('Admin login only','warn');
  const key=which==='perms'?'role_permissions':'tab_visibility';
  const adminPin=await askSecret({title:'Confirm with Admin PIN',subtitle:'To save '+(which==='perms'?'Feature Access':'Tab Visibility'),
    recordInfo:'Applies to all roles immediately (in the mobile app too)',label:'Admin PIN',confirmText:'Save'});
  if(adminPin==null)return;
  if(!adminPin.trim())return showToast('The Admin PIN cannot be empty','warn');
  try{
    const r=await SB.rpc('admin_save_setting',{p_key:key,p_value:sarvApDraft[which],p_admin_pin:adminPin.trim()});
    if(r.error)throw r.error;
    if(!r.data)return showToast('Incorrect Admin PIN; not saved','error');
    sarvSettings[key]=JSON.parse(JSON.stringify(sarvApDraft[which]));
    sarvApplyAccess();
    sarvRenderMatrix_(which==='perms'?'ap_permMatrix':'ap_tabMatrix',which==='perms'?SARV_FEATURES:SARV_TABS,which);
    showToast(''+(which==='perms'?'Feature Access':'Tab Visibility')+' saved');
  }catch(e){
    if(/admin_save_setting|does not exist/i.test(e.message||''))showToast('Run ADMIN_PANEL_MIGRATION.sql first','warn');
    else dbError(e);
  }
}

/* ── Signature pad (shared by the user popup) ───────────────────── */
function sarvMakeSigPad_(canvas){
  const ctx=canvas.getContext('2d');
  ctx.strokeStyle='#0f172a';ctx.lineWidth=2.4;ctx.lineCap='round';ctx.lineJoin='round';
  let down=false,ink=0,lx=0,ly=0;
  const pos=e=>{const r=canvas.getBoundingClientRect(),s=e.touches?e.touches[0]:e;return{x:(s.clientX-r.left)*canvas.width/r.width,y:(s.clientY-r.top)*canvas.height/r.height};};
  const start=e=>{e.preventDefault();down=true;const p=pos(e);lx=p.x;ly=p.y;ctx.beginPath();ctx.moveTo(p.x,p.y);};
  const move=e=>{e.preventDefault();if(!down)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();ink+=Math.hypot(p.x-lx,p.y-ly);lx=p.x;ly=p.y;};
  const stop=()=>{down=false;};
  canvas.addEventListener('mousedown',start);canvas.addEventListener('mousemove',move);
  canvas.addEventListener('mouseup',stop);canvas.addEventListener('mouseleave',stop);
  canvas.addEventListener('touchstart',start,{passive:false});canvas.addEventListener('touchmove',move,{passive:false});
  canvas.addEventListener('touchend',stop);
  return{
    clear(){ctx.clearRect(0,0,canvas.width,canvas.height);ink=0;},
    hasInk(){return ink>=30;},
    dataUrl(){return canvas.toDataURL('image/png');}
  };
}
// Draws a saved signature into any pad, scaled to fit and centred.
function sarvDrawSigInto_(canvas,dataUrl){
  return new Promise((res,rej)=>{
    const img=new Image();
    img.onload=()=>{
      const cx=canvas.getContext('2d');
      cx.clearRect(0,0,canvas.width,canvas.height);
      const s=Math.min(canvas.width/img.width,canvas.height/img.height);
      const w=img.width*s,h=img.height*s;
      cx.drawImage(img,(canvas.width-w)/2,(canvas.height-h)/2,w,h);
      res();
    };
    img.onerror=()=>rej(new Error('The signature image did not load'));
    img.src=dataUrl;
  });
}

/* ── User add / edit popup ──────────────────────────────────────── */
/* ── User form: EXTRA ROLES ───────────────────────────────────────────
   The primary role has its own dropdown above; here go any other roles to
   grant. Access is the union of ALL of them. The primary's checkbox is shown
   disabled + ticked, to make clear that it counts too and that it can't be
   removed here (it is changed from the dropdown above). */
function sarvUserRolesHtml_(u,role){
  const have=(u&&u.roles&&u.roles.length)?u.roles:(u?[u.role]:[]);
  return '<div class="fg" style="grid-column:1 / -1;">'
    +'<label>Extra Roles <small style="text-transform:none;font-weight:600;">'
    +'(besides the primary; access is the UNION of all of these)</small></label>'
    +'<div data-f="roleswrap" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(168px,1fr));gap:4px 10px;'
    +'border:1px solid #cbd5e1;border-radius:7px;padding:8px 10px;background:#f8fafc;">'
    +SARV_PERM_ROLES.map(r=>{
        const isPrim=r.code===role;
        const on=isPrim||have.indexOf(r.code)>=0;
        return '<label style="display:flex;align-items:center;gap:6px;margin:0;text-transform:none;font-size:11px;'
          +'font-weight:'+(on?'800':'600')+';color:'+(isPrim?'#0369a1':'#334155')+';cursor:'+(isPrim?'default':'pointer')+';">'
          +'<input type="checkbox" data-role="'+r.code+'"'+(on?' checked':'')+(isPrim?' disabled':'')
          +' style="width:14px;height:14px;">'+escText(r.label)
          +(isPrim?' <small style="color:#0369a1;font-weight:700;">(primary)</small>':'')+'</label>';
      }).join('')
    +'</div></div>';
}

/* ── User form: APPS (tri-state) ──────────────────────────────────────
   Three states for each app:
     auto  - whatever the role-wise Tab Visibility says (default)
     ON    - always show, whatever the role says
     OFF   - always hide, whatever the role says
   "auto" is the default on purpose: that keeps the role-wise matrix
   meaningful, and the Admin only has to touch the one person whose case is
   different. Below it, "what the role gives right now" is shown too, so
   choosing auto involves no guesswork. */
const SARV_APP_LABEL={HOME_PR:'Purchase Requirement',HOME_PO:'PO Generation',HOME_IN:'Material Inward',
  HOME_IN_NB:'Inward (NB)',HOME_OUT:'Material Outward',HOME_ISSUE:'Issue',HOME_REPORTS:'Print History / Reports',
  HOME_TRACKER:'Item Tracker',HOME_MASTER:'Master Data',HOME_REPAIR:'Repair Tracker',HOME_PRODUCTION:'Production',
  HOME_LOT_CARD:'Lot Card Manager',HOME_PRINTING_LOT:'Printing Lot Card',HOME_TRIMS:'Trims Manager',
  HOME_APPROVAL_APP:'Approval App',HOME_COMPLAINT_APP:'Complaint App',HOME_PACKING:'Packing & Dispatch',
  HOME_ORDER_FORM:'Order Form (Sales)',HOME_SHEET_LINKS:'Sheet Links'};
// Apps that open in their own file; their SSO runs on this access.
const SARV_APP_EXTERNAL={HOME_COMPLAINT_APP:1,HOME_PACKING:1,HOME_ORDER_FORM:1,HOME_SHEET_LINKS:1};

/* ── Apps that also need their own ACCOUNT ───────────────────────────
   Complaint and Packing data run on Supabase Auth (their RLS and triggers
   need `auth.uid()`). So DIRECT login to these two (without that app's own
   password) works only when the person also has an account in that app:
     Complaint → app_users.cmp_username filled in + a row in auth.users
     Packing   → a row in packing.profiles (same id) + a row in auth.users
   The Order Form isn't included: its SSO runs on access alone and needs no
   auth session.

   THIS WAS THE GAP: switching the toggle above ON only wrote the
   `app_access` jsonb (`admin_set_user_app_access`), and this account was
   never created. The Admin thought it was done, but the user still saw
   "NO_APP_ACCOUNT". The account-creating RPC (`admin_grant_app_access`)
   and the Edge Function's provision path already existed; nothing called them. */
const SARV_APP_NEEDS_ACCOUNT={HOME_COMPLAINT_APP:1,HOME_PACKING:1};

/* Carries ON/OFF through to that app's account.
   Returns { id, note }. `id` is returned on purpose: when a new auth account
   is created, app_users.id is moved to that new auth id
   (erp_relink_user_id). Doing anything further with the old id would give
   "USER_NOT_FOUND". */
async function sarvSyncExternalAppAccount_(adminPin,userId,appKey,on){
  const label=SARV_APP_LABEL[appKey]||appKey;
  const r=await SB.rpc('admin_grant_app_access',
    {p_admin_pin:adminPin,p_user_id:userId,p_app_key:appKey,p_on:on});
  if(r.error){
    const m=String(r.error.message||r.error);
    return {id:userId,note:'; Warning: the '+label+' account was not created: '
      +(/does not exist|schema cache|PGRST202/i.test(m)
          ? 'run MERGE_PROFILE_IDS_INTO_APP_USER_ID.sql'
          : m)};
  }
  const d=r.data||{};
  if(d.success)return {id:userId,note:''};
  if(d.error!=='AUTH_USER_MISSING')
    return {id:userId,note:' — '+label+': '+(d.error||'unknown')};

  /* ── "AUTH_USER_MISSING" doesn't mean "no account" ──────────────────
     It only means there is no account on THIS id. Often the account DOES
     exist, just on another id, and trying to create a new one used to fail
     with "A user with this email address has already been registered". So we
     look for that one first and link the id to it; this is all done in SQL,
     with no Edge Function needed.
     (`erp_link_existing_auth_account` — sql/FIX_APP_ACCOUNT_PROVISION.sql) */
  const lk=await SB.rpc('erp_link_existing_auth_account',
    {p_admin_pin:adminPin,p_user_id:userId,p_email:null});
  if(!lk.error&&lk.data&&lk.data.success){
    const newId=String(lk.data.user_id||userId);
    // The id is linked; now the same grant again, on the new id.
    const r2=await SB.rpc('admin_grant_app_access',
      {p_admin_pin:adminPin,p_user_id:newId,p_app_key:appKey,p_on:on});
    if(!r2.error&&r2.data&&r2.data.success)
      return {id:newId,note:' · '+label+' account linked'
        +(lk.data.changed?' (purana auth account '+(lk.data.email||'')+')':'')};
    return {id:newId,note:'; Warning: '+label+': the id was linked but access was not applied: '
      +((r2.error&&r2.error.message)||(r2.data&&r2.data.error)||'unknown')};
  }
  if(lk.data&&lk.data.error==='AUTH_ACCOUNT_TAKEN')
    return {id:userId,note:'; Warning: '+label+': '+(lk.data.hint||'the auth account is linked to another ERP user')};
  const lkErr=(lk.data&&lk.data.error)||(lk.error&&lk.error.message)||'';
  /* If the RPC doesn't exist there's no point going further: the path that
     creates a new auth account depends on it too. We say so plainly. */
  if(/does not exist|schema cache|PGRST202/i.test(lkErr))
    return {id:userId,note:'; Warning: '+label+': first run sql/FIX_APP_ACCOUNT_PROVISION.sql in the SQL Editor'};
  if(lkErr&&!/NO_AUTH_ACCOUNT_FOUND/.test(lkErr))
    return {id:userId,note:' — '+label+': '+lkErr};

  /* There really is no auth account. Only service_role can create one, and
     that key never reaches the browser, so the Edge Function does this: it
     creates the account (with the same id) and then calls this same RPC
     itself to grant access. */
  let fr=null,fd=null;
  try{
    fr=await fetch(SUPABASE_URL+'/functions/v1/erp-sso',{
      method:'POST',
      headers:{'Content-Type':'application/json','apikey':SUPABASE_ANON_KEY,
               'Authorization':'Bearer '+SUPABASE_ANON_KEY},
      body:JSON.stringify({action:'provision',admin_pin:adminPin,user_id:userId,app:appKey})});
    fd=await fr.json().catch(()=>null);
  }catch(e){
    return {id:userId,note:'; Warning: '+label+': could not reach the Edge Function ('+(e.message||e)+')'};
  }
  if(!fr.ok||!fd||!fd.success){
    const why=(fd&&(fd.message||fd.detail||fd.error))||('HTTP '+fr.status);
    /* These two messages come from an old (not yet redeployed) erp-sso, and
       in both cases the real fix is to deploy. The hint is added on the
       client, because the reply comes from the old version and carries no hint. */
    let fix='';
    if(/database error creating new user/i.test(why))
      fix=' → deploy the new version of erp-sso (the old version clashes with the auth.users trigger): '
        +'supabase functions deploy erp-sso';
    else if(/already been registered/i.test(why))
      fix=' → the account exists, just on another id. Run sql/FIX_APP_ACCOUNT_PROVISION.sql in the SQL Editor, then Save again.';
    return {id:userId,note:'; Warning: the '+label+' account was not created: '
      +(fr.status===404?'the erp-sso Edge Function is not deployed (supabase functions deploy erp-sso)':why)+fix};
  }
  return {id:fd.user_id||userId,note:' · '+label+' account created'};
}

function sarvUserAppsHtml_(u){
  const acc=(u&&u.app_access&&typeof u.app_access==='object')?u.app_access:{};
  const roles=(u&&u.roles&&u.roles.length)?u.roles:(u&&u.role?[u.role]:[]);
  const roleSays=k=>roles.length
    ? roles.some(r=>sarvMatrixVal_(sarvSettings.tab_visibility,SARV_TABS,k,r))
    : null;
  return '<div class="fg" style="grid-column:1 / -1;">'
    +'<label>Apps <small style="text-transform:none;font-weight:600;">'
    +'(Home page buttons. <b>auto</b> = whatever the role gives; ON / OFF applies to this user only)</small></label>'
    +'<div data-f="appswrap" style="border:1px solid #cbd5e1;border-radius:7px;padding:4px 0;background:#f8fafc;'
    +'max-height:230px;overflow:auto;">'
    +SARV_APP_KEYS.map(k=>{
        const v=typeof acc[k]==='boolean'?(acc[k]?'1':'0'):'';
        const rs=roleSays(k);
        const hint=rs===null?'':(rs?'from role: shown':'from role: hidden');
        return '<div style="display:flex;align-items:center;gap:8px;padding:3px 10px;">'
          +'<span style="flex:1 1 auto;font-size:11px;font-weight:700;color:#334155;">'
            +escText(SARV_APP_LABEL[k]||k)
            +(SARV_APP_EXTERNAL[k]?' <small style="color:#7c3aed;font-weight:700;">alag app</small>':'')
            /* For these two, ON doesn't just show a button; it also creates
               that app's account (and OFF deactivates it). The Admin needs to
               know this up front; otherwise they'd take it for "just a toggle",
               leave it on 'auto', and the user's direct login would never be set up. */
            +(SARV_APP_NEEDS_ACCOUNT[k]?' <small style="color:#047857;font-weight:700;text-transform:none;">ON = account bhi banega</small>':'')
            +(hint?' <small style="color:#94a3b8;font-weight:600;text-transform:none;">— '+hint+'</small>':'')
          +'</span>'
          +'<select data-app="'+k+'" style="flex:0 0 auto;width:78px;height:24px;font-size:10.5px;padding:0 4px;'
            +'border:1px solid #cbd5e1;border-radius:5px;font-family:inherit;'
            +'background:'+(v===''?'#fff':(v==='1'?'#dcfce7':'#fee2e2'))+';">'
          +'<option value=""'+(v===''?' selected':'')+'>auto</option>'
          +'<option value="1"'+(v==='1'?' selected':'')+'>ON</option>'
          +'<option value="0"'+(v==='0'?' selected':'')+'>OFF</option>'
          +'</select></div>';
      }).join('')
    +'</div>'
    +'<div style="display:flex;gap:6px;margin-top:5px;flex-wrap:wrap;">'
    +'<button type="button" class="b no sm" data-f="appsauto">Sab auto</button>'
    +'<button type="button" class="b no sm" data-f="appson">Sab ON</button>'
    +'<button type="button" class="b no sm" data-f="appsoff">Sab OFF</button>'
    +'<span style="flex:1 1 auto;"></span>'
    +(u?'<button type="button" class="b no sm" data-f="applink" title="Link to the old Complaint App / Packing accounts by name">Link external accounts</button>':'')
    +'</div></div>';
}

/* Unit (required) + Complaint App profile, in the user form. If the
   migration hasn't run, the same spot says so rather than hiding it. */
function sarvUserUnitHtml_(u){
  if(!sarvUnitReady)
    return '<div class="fg" style="grid-column:1 / -1;"><div style="background:#fffbeb;border:1px solid #fcd34d;border-radius:8px;padding:10px 12px;'
      +'font-size:11px;color:#92400e;line-height:1.65;"><b>Unit and Complaint App profile are not available yet.</b> '
      +'Run <code>COMPLAINT_UNITS_MIGRATION.sql</code> and then <code>UNIT_SIGNUP_ADMIN_MIGRATION.sql</code> in Supabase &rsaquo; SQL Editor, then reload.</div></div>';
  const unit=u?(u.cmp_unit||''):'';
  const cr=u?(u.cmp_role||''):'';
  const types=(u&&u.cmp_host_types)||[];
  const box='border:1px solid #cbd5e1;border-radius:7px;padding:8px 10px;background:#f8fafc;';
  return '<div class="fg" style="grid-column:1 / -1;"><label>Unit <span class="req">*</span> '
      +'<small style="text-transform:none;font-weight:600;">(the user\'s factory unit; their complaints are saved under it and go to that unit\'s hosts)</small></label>'
    +'<div data-f="unitwrap" style="display:flex;gap:8px;flex-wrap:wrap;">'
    +sarvUnits.map(x=>'<label style="flex:1 1 120px;display:flex;align-items:center;gap:8px;margin:0;padding:8px 12px;border:1px solid #cbd5e1;border-radius:7px;'
        +'background:#fff;cursor:pointer;text-transform:none;font-size:12.5px;font-weight:800;color:#334155;">'
        +'<input type="radio" name="sarvUnitPick" data-unit="'+escText(x.code)+'"'+(x.code===unit?' checked':'')+' style="width:15px;height:15px;"> '
        +escText(x.name||x.code)+'</label>').join('')
    +'</div>'
    +(u&&!unit?'<div style="font-size:11px;color:#b45309;font-weight:700;margin-top:4px;">Unit not set yet: this user cannot raise a complaint until it is.</div>':'')
    +(u&&unit?'<div style="font-size:10.5px;color:#64748b;margin-top:4px;">Changing it moves only NEW complaints; complaints already raised stay in their old unit.</div>':'')
    +'</div>'
    /* The Complaint App's old "Users" tab, here instead. */
    +'<div class="fg" style="grid-column:1 / -1;"><label>Complaint App <small style="text-transform:none;font-weight:600;">'
      +'(the account itself is created by Apps &rsaquo; Complaint App = ON'+(u&&u.cmp_username?'; <span style="color:#15803d;">account exists</span>':'')+')</small></label>'
    +'<div style="'+box+'">'
    +'<div class="g2">'
    +'<div class="fg"><label>Complaint Role</label><select data-f="cmprole">'
      +SARV_CMP_ROLES.map(r=>'<option value="'+r+'"'+((cr||'User')===r?' selected':'')+'>'+escText(r)+'</option>').join('')+'</select></div>'
    +'<div class="fg" data-f="allunitswrap"><label>&nbsp;</label><label style="display:flex;align-items:center;gap:8px;margin:0;text-transform:none;font-size:12px;font-weight:700;color:#334155;cursor:pointer;">'
      +'<input data-f="allunits" type="checkbox" style="width:15px;height:15px;"'+(u&&u.cmp_all_units?' checked':'')+'> Covers all units</label>'
      +'<small data-f="allunitshint" style="display:block;font-size:10.5px;color:#64748b;margin-top:2px;"></small></div>'
    +'<div class="fg"><label>Department</label><input data-f="cmpdept" style="text-transform:uppercase;" value="'+escText(u?(u.department||''):'')+'" placeholder="e.g. RASCHEL"></div>'
    +'<div class="fg"><label>Designation</label><input data-f="cmpdesig" value="'+escText(u?(u.designation||''):'')+'" placeholder="e.g. Machine Operator"></div>'
    +'</div>'
    +'<div data-f="hostwrap" style="margin-top:6px;"><label style="font-size:10.5px;">Host for which complaint types <span class="req">*</span></label>'
    +SARV_CMP_TYPE_GROUPS.map(g=>'<div style="margin:4px 0 6px;"><div style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.04em;margin-bottom:3px;">'+escText(g.label)+'</div>'
        +'<div style="display:flex;flex-wrap:wrap;gap:6px;">'
        +g.types.map(t=>'<label style="display:flex;align-items:center;gap:5px;margin:0;padding:4px 9px;border:1px solid #cbd5e1;border-radius:999px;background:#fff;'
            +'text-transform:none;font-size:11.5px;font-weight:700;color:#334155;cursor:pointer;">'
            +'<input type="checkbox" data-htype="'+escText(t)+'"'+(types.indexOf(t)>=0?' checked':'')+' style="width:13px;height:13px;"> '+escText(t)+'</label>').join('')
        +'</div></div>').join('')
    +'</div>'
    +'</div></div>';
}

function sarvOpenUserModal(id,presetRole){
  if(!isAdmin())return showToast('Only an Admin login can create users','warn');
  if(sarvAppUsersMissing)return showToast('Run ADMIN_PANEL_MIGRATION.sql first','warn');
  const u=id?sarvAppUsers.find(x=>x.id===id):null;
  const role=u?u.role:(presetRole||'');
  const ov=document.createElement('div');
  ov.className='sarv-ov';ov.id='sarvUserModal';
  ov.innerHTML='<div class="card"><div class="hd">'+(u?'Update User — '+escText(u.user_name):(presetRole==='PURCHASER'?'Add New Purchaser':'Add User'))+'</div><div class="bd">'
    +'<div class="err" data-f="err"></div>'
    +'<div class="g2">'
    +'<div class="fg"><label>'+(sarvUnifiedReady?'Primary Role':'Role')+' <span class="req">*</span>'
      +(sarvUnifiedReady?' <small style="text-transform:none;font-weight:600;">(used for signatures / audit)</small>':'')
      +'</label><select data-f="role"><option value="">-- Select Role --</option>'
      +SARV_PERM_ROLES.map(r=>'<option value="'+r.code+'"'+(r.code===role?' selected':'')+'>'+escText(r.label)+'</option>').join('')+'</select></div>'
    +'<div class="fg"><label>User Name <span class="req">*</span></label><input data-f="name" style="text-transform:uppercase;" autocomplete="off" value="'+escText(u?u.user_name:'')+'" placeholder="Full name"></div>'
    +'<div class="fg"><label>Employee Code</label><input data-f="emp" list="dl-emp-codes" style="text-transform:uppercase;" autocomplete="off" value="'+escText(u?u.emp_code||'':'')+'" placeholder="optional — auto-fill"></div>'
    +'<div class="fg"><label>Contact No.</label><input data-f="contact" type="tel" maxlength="15" value="'+escText(u?u.contact_no||'':'')+'" placeholder="optional"></div>'
    +'<div class="fg" style="grid-column:1 / -1;"><label>Order Form Role <small style="text-transform:none;font-weight:600;">(Sales › Order Form, with this same name + PIN)</small></label>'
      +'<select data-f="srole"'+(sarvSalesRoleReady?'':' disabled title="Run ORDER_FORM_USERS_MIGRATION.sql first"')+'><option value="">— No Order Form access —</option>'
      +SARV_SALES_ROLES.map(r=>'<option value="'+r.v+'"'+(u&&u.sales_role===r.v?' selected':'')+'>'+escText(r.l+' — '+r.hint)+'</option>').join('')+'</select></div>'
    +'<div class="fg"><label>'+(u?'New PIN <small style="text-transform:none;font-weight:600;">(khali = purana PIN)</small>':'PIN <span class="req">*</span>')+'</label><input data-f="pin" type="password" inputmode="numeric" autocomplete="new-password" placeholder="4+ digits"></div>'
    +'<div class="fg"><label>Confirm PIN</label><input data-f="pin2" type="password" inputmode="numeric" autocomplete="new-password" placeholder="again"></div>'
    +'</div>'
    +'<div class="fg" style="display:flex;align-items:center;gap:8px;"><input data-f="active" type="checkbox" style="width:16px;height:16px;"'+(!u||u.is_active?' checked':'')+'><span style="font-size:12px;font-weight:700;color:#334155;">Active (can log in and sign with PIN)</span></div>'
    +sarvUserUnitHtml_(u)
    /* ── Extra roles + Apps ─────────────────────────────────────────
       If the columns exist, show the full UI; if not, DON'T HIDE IT QUIETLY,
       which was the earlier mistake that made the Admin think the feature
       didn't exist. Now the same spot says exactly what needs to be run. */
    +(sarvUnifiedReady
      ? sarvUserRolesHtml_(u,role)+sarvUserAppsHtml_(u)
      : '<div class="fg" style="grid-column:1 / -1;">'
        +'<div style="background:#fffbeb;border:1px solid #fcd34d;border-radius:8px;padding:10px 12px;">'
        +'<div style="font-size:11.5px;font-weight:800;color:#92400e;margin-bottom:4px;">'
        +'Extra Roles and Apps are not available yet</div>'
        +'<div style="font-size:11px;color:#92400e;line-height:1.65;">'
        +'Giving one user <b>several roles</b>, and per-user <b>app access</b> (Home buttons ON/OFF), '
        +'&mdash; both need <code>UNIFIED_USERS_MIGRATION.sql</code> run once in Supabase &rsaquo; SQL Editor. '
        +'After that this box opens right here.'
        +'<br><br>Already run it? Then run <code>notify pgrst, \'reload schema\';</code> '
        +'(the Supabase API\'s column cache can be stale) and reload the page.'
        +'</div></div></div>')
    +'<div class="fg"><label>Digital Signature '+(u&&u.has_signature?'<span style="color:#15803d;text-transform:none;">— saved &#10004; (drawing a new one replaces it)</span>':'<span style="color:#b45309;text-transform:none;">— the user signs here once</span>')+'</label>'
    +'<div class="pad"><canvas width="900" height="220"></canvas><div class="padbar"><span>Sign with a mouse, touch or stylus</span>'
    +'<span style="display:flex;gap:8px;align-items:center;">'
    +(u&&u.has_signature?'<label style="display:flex;align-items:center;gap:4px;margin:0;text-transform:none;font-size:11px;color:#b91c1c;font-weight:700;"><input data-f="sigdel" type="checkbox" style="width:14px;height:14px;"> Remove saved signature</label>':'')
    /* "Use pre saved Sign": only for a user who already has a signature.
       The need: the Admin opens this window to add an extra role, sees an
       empty pad, and thinks the signature has been lost. This button puts the
       user's saved signature on the pad (with the Admin PIN, because
       get_user_signature() asks for the user's OWN PIN, which the Admin
       doesn't have; hence the separate admin_get_user_signature()). */
    +(u&&u.has_signature?'<button type="button" class="b no sm" data-f="sigpre" title="Put this user\'s saved signature on the pad">Use pre saved Sign</button>':'')
    +'<button type="button" class="b no sm" data-f="sigclr">&#10006; Clear</button></span></div></div></div>'
    +'</div><div class="ft"><button type="button" class="b no" data-f="cancel">Cancel</button><button type="button" class="b ok" data-f="save">Save User</button></div></div>';
  document.body.appendChild(ov);
  const f=k=>ov.querySelector('[data-f="'+k+'"]');
  const pad=sarvMakeSigPad_(ov.querySelector('canvas'));
  const close=()=>{document.removeEventListener('keydown',onKey,true);ov.remove();};
  // Esc inside the Admin PIN prompt belongs to that prompt, not to this form.
  const onKey=e=>{if(e.key==='Escape'&&byId('pwdGateModal')?.style.display!=='flex'){e.preventDefault();close();}};
  document.addEventListener('keydown',onKey,true);
  const err=msg=>{const el=f('err');el.textContent=msg;el.style.display=msg?'block':'none';if(msg)ov.querySelector('.card').scrollTop=0;};
  /* A signature brought in via "Use pre saved Sign". The pad's own `ink`
     counter doesn't change for it (it only counts strokes drawn by hand), so
     it has to be remembered separately; otherwise it would be lost on Save. */
  let preSig=null;
  f('sigclr').addEventListener('click',()=>{pad.clear();preSig=null;});
  f('sigpre')?.addEventListener('click',async()=>{
    if(!u||!u.id)return;
    const adminPin=await askSecret({title:'Confirm with Admin PIN',
      subtitle:'To put the saved signature on the pad',
      recordInfo:u.user_name||'',label:'Admin PIN',confirmText:'Sign laayein'});
    if(adminPin==null)return;
    if(!adminPin.trim())return err('The Admin PIN cannot be empty');
    try{
      const r=await SB.rpc('admin_get_user_signature',{p_admin_pin:adminPin.trim(),p_user_id:String(u.id)});
      if(r.error)throw r.error;
      if(!r.data)return err('No saved signature found for this user');
      await sarvDrawSigInto_(ov.querySelector('canvas'),r.data);
      preSig=r.data;
      err('');
      showToast('The saved signature is on the pad and will be kept on Save','ok');
    }catch(e){
      const m=e.message||String(e);
      err(/ADMIN_PIN_INVALID/i.test(m)?'Incorrect Admin PIN'
         :(/admin_get_user_signature|does not exist|schema cache/i.test(m)
            ?'admin_get_user_signature() not found. Run USER_SELF_SERVICE_MIGRATION.sql':m));
    }
  });
  f('cancel').addEventListener('click',close);
  /* Complaint role decides what else applies: host types only for a Host,
     "All units" only for Host / Maintenance / Production Manager. */
  const paintCmp=()=>{
    const r=f('cmprole');if(!r)return;
    const hw=f('hostwrap'),aw=f('allunitswrap'),hint=f('allunitshint');
    if(hw)hw.style.display=r.value==='Host'?'':'none';
    const canAll=SARV_CMP_ALL_UNIT_ROLES.indexOf(r.value)>=0;
    if(aw)aw.style.visibility=canAll?'visible':'hidden';
    if(hint)hint.textContent=r.value==='Host'?'Can be assigned complaints from every unit'
      :canAll?'Sees and assigns every unit\'s complaints':'';
  };
  f('cmprole')?.addEventListener('change',paintCmp);
  paintCmp();
  /* Read the unit / complaint section. Returns {err} or the values. */
  const readUnitForm=()=>{
    if(!sarvUnitReady)return null;
    const pick=ov.querySelector('input[name="sarvUnitPick"]:checked');
    if(!pick)return {err:'Please choose the user\'s Unit (required)'};
    const cr=f('cmprole')?f('cmprole').value:'User';
    const types=[...ov.querySelectorAll('input[data-htype]')].filter(cb=>cb.checked).map(cb=>cb.dataset.htype);
    if(cr==='Host'&&!types.length)return {err:'A Complaint App Host needs at least one complaint type'};
    return {unit:pick.dataset.unit,cmpRole:cr,hostTypes:cr==='Host'?types:[],
      allUnits:SARV_CMP_ALL_UNIT_ROLES.indexOf(cr)>=0&&!!(f('allunits')&&f('allunits').checked),
      dept:(f('cmpdept')?f('cmpdept').value.trim().toUpperCase():''),desig:(f('cmpdesig')?f('cmpdesig').value.trim():'')};
  };
  /* Apps dropdowns: colour shows at a glance what is chosen, plus three
     shortcut buttons (all auto / ON / OFF); setting 18 apps one by one is
     exactly the kind of job nobody does. */
  const appSel=()=>[...ov.querySelectorAll('select[data-app]')];
  const paintApp=s=>{s.style.background=s.value===''?'#fff':(s.value==='1'?'#dcfce7':'#fee2e2');};
  appSel().forEach(s=>s.addEventListener('change',()=>paintApp(s)));
  const setAllApps=v=>appSel().forEach(s=>{s.value=v;paintApp(s);});
  f('appsauto')?.addEventListener('click',()=>setAllApps(''));
  f('appson') ?.addEventListener('click',()=>setAllApps('1'));
  f('appsoff')?.addEventListener('click',()=>setAllApps('0'));
  /* The primary role changed; its checkbox becomes the primary, so the roles
     box has to be rebuilt (otherwise the old primary would stay stuck
     disabled-and-ticked). */
  f('role')?.addEventListener('change',()=>{
    const w=f('roleswrap');if(!w)return;
    const now=f('role').value;
    [...w.querySelectorAll('input[data-role]')].forEach(cb=>{
      const isPrim=cb.dataset.role===now;
      cb.disabled=isPrim;
      if(isPrim)cb.checked=true;
      const lab=cb.closest('label');
      if(lab){
        lab.style.color=isPrim?'#0369a1':'#334155';
        lab.style.cursor=isPrim?'default':'pointer';
        const tag=lab.querySelector('small');
        if(isPrim&&!tag)lab.insertAdjacentHTML('beforeend',' <small style="color:#0369a1;font-weight:700;">(primary)</small>');
        if(!isPrim&&tag)tag.remove();
      }
    });
  });
  // Link to the old Complaint / Packing accounts by name.
  f('applink')?.addEventListener('click',()=>sarvAutolinkProfiles_());
  // Employee Code fills the name / contact from Employee Master.
  f('emp').addEventListener('input',()=>{
    const e=lookupEmployee(f('emp').value);if(!e)return;
    if(!f('name').value.trim())f('name').value=e.person_name||'';
    if(!f('contact').value.trim())f('contact').value=e.contact_no||'';
  });
  f('save').addEventListener('click',async()=>{
    err('');
    const roleV=f('role').value,name=f('name').value.trim().toUpperCase(),pin=f('pin').value,pin2=f('pin2').value;
    if(!roleV)return err('Please select a role');
    if(!name)return err('User Name is required');
    const dup=sarvAppUsers.find(x=>x.role===roleV&&String(x.user_name).toUpperCase()===name&&x.id!==(u&&u.id));
    if(dup)return err('"'+name+'" already exists in this role');
    if(!u&&!pin&&roleV!=='PURCHASER')return err('PIN is required');
    if(pin&&pin.length<4)return err('PIN must be at least 4 digits');
    if(pin!==pin2)return err('PIN and Confirm PIN do not match');
    const uf=readUnitForm();
    if(uf&&uf.err)return err(uf.err);
    /* Order matters: a signature drawn by hand comes first, then the one from
       "Use pre saved Sign", then "remove". `null` means "don't touch the
       signature at all". */
    let sig=null;
    if(pad.hasInk())sig=pad.dataUrl();
    else if(preSig)sig=preSig;
    else if(f('sigdel')&&f('sigdel').checked)sig='';
    const adminPin=await askSecret({title:'Confirm with Admin PIN',subtitle:'To save '+(u?'the user update':'the new user'),
      recordInfo:sarvRoleLabelOf_(roleV)+' — '+name,label:'Admin PIN',confirmText:'Save User'});
    if(adminPin==null)return;
    if(!adminPin.trim())return err('The Admin PIN cannot be empty');
    const btn=f('save');btn.disabled=true;btn.textContent='Saving...';
    try{
      const r=await SB.rpc('admin_save_user',{p_id:u?u.id:null,p_user_name:name,p_role:roleV,
        p_emp_code:f('emp').value.trim().toUpperCase()||null,p_contact_no:f('contact').value.trim()||null,
        p_is_active:f('active').checked,p_new_pin:pin||null,p_signature:sig,p_admin_pin:adminPin.trim()});
      if(r.error)throw r.error;
      // Order Form Role: a separate RPC (admin_save_user is left untouched), same Admin PIN.
      const sroleV=f('srole')?f('srole').value:'';
      let sroleNote='';
      if(sarvSalesRoleReady&&sroleV!==((u&&u.sales_role)||'')){
        await sarvLoadAppUsers_(true);
        const saved=u?sarvAppUsers.find(x=>x.id===u.id):sarvAppUsers.find(x=>x.role===roleV&&String(x.user_name).toUpperCase()===name);
        if(saved){
          const s=await SB.rpc('admin_set_sales_role',{p_admin_pin:adminPin.trim(),p_user_id:String(saved.id),p_sales_role:sroleV||null});
          if(s.error)sroleNote='; Warning: Order Form Role was not saved: '+(s.error.message||s.error);
          else sroleNote=sroleV?' · Order Form: '+sarvSalesRoleLabel_(sroleV):' · Order Form access hataya';
        }
      }
      /* ── Extra roles + Apps: separate RPCs, same Admin PIN ─────────
         admin_save_user() was deliberately left alone (it belongs to
         ADMIN_PANEL_MIGRATION.sql), so these two go after it through their own
         RPCs, the same way the Order Form Role already does. If any of them
         fails, the user has already been saved, so the reason is stated
         clearly in the toast. */
      let uniNote='';
      // The user's id as it stands at the end (creating a Complaint / Packing
      // auth account can move it; see sarvSyncExternalAppAccount_).
      let finalId=u?String(u.id):null;
      if(sarvUnifiedReady){
        await sarvLoadAppUsers_(true);
        const saved=u?sarvAppUsers.find(x=>x.id===u.id)
                     :sarvAppUsers.find(x=>String(x.user_name).toUpperCase()===name
                        &&((x.roles&&x.roles.length)?x.roles.indexOf(roleV)>=0:x.role===roleV));
        if(saved){
          finalId=String(saved.id);
          const rw=f('roleswrap');
          if(rw){
            const picked=[...rw.querySelectorAll('input[data-role]')]
              .filter(cb=>cb.checked||cb.disabled).map(cb=>cb.dataset.role);
            // The primary is always in the list; the server requires it too.
            const roles=[roleV].concat(picked.filter(r=>r!==roleV));
            const rr=await SB.rpc('admin_set_user_roles',
              {p_admin_pin:adminPin.trim(),p_user_id:String(saved.id),p_roles:roles,p_primary_role:roleV});
            if(rr.error||!(rr.data&&rr.data.success))
              uniNote+='; Warning: Roles were not saved: '+((rr.error&&rr.error.message)||(rr.data&&rr.data.error)||'unknown');
            else if(roles.length>1)uniNote+=' · '+roles.length+' roles';
          }
          const aw=f('appswrap');
          if(aw){
            const acc={};
            [...aw.querySelectorAll('select[data-app]')].forEach(s=>{
              if(s.value==='1')acc[s.dataset.app]=true;
              else if(s.value==='0')acc[s.dataset.app]=false;
              // 'auto' is never sent; the absence of the key is what "auto" means
            });
            const ar=await SB.rpc('admin_set_user_app_access',
              {p_admin_pin:adminPin.trim(),p_user_id:String(saved.id),p_app_access:acc});
            if(ar.error||!(ar.data&&ar.data.success))
              uniNote+='; Warning: App access was not saved: '+((ar.error&&ar.error.message)||(ar.data&&ar.data.error)||'unknown');
            else{
              const n=Object.keys(acc).length;
              if(n)uniNote+=' · '+n+' app override';

              /* For Complaint / Packing, writing the jsonb isn't enough: those
                 apps also need their own account, otherwise the user sees
                 "NO_APP_ACCOUNT". That account is created (or deactivated) here.

                 Only on an explicit ON/OFF; 'auto' is left alone, because
                 'auto' means "whatever the role-wise matrix says", and creating
                 an auth account for everyone on that basis would be wrong.

                 One at a time (not Promise.all): when a new auth account is
                 created the user's id changes, and the next call must use that
                 new id. */
              let curId=String(saved.id);
              for(const k of Object.keys(SARV_APP_NEEDS_ACCOUNT)){
                if(typeof acc[k]!=='boolean')continue;
                const res=await sarvSyncExternalAppAccount_(adminPin.trim(),curId,k,acc[k]);
                curId=res.id; uniNote+=res.note;
              }
              finalId=curId;
            }
          }
        }
      }
      /* Unit + Complaint App profile: its own RPC, same Admin PIN, LAST, so it
         lands on the final id. Like the steps above, a failure here leaves the
         user saved and says so in the toast. */
      if(uf){
        if(!finalId){
          await sarvLoadAppUsers_(true);
          const s=sarvAppUsers.find(x=>x.role===roleV&&String(x.user_name).toUpperCase()===name);
          if(s)finalId=String(s.id);
        }
        if(!finalId)uniNote+='; Warning: Unit was not saved (user not found after save). Edit the user and save again.';
        else{
          const ur=await SB.rpc('admin_save_user_unit_profile',{p_admin_pin:adminPin.trim(),p_user_id:finalId,
            p_unit:uf.unit,p_cmp_role:uf.cmpRole,p_host_types:uf.hostTypes,p_all_units:uf.allUnits,
            p_department:uf.dept||null,p_designation:uf.desig||null});
          const ue=(ur.error&&(ur.error.message||String(ur.error)))||(ur.data&&!ur.data.success&&ur.data.error)||'';
          if(ue)uniNote+='; Warning: Unit / Complaint profile was not saved: '
            +(/admin_save_user_unit_profile|PGRST202|schema cache/i.test(ue)?'run UNIT_SIGNUP_ADMIN_MIGRATION.sql':(SARV_UNIT_ERR[ue]||ue));
          else uniNote+=' · '+sarvUnitName_(uf.unit);
        }
      }
      await sarvLoadAppUsers_(true);
      sarvRenderUsers_();
      // If you changed your own access, apply it immediately; otherwise the Admin
      // would have to reload to see their own new access.
      if(sarvCurrentUser&&u&&String(sarvCurrentUser.id)===String(u.id))sarvRefreshSsoSession_().catch(()=>{});
      close();
      const warn=(sroleNote+uniNote).includes('Warning:');
      showToast(''+name+' ('+sarvRoleLabelOf_(roleV)+') '+(u?'updated':'added')+sroleNote+uniNote
        +(roleV==='PURCHASER'?'; now shown in the PR form and mobile login':''),warn?'warn':undefined);
    }catch(e){
      const m=String(e.message||e);
      const map={ADMIN_PIN_INVALID:'Incorrect Admin PIN',PIN_REQUIRED:'This user has no PIN yet. Please enter one.',PIN_TOO_SHORT:'The PIN must be at least 4 digits',
        USER_EXISTS:'This name already exists in this role',ROLE_INVALID:'Invalid role',NAME_ROLE_REQUIRED:'Role and name are required',USER_NOT_FOUND:'User not found. Please refresh.'};
      const k=Object.keys(map).find(x=>m.includes(x));
      err(k?map[k]:(/admin_save_user|does not exist/i.test(m)?'Run ADMIN_PANEL_MIGRATION.sql first':m));
    }finally{btn.disabled=false;btn.innerHTML='Save User';}
  });
  setTimeout(()=>(role?f('name'):f('role')).focus(),30);
}
/* Links to the old Complaint App / Packing accounts by name.
   The benefit: the person's earlier work (assigned tasks, their signature,
   slips they made) stays linked to the new single login. Names that occur
   twice are skipped (no link is better than a wrong link); the Admin can
   link those by hand. */
async function sarvAutolinkProfiles_(){
  if(!isAdmin())return showToast('Admin only','warn');
  const adminPin=await askSecret({title:'Confirm with Admin PIN',
    subtitle:'To link the old Complaint App / Packing accounts',
    recordInfo:'Matched by name; names that occur twice are skipped',
    label:'Admin PIN',confirmText:'Link'});
  if(adminPin==null)return;
  if(!adminPin.trim())return showToast('The Admin PIN cannot be empty','warn');
  try{
    const r=await SB.rpc('admin_autolink_user_profiles',{p_admin_pin:adminPin.trim()});
    if(r.error)throw r.error;
    const d=r.data||{};
    if(!d.success)return showToast(d.error==='ADMIN_PIN_INVALID'?'Incorrect Admin PIN':(''+(d.error||'fail')),'error');
    await sarvLoadAppUsers_(true);sarvRenderUsers_();
    showToast('Linked. Complaint: '+(d.complaint_linked||0)+', Packing: '+(d.packing_linked||0)
      +((d.complaint_linked||d.packing_linked)?'':' (no new matches found)'));
  }catch(e){
    if(/admin_autolink_user_profiles|does not exist/i.test(e.message||''))
      showToast('Run UNIFIED_USERS_MIGRATION.sql first','warn');
    else dbError(e);
  }
}
async function sarvDeleteUser_(id){
  const u=sarvAppUsers.find(x=>x.id===id);if(!u)return;
  if(!confirm('Delete "'+u.user_name+'" ('+sarvRoleLabelOf_(u.role)+')?\n\nTheir PIN and saved signature will be removed too.'+(u.role==='PURCHASER'?'\nThe Purchaser will no longer be able to log in to the mobile app.':'')+'\n\n(To only block them, Edit and untick "Active".)'))return;
  const adminPin=await askSecret({title:'Confirm with Admin PIN',subtitle:'To delete the user',recordInfo:u.user_name,label:'Admin PIN',confirmText:'Delete'});
  if(adminPin==null)return;
  try{
    const r=await SB.rpc('admin_delete_user',{p_id:id,p_admin_pin:adminPin.trim()});
    if(r.error)throw r.error;
    if(!r.data)return showToast('Incorrect Admin PIN; not deleted','error');
    await sarvLoadAppUsers_(true);sarvRenderUsers_();
    showToast(''+u.user_name+' deleted');
  }catch(e){dbError(e);}
}

/* ── Sign with PIN ──────────────────────────────────────────────────
   The signature a user drew once (Users & Roles) is put on a pad by typing
   their PIN — get_user_signature() returns it only for the right PIN.
   Resolves {dataUrl,name} or null when cancelled. */
async function sarvPinSign(opts={}){
  await sarvLoadAppUsers_();
  if(sarvAppUsersMissing){if(!opts.quiet)showToast('Run ADMIN_PANEL_MIGRATION.sql first','warn');return null;}
  let users=sarvAppUsers.filter(u=>u.is_active&&u.has_signature);
  if(opts.roles&&opts.roles.length){const f=users.filter(u=>opts.roles.includes(u.role));if(f.length||opts.strictRoles)users=f;}
  if(!users.length){if(!opts.quiet)showToast('No user has a saved signature. Set one up under Admin Panel › Users & Roles.','warn');return null;}
  const pre=(sarvCurrentUser&&users.find(u=>u.id===sarvCurrentUser.id))?sarvCurrentUser.id:(users.length===1?users[0].id:'');
  return new Promise(resolve=>{
    const ov=document.createElement('div');
    ov.className='sarv-ov';
    ov.innerHTML='<div class="card" style="max-width:400px;"><div class="hd">PIN se Sign — '+escText(opts.title||'Digital Signature')+'</div><div class="bd">'
      +'<div class="err" data-f="err"></div>'
      +'<div class="fg"><label>User</label><select data-f="user"><option value="">-- Select --</option>'
      +users.map(u=>'<option value="'+escText(u.id)+'"'+(u.id===pre?' selected':'')+'>'+escText(u.user_name)+' ('+escText(sarvRoleLabelOf_(u.role))+')</option>').join('')+'</select></div>'
      +'<div class="fg"><label>Your PIN</label><input data-f="pin" type="password" inputmode="numeric" autocomplete="off" placeholder="Enter PIN"></div>'
      +'<div style="font-size:11px;color:#64748b;">'+escText(opts.note||'With the correct PIN your saved signature will be placed on the pad.')+'</div>'
      +'</div><div class="ft"><button type="button" class="b no" data-f="cancel">Cancel</button><button type="button" class="b ok" data-f="ok">Sign</button></div></div>';
    document.body.appendChild(ov);
    const f=k=>ov.querySelector('[data-f="'+k+'"]');
    const done=v=>{document.removeEventListener('keydown',onKey,true);ov.remove();resolve(v);};
    const submit=async()=>{
      const id=f('user').value,pin=f('pin').value,er=f('err');
      er.style.display='none';
      if(!id){er.textContent='Please select a user';er.style.display='block';return;}
      if(!pin){er.textContent='Please enter your PIN';er.style.display='block';return;}
      f('ok').disabled=true;
      try{
        const r=await SB.rpc('get_user_signature',{p_user_id:id,p_pin:pin});
        if(r.error)throw r.error;
        if(!r.data){er.textContent='Incorrect PIN';er.style.display='block';f('pin').select();return;}
        done({dataUrl:r.data,name:(users.find(u=>u.id===id)||{}).user_name||''});
      }catch(e){er.textContent=e.message||String(e);er.style.display='block';}
      finally{if(f('ok'))f('ok').disabled=false;}
    };
    const onKey=e=>{if(e.key==='Escape'){e.preventDefault();done(null);}else if(e.key==='Enter'){e.preventDefault();submit();}};
    document.addEventListener('keydown',onKey,true);
    f('cancel').addEventListener('click',()=>done(null));
    f('ok').addEventListener('click',submit);
    setTimeout(()=>(pre?f('pin'):f('user')).focus(),30);
  });
}
/* A "PIN se Sign" button beside the Clear button of each signature pad. */
function sarvAttachPinSign_(clearBtnId,canvasId,timeFieldId,title,roles,canUse){
  const clr=byId(clearBtnId);if(!clr||clr.dataset.pinSign)return;
  clr.dataset.pinSign='1';
  const b=document.createElement('button');
  b.type='button';b.className='sarv-pinsign-btn';b.innerHTML='PIN se Sign';
  b.title='Enter your PIN instead of drawing; your saved signature will be applied';
  b.style.marginRight='6px';
  clr.parentNode.insertBefore(b,clr);
  b.addEventListener('click',async()=>{
    const c=byId(canvasId);if(!c)return;
    if(canUse&&!canUse(c))return;
    const r=await sarvPinSign({title,roles});if(!r)return;
    try{
      await sarvDrawSigInto_(c,r.dataUrl);
      const tf=byId(timeFieldId);if(tf)tf.textContent=pStamp()+' — '+r.name;
      showToast(''+r.name+'\'s signature applied');
    }catch(e){showToast(e.message||String(e),'error');}
  });
}

/* ── PIN-only pads ───────────────────────────────────────────────────
   Once the logged-in user's sign is saved, the Store In-Charge draw pads
   (Build PO, Vendor Rate & Info) are not shown at all: the confirm button asks
   their PIN and lays the saved sign onto the (hidden) canvas, then carries on
   exactly as if it had been drawn. A user with no saved sign — or whose PIN
   brings none back — gets the pad as before. */
const SARV_PIN_PADS=[
  {canvas:'p_poStoreSignCanvas',time:'p_poStoreSignTimeField',confirm:'p_poBuildConfirmBtn',title:'Generate PO'},
  {canvas:'p_viSignCanvas',time:'p_viSignTimeField',confirm:'p_viSaveBtn',title:'Save Vendor Info',can:()=>sarvCan('VENDOR_INFO_DESK')}
];
let sarvPadForceDraw=false;   // set when a PIN brought back no sign — show the pad again
function sarvPadPinMode_(){
  const id=sarvCurrentUser&&sarvCurrentUser.id;
  return !sarvPadForceDraw&&!!(id&&sarvAppUsers.some(u=>u.id===id&&u.is_active&&u.has_signature));
}
function sarvApplyPadPinMode_(){
  const on=sarvPadPinMode_();
  SARV_PIN_PADS.forEach(p=>{
    const c=byId(p.canvas);if(!c||!c.parentElement)return;
    const pad=c.parentElement;
    pad.style.display=on?'none':'';
    let note=byId(p.canvas+'_pinNote');
    if(!note){
      note=document.createElement('div');
      note.id=p.canvas+'_pinNote';
      note.style.cssText='padding:10px 12px;border:1px solid #c4b5fd;background:#f5f3ff;border-radius:6px;font-size:12px;font-weight:700;color:#5b21b6;';
      note.innerHTML='Your signature is saved. Press <b>'+escText(p.title)+'</b> and enter your PIN; the signature is applied automatically.';
      pad.parentNode.insertBefore(note,pad.nextSibling);
    }
    note.style.display=on?'':'none';
  });
}
function sarvBindPinPads_(){
  SARV_PIN_PADS.forEach(p=>{
    // Document capture: runs before the button's own handler in every browser;
    // that handler only sees the click again (pinPass) once the saved sign is
    // on the canvas.
    document.addEventListener('click',async e=>{
      const b=e.target&&e.target.closest&&e.target.closest('#'+p.confirm);
      if(!b||b.disabled)return;
      if(b.dataset.pinPass==='1'){delete b.dataset.pinPass;return;}
      if(!sarvPadPinMode_()||(p.can&&!p.can()))return;
      e.preventDefault();e.stopImmediatePropagation();
      const r=await sarvSubmitPinGate_(p.title);
      if(!r)return;
      const c=byId(p.canvas);
      if(!r.dataUrl||!c){
        sarvPadForceDraw=true;sarvApplyPadPinMode_();
        return showToast('No saved signature found for this user. Sign on the pad and press again.','warn');
      }
      try{await sarvDrawSigInto_(c,r.dataUrl);}
      catch(err){sarvPadForceDraw=true;sarvApplyPadPinMode_();return showToast('The saved signature did not load. Please sign on the pad.','warn');}
      const tf=byId(p.time);if(tf)tf.textContent=pStamp()+' — '+r.name;
      b.dataset.pinPass='1';
      b.click();
    },true);
  });
}

document.addEventListener('DOMContentLoaded',()=>{
  sarvBindPinPads_();
  // Admin Panel controls
  document.querySelectorAll('#sarvAdminPanel .ap-tab').forEach(b=>b.addEventListener('click',()=>sarvShowApPane_(b.dataset.ap)));
  byId('ap_fullScreenBtn')?.addEventListener('click',()=>sarvApFullScreen_(!byId('sarvAdminPanel')?.classList.contains('ap-full')));
  // Esc leaves full screen — unless a popup on top of it (user form, PIN) owns the key.
  document.addEventListener('keydown',e=>{
    if(e.key!=='Escape'||!byId('sarvAdminPanel')?.classList.contains('ap-full'))return;
    if(document.querySelector('.sarv-ov')||byId('pwdGateModal')?.style.display==='flex')return;
    sarvApFullScreen_(false);
  });
  byId('ap_addUserBtn')?.addEventListener('click',()=>sarvOpenUserModal(null));
  byId('ap_addPurchaserBtn')?.addEventListener('click',()=>sarvOpenUserModal(null,'PURCHASER'));
  byId('ap_reloadUsersBtn')?.addEventListener('click',()=>sarvLoadAppUsers_(true).then(sarvRenderUsers_));
  byId('ap_userRoleFilter')?.addEventListener('change',sarvRenderUsers_);
  byId('ap_userUnitFilter')?.addEventListener('change',sarvRenderUsers_);
  byId('ap_userSearch')?.addEventListener('input',sarvRenderUsers_);
  byId('ap_usersBody')?.addEventListener('click',e=>{
    const ed=e.target.closest('[data-ap-edit]');if(ed)return sarvOpenUserModal(ed.dataset.apEdit);
    const dl=e.target.closest('[data-ap-del]');if(dl)sarvDeleteUser_(dl.dataset.apDel);
  });
  ['ap_permMatrix','ap_tabMatrix'].forEach(id=>byId(id)?.addEventListener('click',sarvMatrixClick_));
  byId('ap_permSaveBtn')?.addEventListener('click',()=>sarvSaveMatrix_('perms'));
  byId('ap_tabSaveBtn')?.addEventListener('click',()=>sarvSaveMatrix_('tabs'));
  byId('ap_permResetBtn')?.addEventListener('click',()=>{sarvApDraft.perms=sarvFullMatrix_(null,SARV_FEATURES);sarvRenderMatrix_('ap_permMatrix',SARV_FEATURES,'perms');showToast('Defaults restored; they apply when you press Save');});
  byId('ap_tabResetBtn')?.addEventListener('click',()=>{sarvApDraft.tabs=sarvFullMatrix_(null,SARV_TABS);sarvRenderMatrix_('ap_tabMatrix',SARV_TABS,'tabs');showToast('Defaults restored; they apply when you press Save');});
  // PIN-sign on the two Store Incharge pads
  sarvAttachPinSign_('p_poStoreSignClearBtn','p_poStoreSignCanvas','p_poStoreSignTimeField','Store Incharge (PO)',['USER_IC_PIN','ADMIN_PIN']);
  sarvAttachPinSign_('p_viSignClearBtn','p_viSignCanvas','p_viSignTimeField','Store Incharge (Vendor Info)',['USER_IC_PIN','ADMIN_PIN'],
    c=>{if(c.style.pointerEvents==='none'){sarvDeny('VENDOR_INFO_DESK');return false;}return true;});
  sarvApplyAccess();
  sarvLoadSettings_();
  sarvLoadAppUsers_();
  /* The fixed dropdown values apply to forms across the whole app (Inward's
     Party State, the PR's Department, the Item Master's Category/UOM/GST …),
     so they can't wait for Master Data to be opened; they load at startup. If
     the table isn't found, the code defaults keep working. */
  sarvLoadDropdowns_();
});

/* ================================================================
   SIGNATURE CANVAS ENGINE
================================================================ */
(function initSignatureEngine(){
  let drawing=false, ctx=null, canvas=null;
  function getCanvas(){ return canvas||(canvas=byId('signatureCanvas')); }
  function getCtx(){
    if(ctx) return ctx;
    const c=getCanvas(); if(!c) return null;
    ctx=c.getContext('2d');
    ctx.strokeStyle='#0f172a'; ctx.lineWidth=2.2;
    ctx.lineCap='round'; ctx.lineJoin='round';
    return ctx;
  }
  function pos(e,c){
    const r=c.getBoundingClientRect();
    const src=e.touches?e.touches[0]:e;
    return {x:src.clientX-r.left, y:src.clientY-r.top};
  }
  function onDown(e){
    e.preventDefault(); drawing=true;
    const c=getCanvas(); const cx=getCtx(); if(!c||!cx) return;
    const p=pos(e,c); cx.beginPath(); cx.moveTo(p.x,p.y);
  }
  function onMove(e){
    e.preventDefault(); if(!drawing) return;
    const c=getCanvas(); const cx=getCtx(); if(!c||!cx) return;
    const p=pos(e,c); cx.lineTo(p.x,p.y); cx.stroke();
  }
  function onUp(e){ drawing=false; }
  function bindCanvas(){
    const c=getCanvas(); if(!c||c.dataset.sigBound) return;
    c.addEventListener('mousedown',onDown); c.addEventListener('mousemove',onMove);
    c.addEventListener('mouseup',onUp); c.addEventListener('mouseleave',onUp);
    c.addEventListener('touchstart',onDown,{passive:false});
    c.addEventListener('touchmove',onMove,{passive:false});
    c.addEventListener('touchend',onUp);
    c.dataset.sigBound='1';
  }
  // Override stubs
  window.clearCanvas=function(){
    const c=getCanvas(); if(!c) return;
    bindCanvas();
    getCtx()?.clearRect(0,0,c.width,c.height);
  };
  window.getSignatureDataUrl=function(){
    const c=getCanvas(); if(!c) return '';
    return c.toDataURL('image/png');
  };
  window.isSignatureEmpty=function(){
    const c=getCanvas(); if(!c) return true;
    const data=c.getContext('2d').getImageData(0,0,c.width,c.height).data;
    return !data.some(v=>v!==0);
  };
  // Bind when modal opens
  const mo=new MutationObserver(()=>{ const c=getCanvas(); if(c) bindCanvas(); });
  document.addEventListener('DOMContentLoaded',()=>{
    const modal=byId('drawSignatureModal');
    if(modal) mo.observe(modal,{attributes:true,attributeFilter:['style']});
    const clrBtn=byId('clearCanvasBtn');
    if(clrBtn&&!clrBtn.dataset.sigBound){ clrBtn.addEventListener('click',window.clearCanvas); clrBtn.dataset.sigBound='1'; }
    bindCanvas();
  });
})();

/* ================================================================
   PHOTO PREVIEW ENGINE (Inward + Outward)
================================================================ */
(function initPhotoEngine(){
  const stores={inward:{camera:'inwPhotoCameraInput',gallery:'inwPhotoGalleryInput',preview:'inwPhotoPreview',count:'inwPhotoCount',files:[]},outward:{camera:'outPhotoCameraInput',gallery:'outPhotoGalleryInput',preview:'outPhotoPreview',count:'outPhotoCount',files:[]}};

  function renderPreviews(key){
    const s=stores[key];
    const box=byId(s.preview); const cnt=byId(s.count);
    if(!box) return;
    box.innerHTML=s.files.map((f,i)=>`
      <div style="position:relative;width:80px;height:80px;border-radius:6px;overflow:hidden;border:1.5px solid #cbd5e1;flex-shrink:0;">
        <img src="${f.dataUrl}" style="width:100%;height:100%;object-fit:cover;">
        <button onclick="removePhotoAt('${key}',${i})" style="position:absolute;top:2px;right:2px;background:rgba(0,0,0,0.6);color:#fff;border:none;border-radius:50%;width:18px;height:18px;font-size:10px;cursor:pointer;line-height:18px;text-align:center;padding:0;">✕</button>
        <div style="position:absolute;bottom:0;left:0;right:0;background:rgba(0,0,0,0.5);color:#fff;font-size:8px;padding:2px 4px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;">${f.name}</div>
      </div>`).join('');
    if(cnt) cnt.textContent=s.files.length?s.files.length+' photo'+(s.files.length>1?'s':''):'' ;
  }

  function addFiles(key, fileList){
    const s=stores[key];
    const newFiles=[...fileList].filter(f=>f.type.startsWith('image/'));
    const readers=newFiles.map(f=>new Promise(res=>{
      const r=new FileReader();
      r.onload=()=>res({name:f.name,type:f.type,dataUrl:r.result,file:f});
      r.onerror=()=>res(null);
      r.readAsDataURL(f);
    }));
    Promise.all(readers).then(results=>{
      s.files=[...s.files,...results.filter(Boolean)];
      renderPreviews(key);
    });
  }

  window.removePhotoAt=function(key,idx){
    if(!stores[key]) return;
    stores[key].files.splice(idx,1);
    renderPreviews(key);
  };

  window.getPhotos=function(key){ return stores[key]?.files||[]; };
  // Entry Type drafts (makeEntryDrafts_): hand the current photos over to a
  // draft and empty the preview, then give a draft's photos back.
  window.takePhotos=function(key){
    if(!stores[key])return [];
    const files=stores[key].files;stores[key].files=[];renderPreviews(key);return files;
  };
  window.putPhotos=function(key,files){
    if(!stores[key])return;
    stores[key].files=files||[];renderPreviews(key);
  };
  // Used by clearInwardForm / clearOutwardForm after a save — without this the
  // store kept the previous entry's photos and attached them to the next one.
  window.clearPhotos=function(key){
    if(!stores[key])return;
    stores[key].files=[];
    const cam=byId(stores[key].camera),gal=byId(stores[key].gallery);
    if(cam)cam.value=''; if(gal)gal.value='';
    renderPreviews(key);
  };

  document.addEventListener('DOMContentLoaded',()=>{
    Object.entries(stores).forEach(([key,s])=>{
      const cam=byId(s.camera); const gal=byId(s.gallery);
      if(cam&&!cam.dataset.photoBound){ cam.addEventListener('change',e=>addFiles(key,e.target.files)); cam.dataset.photoBound='1'; }
      if(gal&&!gal.dataset.photoBound){ gal.addEventListener('change',e=>addFiles(key,e.target.files)); gal.dataset.photoBound='1'; }
    });
    // Live billing recalc on freight + roundoff + party state change
    ['freightExp','roundOffInput','partyState'].forEach(id=>{
      const el=byId(id);
      if(el&&!el.dataset.billBound){ el.addEventListener('input',updateStoreTotals); el.addEventListener('change',updateStoreTotals); el.dataset.billBound='1'; }
    });
    ['calcGrossWeight','calcFreightRate'].forEach(id=>{
      const el=byId(id);
      if(el&&!el.dataset.frtBound){ el.addEventListener('input',updateStoreTotals); el.dataset.frtBound='1'; }
    });
  });
})();

/* ================================================================
   MASTER DATA — Item Master (Full Implementation)
================================================================ */
// Supabase/PostgREST caps a single request at ~1000 rows by default — with
// more items or ledger lines than that, a plain .select() would silently
// return only a partial dataset. This pages through .range() until a page
// comes back short, so callers always get every row.
async function fetchAllRows(table,selectCols,orderCol,filterFn){
  const PAGE=1000;
  let from=0,all=[];
  for(;;){
    let q=SB.from(table).select(selectCols);
    if(filterFn)q=filterFn(q);
    q=q.range(from,from+PAGE-1);
    if(orderCol)q=q.order(orderCol);
    const {data,error}=await q;
    if(error)throw error;
    all=all.concat(data||[]);
    if(!data||data.length<PAGE)break;
    from+=PAGE;
  }
  return all;
}

// Item Master table state — cached in full (see fetchAllRows) so the
// search box and Category filter both run instantly over the complete
// dataset instead of re-querying Supabase on every keystroke/click.
let sarvItemMasterRows=[];      // [{it, inQty, outQty, bal, catKey}]
/* The subset of the above that is ON SCREEN right now — after the search box,
   the Stock dropdown and every column filter, in the order the column sort put
   it in. Written by renderItemMasterTable and read by the Download CSV / PDF
   buttons, so an export is always of the list being looked at and never of a
   separately re-derived one. */
let sarvItemMasterShown=[];
// Last-loaded master rows, kept so each panel's search box can re-render from
// memory instead of refetching on every keystroke — same pattern as
// sarvItemMasterRows / renderItemMasterTable above.
let sarvSupplierMasterRows=[], sarvEmployeeMasterRows=[], sarvMachineMasterRows=[];

/* ================================================================
   ITEM MASTER — COLLAPSIBLE ADD FORM + FULL-HEIGHT LIST
   ----------------------------------------------------------------
   Two halves of the same idea: this tab is opened far more often to
   LOOK something up than to add a part, so the list gets the screen
   and the form gets out of the way until it is asked for.
================================================================ */
const IM_ADD_FORM_KEY='sarv_im_addform_open';
function isAddItemFormOpen_(){
  const b=byId('mi_formBody');
  return !!b&&b.style.display!=='none';
}
/* open===undefined flips it. remember===false opens it WITHOUT changing the
   saved preference — that is for the Edit button, which has to show the form
   whatever the user normally keeps it at, but should not quietly decide they
   now want it open every visit. The list is re-fitted afterwards, because the
   form opening or closing is exactly what changes how much room is left. */
window.setAddItemForm=function(open,remember){
  const body=byId('mi_formBody'),head=byId('mi_formToggle'),hint=byId('mi_formHint');
  if(!body)return;
  const want=(open===undefined)?!isAddItemFormOpen_():!!open;
  body.style.display=want?'block':'none';
  if(head)head.classList.toggle('open',want);
  if(hint)hint.textContent=want?'Click to close':'Click to open';
  if(remember!==false){try{localStorage.setItem(IM_ADD_FORM_KEY,want?'1':'0');}catch(e){}}
  fitItemListHeight_();
};
window.toggleAddItemForm=function(){setAddItemForm();};
/* Restores the remembered state. Default CLOSED on a browser that has never
   been told otherwise — the list is the reason people come here. */
function initAddItemForm_(){
  let open=false;
  try{open=localStorage.getItem(IM_ADD_FORM_KEY)==='1';}catch(e){}
  setAddItemForm(open);
  /* Live "name already taken" check on Item Name. Bound once — this runs on
     every panel open and after every save (cancelItemEdit calls it), so a
     fresh listener each time would stack up. */
  const nameBox=byId('mi_itemName');
  if(nameBox&&!nameBox.dataset.miDupBound){
    ['input','change'].forEach(ev=>nameBox.addEventListener(ev,miSyncItemNameHint_));
    nameBox.dataset.miDupBound='1';
  }
  // Also clears the hint on the way through, which is what a cleared form needs.
  miSyncItemNameHint_();
  /* The header's sort / filter wiring, re-asserted every time this panel is
     shown. Idempotent, and belt-and-braces: if store-core.js happened to
     evaluate before the Item Master markup was parsed, the DOMContentLoaded
     binding would have found no <thead> — this is the path that catches it. */
  initItemMasterHeader_();
}
/* Gives the item list every pixel left below it, measured rather than guessed.
   A fixed calc(100vh - 320px) could not know how tall the toolbar had wrapped
   on a narrow window, whether the filter chips were showing, or whether the Add
   form was open — so it was either too short (a letterbox in the middle of the
   page) or too tall (the last rows unreachable under the viewport).
   Called on load, on every toggle, on resize, and whenever the tab is shown. */
function fitItemListHeight_(){
  const box=byId('itemMasterBox');
  if(!box||!box.offsetParent)return;        // tab not visible — nothing to measure
  const top=box.getBoundingClientRect().top;
  // Breathing room under the table so the card's own border/padding is not
  // pressed against the bottom of the window.
  const h=Math.max(220,Math.round(window.innerHeight-top-24));
  /* maxHeight only, never a fixed height: a short list should shrink to its
     rows rather than leave a tall empty box under them. The scrollbar gutter
     is reserved regardless (overflow-y:scroll in the CSS), so the columns do
     not shift when the list crosses from fitting to not fitting. */
  box.style.maxHeight=h+'px';
}
window.addEventListener('resize',fitItemListHeight_);

/* ══ MASTER DATA: FULL SCREEN / HIDE TOP ════════════════════════════════
   Two switches at the end of the Master Data tab strip, the same for every tab:
     • Full screen — the panel covers the whole window (above the app header);
       Esc or the button again brings it back. Not remembered: a reload opens
       the normal view.
     • Hide top    — hides the panel title and every block marked data-md-top
       in index.html (the Add New … forms and the notice boxes). The search /
       filter bar right above each table stays, so search keeps working.
       Remembered per browser.
   In either mode every table's scroll box is stretched to the bottom of the
   window (mdFitTables_), so the extra room goes to rows. */
const MD_HIDE_KEY='sarv_md_hidetop';
let sarvMdFull=false;
function mdHideTop_(){try{return localStorage.getItem(MD_HIDE_KEY)==='1'}catch(e){return false}}
function mdApplyView_(){
  const p=byId('masterDataPanel');if(!p)return;
  const hide=mdHideTop_();
  p.classList.toggle('md-fs',sarvMdFull);
  p.classList.toggle('md-hidetop',hide);
  const hb=byId('mdHideTopBtn'),fb=byId('mdFullBtn');
  if(hb){hb.textContent=hide?'Show top':'Hide top';hb.classList.toggle('on',hide);hb.setAttribute('aria-pressed',hide?'true':'false');}
  if(fb){fb.textContent=sarvMdFull?'Exit full screen':'Full screen';fb.classList.toggle('on',sarvMdFull);fb.setAttribute('aria-pressed',sarvMdFull?'true':'false');}
  setTimeout(mdFitTables_,0);
}
window.mdToggleView=function(which){
  if(which==='fs')sarvMdFull=!sarvMdFull;
  else{try{localStorage.setItem(MD_HIDE_KEY,mdHideTop_()?'0':'1')}catch(e){}}
  mdApplyView_();
};
// Each table's scroll box: to the bottom of the window while a mode is on,
// back to its own height (the inline / stylesheet one) when both are off.
function mdFitTables_(){
  const p=byId('masterDataPanel');if(!p||p.style.display==='none')return;
  fitItemListHeight_();              // Item Master always fits the window already
  const on=p.classList.contains('md-fs')||p.classList.contains('md-hidetop');
  p.querySelectorAll('.table-container,.fbm-wrap,.dd-side').forEach(box=>{
    if(box.id==='itemMasterBox')return;
    if(box.dataset.mdMax==null)box.dataset.mdMax=box.style.maxHeight||'';
    if(!on||!box.offsetParent){box.style.maxHeight=box.dataset.mdMax;return;}
    const top=box.getBoundingClientRect().top;
    box.style.maxHeight=Math.max(240,Math.round(window.innerHeight-top-18))+'px';
  });
}
window.addEventListener('resize',mdFitTables_);
document.addEventListener('keydown',e=>{
  if(e.key!=='Escape'||!sarvMdFull)return;
  const p=byId('masterDataPanel');if(!p||p.style.display==='none')return;
  // Esc first closes whatever popup is open on top (filter panel, modal …).
  const popup=[...document.querySelectorAll('.secure-modal-overlay,.modal.active,#imFilterPanel,#sarvDmyCal')]
    .some(x=>getComputedStyle(x).display!=='none'&&x.getBoundingClientRect().width>0);
  if(popup)return;
  sarvMdFull=false;mdApplyView_();
});
document.addEventListener('DOMContentLoaded',mdApplyView_);

/* ================================================================
   ITEM MASTER — PER-COLUMN FILTERS (Excel-style, and DEPENDENT)
   ----------------------------------------------------------------
   Every column header carries a ▾ button. It opens a list of the
   values actually present in that column, each tickable, plus a
   Min / Max pair on the numeric columns. Apply commits it; Remove
   Filter clears that one column; the chip bar under the toolbar
   clears any of them, or all at once.

   DEPENDENT is the point of it. The list a column offers is built
   from the rows that survive EVERY OTHER filter — the search box
   and the Stock (MSV) dropdown included — never from the full
   table. So picking Category = ELECTRICAL leaves the Make list
   showing only the makes that actually occur in ELECTRICAL items,
   and a combination that would return nothing is simply not
   offered. The one exception is a value that is already ticked:
   it stays listed, greyed, even when the other filters have taken
   every row carrying it, because a value you cannot see is a value
   you can never untick.

   This replaced the standalone Category dropdown that used to sit
   in the toolbar. Category is a column like any other now; two
   Category filters that both applied would have been a trap.
================================================================ */
/* How each filterable column is read. `get` returns the value used for
   matching and grouping — null meaning "not set", which is offered in the
   list as (Blank) so "show me the items with no Material" is askable.
   `numeric` adds the Min / Max row and sorts the value list by number. */
const SARV_IM_FILTER_COLS={
  code:{label:'Code',               numeric:false,get:r=>r.it.item_code},
  name:{label:'Item Name',          numeric:false,get:r=>r.it.name},
  desc:{label:'Description',        numeric:false,get:r=>r.it.description},
  cat: {label:'Category',           numeric:false,get:r=>r.catKey},
  size:{label:'Size',               numeric:false,get:r=>itemSize_(r.it)},
  mat: {label:'Material',           numeric:false,get:r=>itemMaterial_(r.it)},
  rate:{label:'Rate',               numeric:true, get:r=>Number(r.it.rate||0)},
  gst: {label:'GST %',              numeric:true, get:r=>itemGst_(r.it)},
  uom: {label:'UOM',                numeric:false,get:r=>r.it.uom||'PCS'},
  make:{label:'Make',               numeric:false,get:r=>r.it.make},
  msv: {label:'MIN STOCK QTY (MSV)',numeric:true, get:r=>itemMsv_(r.it)},
  soq: {label:'STD ORDER QTY',      numeric:true, get:r=>itemStdOrderQty_(r.it)},
  xtol:{label:'PO EXCESS ALLOWED %',numeric:true, get:r=>itemExcessTol_(r.it)},
  in:  {label:'IN Qty',             numeric:true, get:r=>r.inQty},
  out: {label:'OUT Qty',            numeric:true, get:r=>r.outQty},
  bal: {label:'Balance Qty',        numeric:true, get:r=>r.bal},
  // null until the background PR / PO lookup lands (imLoadPipeline_), then a
  // number, 0 included: "nothing pending" is a value you can filter on.
  pipe:{label:'Pending PR / PO Qty',numeric:true, get:r=>r.pipe==null?null:r.pipe}
};
const IM_BLANK='(Blank)';
/* Applied filters, by column id: {values:Set<string>|null, min:number|null,
   max:number|null}. values===null means no value restriction — different from
   an empty Set, which means "nothing ticked", i.e. show nothing. */
let sarvImFilters={};
// Which column's panel is open, and the state being edited in it. Kept apart
// from sarvImFilters so Cancel really cancels.
let sarvImPanelCol=null, sarvImDraft=null;

// The display string a value is grouped and matched under. One function, used
// by the option list, the row test and the chip labels alike, so the three can
// never disagree about what "4" or "" means.
function imCellKey_(col,row){
  const v=SARV_IM_FILTER_COLS[col].get(row);
  if(v==null||String(v).trim()==='')return IM_BLANK;
  return String(v).trim();
}
// Numeric value for the Min / Max test. null = nothing to compare, which a
// range always rejects (an item with no MSV is neither above nor below one).
function imCellNum_(col,row){
  if(!SARV_IM_FILTER_COLS[col].numeric)return null;
  const v=SARV_IM_FILTER_COLS[col].get(row);
  if(v==null||String(v).trim()==='')return null;
  const n=Number(v);
  return isNaN(n)?null:n;
}
function imHasFilter_(col){
  const f=sarvImFilters[col];
  return !!f&&(f.values!=null||f.min!=null||f.max!=null);
}
function imActiveCols_(){return Object.keys(SARV_IM_FILTER_COLS).filter(imHasFilter_)}
function imColPass_(col,row){
  const f=sarvImFilters[col];
  if(!f)return true;
  if(f.values&&!f.values.has(imCellKey_(col,row)))return false;
  if(f.min!=null||f.max!=null){
    const n=imCellNum_(col,row);
    if(n==null)return false;
    if(f.min!=null&&n<f.min)return false;
    if(f.max!=null&&n>f.max)return false;
  }
  return true;
}
/* The non-column filters — the search box and the Stock/MSV dropdown. Pulled
   out so the dependent option lists apply them too; a value that only occurs
   in rows the search has already hidden is not a value worth offering.
   The slicer buttons sit here too, for the same reason. slicerExcept leaves
   one slicer column out — only the slicer bar's own counts use it. */
function imBasePass_(row,slicerExcept){
  if(!imSlicerPass_(row,slicerExcept))return false;
  const q=(byId('itemMasterSearch')?.value||'').toLowerCase().trim();
  const msvFilter=byId('itemMasterMsvFilter')?.value||'ALL';
  if(msvFilter!=='ALL'){
    const msv=itemMsv_(row.it);
    // No MSV set — there is nothing to be below or above, so it shows in neither.
    if(msv==null||msv<=0)return false;
    if(msvFilter==='BELOW'&&!(row.bal<msv))return false;
    if(msvFilter==='ABOVE'&&!(row.bal>=msv))return false;
  }
  if(q){
    const hay=[row.it.item_code,row.it.name,row.it.description,row.it.category,row.it.sub_category,row.it.make,
      row.it.item_size,row.it.material_type].map(x=>String(x||'').toLowerCase()).join(' ');
    if(!hay.includes(q))return false;
  }
  return true;
}
// exceptCol is what makes the filters dependent: a column's own filter is left
// out when working out what that column should still be offering.
function imRowPass_(row,exceptCol){
  if(!imBasePass_(row))return false;
  return Object.keys(SARV_IM_FILTER_COLS).every(c=>c===exceptCol||imColPass_(c,row));
}

/* ══ ITEM MASTER: SLICER BUTTONS ═════════════════════════════════════
   Excel-style slicers: one-click buttons above the list, by column. The
   values come from Dropdown Master: each slicer column has its own key
   (erp_imSlicer_<col>) in `sales_dropdowns`. So adding a new slicer needs
   neither SQL nor code: in Dropdown Master › Item Master › Slicer Buttons,
   choose the column (that is the slicer's heading) and add a value.

   Rules, as in Excel slicers:
     * several buttons within one column = OR  (Category: YARN or FABRIC)
     * across different columns          = AND
     * also AND with the search, Stock and ▾ column filters
   On Item Name / Description a button matches "contains the word": writing
   the full name in a slicer would be pointless, and "BEARING" should bring
   up every bearing. Other columns match the whole value, ignoring case.

   The code default is EMPTY: until the Admin adds a slicer the bar doesn't
   show at all (the Admin just sees a "set up" link). A chosen slicer
   survives Refresh (like the column filters) but not a page reload. */
const IM_SLICER_COLS=['cat','size','mat','uom','make','gst','code','name','desc'];
const IM_SLICER_CONTAINS={name:1,desc:1};
const imSlicerKey_=col=>'erp_imSlicer_'+col;
// col -> Set of slicer values, exactly as Dropdown Master holds them.
let sarvImSlicerSel={};

// GST "18%" and "18" are the same; the button works even if the Admin types the %.
function imSlNorm_(col,v){
  let s=String(v==null?'':v).trim().toUpperCase();
  if(col==='gst')s=s.replace(/\s*%$/,'');
  return s;
}
/* The defined slicers, in column order: [{col, values:[…]}]. If Dropdown
   Master hasn't loaded yet (or the table doesn't exist), empty: the bar
   hides and the list is unaffected. */
/* ── Slicers made from a column's own VALUES ──────────────────────────
   The per-column route above needs every button typed in by an Admin.
   For the columns that hold a short list of repeating values, the Admin can
   instead tick the whole column (one or several) and get one button per
   distinct value actually present in the Item Master —
   a new Category or Make shows up as a button the moment an item carries
   it. One column or several; several behave as above (OR within a column,
   AND across columns). Name / Description / Code are left out: they are
   different on nearly every row, so a button per value would be the list
   itself. The choice is made ONCE, by an Admin, in Dropdown Master › Item
   Master › Slicer Buttons › "Slicer Columns (one button per value)" — key
   erp_imSlicerAutoCols, one row per column — so every login sees the same
   slicers. My Day's Below-MSV list reads the same choice. A row may hold the
   column key (cat) or its label (Category); both are accepted. */
const IM_SLICER_AUTO_COLS=['cat','size','mat','uom','make','gst'];
const IM_SLICER_AUTO_DD_KEY='erp_imSlicerAutoCols';
function imSlicerAutoCols_(){
  try{
    const want=new Set(sarvDropdownList(IM_SLICER_AUTO_DD_KEY).map(v=>String(v==null?'':v).trim().toUpperCase()));
    return IM_SLICER_AUTO_COLS.filter(c=>want.has(c.toUpperCase())||want.has(String(SARV_IM_FILTER_COLS[c].label).toUpperCase()));
  }catch(e){return [];}
}
// Distinct non-blank values of one column across `rows`, in natural order
// (ITEM-2 before ITEM-10). "18" and "18%" count once — see imSlNorm_.
function imColDistinct_(col,rows){
  const seen=new Map();
  (rows||[]).forEach(r=>{
    const k=imCellKey_(col,r);if(k===IM_BLANK)return;
    const u=imSlNorm_(col,k);if(!seen.has(u))seen.set(u,k);
  });
  return [...seen.values()].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true,sensitivity:'base'}));
}
/* The defined slicers, in column order: [{col, values:[…], auto}]. Dropdown
   Master values come first (the Admin's order), then — for a column ticked
   in the picker — every other value the data holds. Order is stable between
   a render and the click that follows, which imToggleSlicer's index needs. */
function imSlicerDefs_(){
  const auto=new Set(imSlicerAutoCols_());
  try{
    return IM_SLICER_COLS.map(col=>{
      let vals=[];
      try{vals=sarvDropdownList(imSlicerKey_(col)).map(v=>String(v==null?'':v).trim()).filter(Boolean);}catch(e){}
      vals=[...new Set(vals)];
      if(auto.has(col)){
        const have=new Set(vals.map(v=>imSlNorm_(col,v)));
        imColDistinct_(col,sarvItemMasterRows).forEach(v=>{
          const u=imSlNorm_(col,v);if(!have.has(u)){have.add(u);vals.push(v);}
        });
      }
      return {col,values:vals,auto:auto.has(col)};
    }).concat([{col:IM_SLICER_COMBO,values:imComboList_(),auto:false}])
      .filter(g=>g.values.length);
  }catch(e){return [];}
}

/* ── Combined slicers: ONE button, several columns ─────────────────────
   Dropdown Master › Item Master › Slicer Buttons › "Combined Slicers". Each
   value is one button, written as its conditions joined by "~":
       4 INCH SATTAN ~ TRIMS
   Every condition must hold (AND). A plain condition is looked for in every
   slicer column — whole value on Category / Size / Make / UOM / GST / Code,
   "contains" on Item Name / Description — so the line above means "name says
   4 INCH SATTAN AND Category is TRIMS" without naming either column. Where
   a word could hit the wrong column, the column can be named:
       Item Name: 4 INCH SATTAN ~ Category: TRIMS     (or name=… ~ cat=…)
   The buttons sit under their own heading, "Combined", and behave like any
   other slicer: OR with each other, AND with the other headings, dependent
   counts, kept out of the list once the value is removed. */
const IM_SLICER_COMBO='combo';
const IM_SLICER_COMBO_DD_KEY='erp_imSlicerCombo';
function imComboList_(){
  try{return [...new Set(sarvDropdownList(IM_SLICER_COMBO_DD_KEY).map(v=>String(v==null?'':v).trim()).filter(Boolean))];}
  catch(e){return [];}
}
function imComboParts_(val){
  return String(val||'').split('~').map(s=>s.trim()).filter(Boolean).map(p=>{
    const m=p.match(/^([^:=]+?)\s*[:=]\s*(.+)$/);
    if(m){
      const nm=m[1].trim().toUpperCase();
      const col=IM_SLICER_COLS.find(c=>c.toUpperCase()===nm||String(SARV_IM_FILTER_COLS[c].label).toUpperCase()===nm);
      if(col)return {col,v:m[2].trim()};
    }
    return {col:null,v:p};   // an unknown "xyz:" prefix is just part of the text
  });
}
function imComboMatch_(val,row){
  const parts=imComboParts_(val);
  if(!parts.length)return false;
  return parts.every(p=>p.col?imSlicerMatch_(p.col,p.v,row):IM_SLICER_COLS.some(c=>imSlicerMatch_(c,p.v,row)));
}
// Heading text for a slicer column, the Combined one included.
function imSlicerLabel_(col){
  return col===IM_SLICER_COMBO?'Combined':((SARV_IM_FILTER_COLS[col]||{}).label||col);
}
/* Dropdown Master's tick-box row for erp_imSlicerAutoCols: one tick per
   eligible column, with how many buttons it would make. Ticking writes /
   removes that column's row in sales_dropdowns, so the choice is shared. */
function imSlicerAutoPickHtml_(admin){
  const auto=new Set(imSlicerAutoCols_());
  const src=sarvItemMasterRows||[];
  return '<div class="dd-sl-pick">'
    +IM_SLICER_AUTO_COLS.map(c=>{
      const n=src.length?imColDistinct_(c,src).length:null;
      return '<label class="dd-sl-pickc'+(auto.has(c)?' on':'')+'">'
        +'<input type="checkbox"'+(auto.has(c)?' checked':'')+(admin?' onchange="sarvDdToggleSlicerCol(\''+c+'\')"':' disabled')+'> '
        +escText(SARV_IM_FILTER_COLS[c].label)+(n!=null?' <span class="n" title="buttons it makes">'+n+'</span>':'')+'</label>';
    }).join('')+'</div>';
}
window.sarvDdToggleSlicerCol=async function(col){
  if(!sarvDdGuard_())return;
  if(IM_SLICER_AUTO_COLS.indexOf(col)<0)return;
  const label=String(SARV_IM_FILTER_COLS[col].label).toUpperCase();
  const have=sarvDdRowsOf(IM_SLICER_AUTO_DD_KEY).filter(r=>{
    const v=String(r.value||'').trim().toUpperCase();return v===col.toUpperCase()||v===label;
  });
  try{
    const q=have.length
      ? SB.from(SARV_DD_TABLE).delete().in('id',have.map(r=>r.id))
      : SB.from(SARV_DD_TABLE).insert([{key:IM_SLICER_AUTO_DD_KEY,value:col}]);
    const {error}=await q;
    if(error)throw error;
    await sarvLoadDropdowns_(true);sarvDdRender_();
    if(typeof renderItemMasterTable==='function')renderItemMasterTable();
    showToast(SARV_IM_FILTER_COLS[col].label+(have.length?' slicer buttons removed':' slicer buttons added: one per value'));
  }catch(e){if(!sarvDdTableMissing_(e))dbError(e);}
};
function imSlicerMatch_(col,val,row){
  if(col===IM_SLICER_COMBO)return imComboMatch_(val,row);
  const cell=imCellKey_(col,row);
  if(cell===IM_BLANK)return false;
  const c=imSlNorm_(col,cell),v=imSlNorm_(col,val);
  return IM_SLICER_CONTAINS[col]?c.includes(v):c===v;
}
function imSlicerPass_(row,exceptCol){
  for(const col in sarvImSlicerSel){
    if(col===exceptCol)continue;
    const set=sarvImSlicerSel[col];
    if(!set||!set.size)continue;
    let ok=false;
    for(const v of set){if(imSlicerMatch_(col,v,row)){ok=true;break;}}
    if(!ok)return false;
  }
  return true;
}
function imActiveSlicerCols_(){return Object.keys(sarvImSlicerSel).filter(c=>sarvImSlicerSel[c]&&sarvImSlicerSel[c].size);}
function imSlicerSummary_(){
  return imActiveSlicerCols_().map(c=>imSlicerLabel_(c)+': '+[...sarvImSlicerSel[c]].join(' / '));
}
/* If a value is removed or changed in Dropdown Master it can't stay selected;
   otherwise a slicer with no visible button would still be filtering the
   list. Runs BEFORE render, so the table and the bar read the same state. */
function imPruneSlicers_(){
  const defs=imSlicerDefs_();
  Object.keys(sarvImSlicerSel).forEach(col=>{
    const g=defs.find(x=>x.col===col),set=sarvImSlicerSel[col];
    [...set].forEach(v=>{if(!g||g.values.indexOf(v)<0)set.delete(v);});
    if(!set.size)delete sarvImSlicerSel[col];
  });
}
/* By value index, not by value: that leaves no room for escaping mistakes
   with a quote / apostrophe inside onclick (5" PREMIUM, D'SOUZA). */
window.imToggleSlicer=function(col,i){
  const g=imSlicerDefs_().find(x=>x.col===col);
  const val=g&&g.values[i];if(val==null)return;
  const set=sarvImSlicerSel[col]||(sarvImSlicerSel[col]=new Set());
  if(set.has(val))set.delete(val);else set.add(val);
  if(!set.size)delete sarvImSlicerSel[col];
  renderItemMasterTable();
};
window.imClearSlicers=function(col){
  if(col)delete sarvImSlicerSel[col];else sarvImSlicerSel={};
  renderItemMasterTable();
};
/* Admin shortcut: straight to that slicer column in Dropdown Master. */
window.imOpenSlicerSetup=function(col){
  // 'auto' = the "Slicer Columns" row (one button per value).
  sarvDdPick=col==='auto'?IM_SLICER_AUTO_DD_KEY
    :col===IM_SLICER_COMBO?IM_SLICER_COMBO_DD_KEY
    :imSlicerKey_(col&&IM_SLICER_COLS.indexOf(col)>=0?col:IM_SLICER_COLS[0]);
  sarvDdEditId=null;
  switchMasterSubTab('dropdownMasterSub');
};
/* Each button's count = how many items that value would show after
   everything else (search, Stock, column filters, slicers on OTHER columns).
   Slicers in the same column aren't counted: that is OR, so the count says
   how many would be ADDED by pressing the button.
   DEPENDENT: a button whose count is 0 is HIDDEN, not just greyed — press
   YARN under Category and the Make / Size buttons that no yarn item carries
   disappear, so what is left on the bar is only what can still be narrowed
   to. A selected button is always drawn (even at 0), so it can be taken off;
   a heading with nothing left to offer and nothing selected goes too. */
function imRenderSlicers_(){
  const bar=byId('imSlicerBar');if(!bar)return;
  const defs=imSlicerDefs_();
  const admin=(typeof isAdmin==='function'&&isAdmin())&&sarvCan('DROPDOWN_MANAGE');
  const setupBtn=admin?'<button type="button" class="im-sl-link" onclick="imOpenSlicerSetup(\'auto\')" '
    +'title="Dropdown Master › Item Master › Slicer Buttons: choose the columns, or add fixed values">&#9776; Set up Slicers</button>':'';
  if(!defs.length){
    if(!admin){bar.style.display='none';bar.innerHTML='';return;}
    bar.style.display='block';
    bar.innerHTML='<div class="im-sl-wrap im-sl-empty">'+setupBtn
      +'<span>No slicers yet. In Dropdown Master › Item Master › Slicer Buttons, tick one or more columns '
      +'(Category, Size, Make …) to get one button per value, or add fixed values to a column.</span></div>';
    return;
  }
  const rows=sarvItemMasterRows||[];
  // A column with very many values would bury the list under buttons; the
  // rest stay reachable through that column's ▾ filter.
  const SHOW_MAX=40;
  let html='<div class="im-sl-wrap"><span class="im-sl-title">SLICERS</span>';
  defs.forEach(g=>{
    const sel=sarvImSlicerSel[g.col]||new Set();
    const pool=rows.filter(r=>imBasePass_(r,g.col)&&Object.keys(SARV_IM_FILTER_COLS).every(c=>imColPass_(c,r)));
    // Index i is kept with each button: imToggleSlicer looks the value up by it.
    const live=[];
    g.values.forEach((v,i)=>{
      const n=pool.reduce((s,r)=>s+(imSlicerMatch_(g.col,v,r)?1:0),0);
      if(n||sel.has(v))live.push({v,i,n,on:sel.has(v)});
    });
    if(!live.length)return;
    // Past the cap only the selected ones are drawn, so a tick can always be taken off.
    const shown=live.filter((b,k)=>k<SHOW_MAX||b.on);
    html+='<div class="im-sl-group'+(sel.size?' on':'')+'"><span class="im-sl-lab">'+escText(imSlicerLabel_(g.col))+'</span>';
    shown.forEach(b=>{
      html+='<button type="button" class="im-sl-btn'+(b.on?' on':'')+(b.n?'':' zero')+'" onclick="imToggleSlicer(\''+g.col+'\','+b.i+')" '
        +'title="'+escText(imSlicerLabel_(g.col)+': '+b.v+(IM_SLICER_CONTAINS[g.col]?' (contains the word)':'')
        +(g.col===IM_SLICER_COMBO?' (every part must match)':'')
        +': '+b.n+' item(s)'+(b.on?' · click to remove':''))+'">'
        +escText(b.v)+'<span class="n">'+b.n+'</span></button>';
    });
    if(live.length>shown.length)html+='<span class="im-sl-more" title="Use the column\'s ▾ filter for the rest">+'+(live.length-shown.length)+' more</span>';
    if(sel.size)html+='<button type="button" class="im-sl-x" onclick="imClearSlicers(\''+g.col+'\')" title="Remove this column\'s slicers">&#10006;</button>';
    if(admin)html+='<button type="button" class="im-sl-edit" onclick="imOpenSlicerSetup(\''+(g.auto?'auto':g.col)+'\')" title="Change this slicer in Dropdown Master">✎</button>';
    html+='</div>';
  });
  const nOn=imActiveSlicerCols_().length;
  if(nOn)html+='<button type="button" class="im-sl-clear" onclick="imClearSlicers()">&#10006; Clear Slicers</button>';
  html+=setupBtn+'</div>';
  bar.style.display='block';
  bar.innerHTML=html;
}

/* ══ ITEM MASTER: COLUMN SHOW / HIDE ═════════════════════════════════
   Columns the user unticks in the Columns popup are hidden from the table.
   Only the DISPLAY changes: filters, sort, search, slicers and CSV / PDF
   (which have their own column picker) work as before. The choice is
   remembered in the browser (by key, not index, so a newly added column
   can't shift someone's choice onto the neighbouring column).

   Hiding is done in CSS: every <th>/<td> has data-imc="<col>", and a
   <style> applies display:none to the hidden keys. So nothing breaks
   mid-render; only the colspan of the SUBTOTAL label cell is counted.
   #, NEW PR and Edit/Delete are always shown: they are action columns, not
   data (NEW PR has its own access rule). */
const IM_VIEW_COLS=['code','name','desc','cat','size','mat','rate','gst','uom','make','msv','soq','xtol','in','out','bal','pipe'];
// The SUBTOTAL label spans these (from # to Make).
const IM_LABEL_COLS=['code','name','desc','cat','size','mat','rate','gst','uom','make'];
const IM_COLHIDE_KEY='sarv_im_hidecols';
function imColHidden_(){
  let saved=null;
  try{saved=JSON.parse(localStorage.getItem(IM_COLHIDE_KEY)||'null');}catch(e){}
  if(!Array.isArray(saved))return new Set();
  const keep=saved.filter(k=>IM_VIEW_COLS.indexOf(k)>=0);
  // If all are hidden (an old / corrupt choice), hide nothing; better than an empty table.
  return keep.length>=IM_VIEW_COLS.length?new Set():new Set(keep);
}
function imColSaveHidden_(set){
  try{localStorage.setItem(IM_COLHIDE_KEY,JSON.stringify([...set]));}catch(e){}
}
function imApplyColVisibility_(){
  const hid=imColHidden_();
  let st=byId('imColHideStyle');
  if(!st){st=document.createElement('style');st.id='imColHideStyle';document.head.appendChild(st);}
  st.textContent=[...hid].map(k=>'#itemMasterTable [data-imc="'+k+'"]{display:none;}').join('\n');
  const btn=byId('imColPickBtn');
  if(btn){
    btn.innerHTML='Columns'+(hid.size?' <b>('+hid.size+' hidden)</b>':'');
    btn.classList.toggle('im-colpick-on',hid.size>0);
  }
  return hid;
}
function imCloseColPick(){const ov=byId('imColPickOverlay');if(ov)ov.style.display='none';}
window.imCloseColPick=imCloseColPick;
/* The popup is built once and reused, like the export picker, in the same
   place (inside #storeInterface, otherwise the overlay CSS doesn't apply).
   The table changes as soon as a tick changes, visibly behind the popup. */
window.imOpenColPick=function(){
  let ov=byId('imColPickOverlay');
  if(!ov){
    ov=document.createElement('div');
    ov.id='imColPickOverlay';
    ov.className='secure-modal-overlay';
    ov.style.cssText='display:none;align-items:center;justify-content:center;z-index:29500;padding:14px;';
    ov.innerHTML='<div style="background:#fff;width:min(520px,96vw);max-height:92vh;border-radius:12px;'
      +'box-shadow:0 25px 60px rgba(0,0,0,.35);display:flex;flex-direction:column;overflow:hidden;">'
      +'<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:#0f172a;color:#fff;">'
        +'<strong style="font-size:13px;">Item Master: show / hide columns</strong>'
        +'<span style="flex:1;"></span>'
        +'<button type="button" id="imcpClose" style="border:1px solid #64748b;background:transparent;color:#fff;'
        +'border-radius:6px;padding:4px 9px;font-size:15px;cursor:pointer;">&#10005;</button></div>'
      +'<div style="padding:8px 14px;background:#f8fafc;border-bottom:1px solid #e2e8f0;font-size:11px;color:#334155;font-weight:600;">'
        +'Untick a column to hide it from the table. Filter / sort / search keep working, '
        +'and the choice is remembered in this browser. CSV / PDF columns are chosen separately.</div>'
      +'<div style="display:flex;align-items:center;gap:8px;padding:8px 14px 4px;">'
        +'<span style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.3px;">Ticked = shown</span>'
        +'<span style="flex:1;"></span>'
        +'<button type="button" id="imcpAll" style="background:#f0fdf4;border:1px solid #86efac;color:#15803d;'
        +'border-radius:5px;padding:3px 9px;font-size:10px;font-weight:800;cursor:pointer;">Show all</button></div>'
      +'<div id="imcpList" style="flex:1;overflow-y:auto;padding:4px 14px 10px;display:grid;'
        +'grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:2px 14px;"></div>'
      +'<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:#f8fafc;border-top:1px solid #e2e8f0;">'
        +'<span id="imcpCount" style="font-size:11px;font-weight:800;color:#0369a1;"></span>'
        +'<span style="flex:1;"></span>'
        +'<button type="button" id="imcpDone" style="background:#6d28d9;color:#fff;border:0;border-radius:6px;'
        +'padding:7px 16px;font-size:12px;font-weight:800;cursor:pointer;">&#10004; Done</button></div>'
      +'</div>';
    (byId('storeInterface')||document.body).appendChild(ov);
    byId('imcpClose').addEventListener('click',imCloseColPick);
    byId('imcpDone').addEventListener('click',imCloseColPick);
    ov.addEventListener('click',e=>{if(e.target===ov)imCloseColPick();});
    document.addEventListener('keydown',e=>{
      if(e.key==='Escape'&&byId('imColPickOverlay')?.style.display==='flex')imCloseColPick();
    });
    byId('imcpAll').addEventListener('click',()=>{
      imColSaveHidden_(new Set());
      renderItemMasterTable();imcpFill_();
    });
    byId('imcpList').addEventListener('change',e=>{
      const cb=e.target.closest('.imcp-col');if(!cb)return;
      const hid=imColHidden_();
      if(cb.checked)hid.delete(cb.value);else hid.add(cb.value);
      if(hid.size>=IM_VIEW_COLS.length){
        cb.checked=true;
        return showToast('At least one column must stay visible','warn');
      }
      imColSaveHidden_(hid);
      renderItemMasterTable();imcpFill_();
    });
  }
  imcpFill_();
  ov.style.display='flex';
};
function imcpFill_(){
  const hid=imColHidden_();
  const sl=new Set(imActiveSlicerCols_());
  byId('imcpList').innerHTML=IM_VIEW_COLS.map(k=>{
    /* If a hidden column has a filter / slicer applied, it is still filtering
       the list; that is noted right here, otherwise "where did the rows go" has no answer. */
    const busy=imHasFilter_(k)||sl.has(k);
    return '<label style="display:flex;align-items:center;gap:7px;padding:3px 0;font-size:11.5px;font-weight:600;color:#0f172a;cursor:pointer;">'
      +'<input type="checkbox" class="imcp-col" value="'+k+'"'+(hid.has(k)?'':' checked')+' style="width:14px;height:14px;cursor:pointer;">'
      +'<span>'+escText(SARV_IM_FILTER_COLS[k].label)+'</span>'
      +(busy?'<span style="font-size:9px;font-weight:800;color:#b45309;background:#fef3c7;border-radius:8px;padding:1px 6px;" title="A filter / slicer is applied to this column">filtered</span>':'')
      +'</label>';
  }).join('');
  const el=byId('imcpCount');
  if(el)el.textContent=(IM_VIEW_COLS.length-hid.size)+' of '+IM_VIEW_COLS.length+' columns shown';
}
/* The value list for one column: what is left after every OTHER filter, with
   a count each. Sorted by number on numeric columns and alphabetically
   elsewhere; (Blank) always sinks to the bottom, where it reads as the
   leftover rather than as a value in its own right. */
function imOptionsFor_(col){
  const counts=new Map();
  sarvItemMasterRows.forEach(row=>{
    if(!imRowPass_(row,col))return;
    const k=imCellKey_(col,row);
    counts.set(k,(counts.get(k)||0)+1);
  });
  const numeric=SARV_IM_FILTER_COLS[col].numeric;
  const list=[...counts.entries()].map(([value,count])=>({value,count}));
  list.sort((a,b)=>{
    if(a.value===IM_BLANK)return 1;
    if(b.value===IM_BLANK)return -1;
    return numeric?(Number(a.value)-Number(b.value))
                  :String(a.value).localeCompare(String(b.value),undefined,{numeric:true,sensitivity:'base'});
  });
  return list;
}

window.imOpenFilter=function(ev,col){
  // Without this the click reaches the <th> and re-sorts the column underneath
  // the panel that just opened.
  if(ev){ev.stopPropagation();ev.preventDefault();}
  if(!SARV_IM_FILTER_COLS[col])return;
  if(sarvImPanelCol===col){imCloseFilterPanel();return;}   // same button closes it
  sarvImPanelCol=col;
  const cur=sarvImFilters[col];
  sarvImDraft={
    values:cur&&cur.values?new Set(cur.values):null,
    min:cur&&cur.min!=null?cur.min:null,
    max:cur&&cur.max!=null?cur.max:null,
    search:'',
    /* The option list is worked out once, here, not on every keystroke in the
       panel's search box. Nothing the panel does can change it: the draft is
       not applied until Apply, and a column's own filter is excluded from its
       own list anyway. On a master with thousands of items, recomputing it per
       keystroke was the one thing in here that would have felt slow. */
    options:imOptionsFor_(col),
    /* The header button this panel hangs off. Kept so every re-render (search,
       Select All, Clear) can re-anchor itself — the panel changes height as the
       list narrows, and one that never re-positioned would grow off-screen.

       The column's OWN funnel is looked up by id, in preference to anything on
       the event. The click now arrives from one delegated listener on the
       <thead> (imHeaderClick_), so ev.currentTarget is that whole header row —
       anchoring to it would park every column's panel at the left edge of the
       table instead of under the ▾ that was pressed. */
    anchor:byId('imF-'+col)||(ev&&(ev.target&&ev.target.closest&&ev.target.closest('.im-fbtn')))||(ev&&ev.currentTarget)
  };
  imRenderFilterPanel_();
};
function imEnsureFilterPanel_(){
  let p=byId('imFilterPanel');
  if(p)return p;
  p=document.createElement('div');
  p.id='imFilterPanel';
  // On <body> rather than inside the <th>: the table scrolls in a container
  // with its own overflow and a sticky header, which would clip it.
  document.body.appendChild(p);
  // A click inside the panel must never reach the document-level closer below.
  p.addEventListener('click',e=>e.stopPropagation());
  return p;
}
function imPositionFilterPanel_(anchor){
  const p=byId('imFilterPanel');if(!p)return;
  const btn=anchor||byId('imF-'+sarvImPanelCol);
  const r=btn?btn.getBoundingClientRect():{left:120,top:100,bottom:120};
  const w=p.offsetWidth||268,h=p.offsetHeight||320;
  // Kept inside the viewport: a filter on the last column would otherwise open
  // off the right edge, and one near the bottom would run off-screen.
  let left=Math.min(Math.max(8,r.left-10),Math.max(8,window.innerWidth-w-8));
  let top=r.bottom+4;
  if(top+h>window.innerHeight-8)top=Math.max(8,r.top-h-4);
  p.style.left=left+'px';p.style.top=top+'px';
  // Measured while hidden (see imRenderFilterPanel_), shown once it is parked
  // where it belongs — otherwise it flashes at the previous column's position.
  p.style.visibility='visible';
}
function imRenderFilterPanel_(){
  const col=sarvImPanelCol;if(!col)return;
  const p=imEnsureFilterPanel_(),meta=SARV_IM_FILTER_COLS[col];
  const opts=sarvImDraft.options||[];
  const present=new Set(opts.map(o=>o.value));
  // Ticked values the other filters have emptied out are appended, greyed, so
  // they can still be unticked. Without this the panel could strand a filter.
  const extra=sarvImDraft.values
    ? [...sarvImDraft.values].filter(v=>!present.has(v)).sort().map(v=>({value:v,count:0,gone:true}))
    : [];
  const all=opts.concat(extra);
  const term=(sarvImDraft.search||'').toLowerCase();
  const shown=term?all.filter(o=>o.value.toLowerCase().includes(term)):all;
  /* What Apply measures itself against, stashed on the draft because
     imApplyFilter runs long after this function has returned and none of these
     closures are left:
       allValues   — every value the panel is offering, stranded ones included;
       shownValues — just the ones the panel's own search has left visible.
     `options` (set when the panel opened) is NOT the same list: a stranded
     value can be in `all` and not in `options`, and comparing the user's ticks
     against the shorter list is what made "everything ticked" read as a real
     filter instead of as no filter. */
  sarvImDraft.allValues=all.map(o=>o.value);
  sarvImDraft.shownValues=shown.map(o=>o.value);
  // values===null is "no restriction", which reads as everything ticked.
  const ticked=v=>sarvImDraft.values?sarvImDraft.values.has(v):true;
  const LIMIT=400;
  const clipped=shown.length>LIMIT?shown.slice(0,LIMIT):shown;
  const rowsHtml=clipped.length?clipped.map(o=>
      '<label class="imf-opt'+(o.gone?' gone':'')+'">'
      +'<input type="checkbox" data-v="'+escText(o.value)+'"'+(ticked(o.value)?' checked':'')+'>'
      +'<span class="t" title="'+escText(o.value)+'">'+escText(o.value)+'</span>'
      +'<span class="n">'+(o.gone?'0':o.count)+'</span></label>').join('')
    : '<div style="color:#94a3b8;padding:6px 2px;">'+(term?'No values match this search.':'No values left in this column after the other filters.')+'</div>';
  const clipNote=shown.length>LIMIT
    ? '<div style="color:#b45309;font-size:10px;padding:4px 2px 0;">Showing the first '+LIMIT+' values (of '+shown.length+'). Use the search above to narrow it down.</div>'
    : '';
  const rangeHtml=meta.numeric
    ? '<div class="imf-range">'
      +'<input type="number" id="imfMin" placeholder="Min" step="any" value="'+(sarvImDraft.min!=null?sarvImDraft.min:'')+'">'
      +'<input type="number" id="imfMax" placeholder="Max" step="any" value="'+(sarvImDraft.max!=null?sarvImDraft.max:'')+'">'
      +'</div>'
    : '';
  p.innerHTML=
     '<div class="imf-head">'+escText(meta.label)
    +'<div class="imf-sub">'+opts.length+' value(s) &middot; based on the other filters</div></div>'
    +'<div class="imf-body">'+rangeHtml
    +'<input type="text" id="imfSearch" placeholder="Values me search..." value="'+escText(sarvImDraft.search||'')+'">'
    +'<div style="display:flex;justify-content:space-between;margin-top:6px;">'
    +'<button type="button" class="imf-mini" id="imfAll">Select All</button>'
    +'<button type="button" class="imf-mini" id="imfNone" style="color:#b91c1c;">Clear</button></div>'
    +'<div class="imf-list" id="imfList">'+rowsHtml+'</div>'+clipNote
    +'</div>'
    +'<div class="imf-foot">'
    +'<button type="button" class="imf-btn imf-apply" id="imfApply">&#10004; Apply</button>'
    +'<button type="button" class="imf-btn imf-remove" id="imfRemove">&#10006; Remove Filter</button>'
    +'<button type="button" class="imf-btn imf-cancel" id="imfCancel">Cancel</button>'
    +'</div>';
  // Laid out so it can be measured, but not yet visible — imPositionFilterPanel_
  // at the bottom of this function reveals it once it has somewhere to be.
  p.style.visibility='hidden';
  p.style.display='block';

  // Ticking a box only ever edits the draft — nothing filters until Apply.
  // Until the first tick values is null ("all"), so it is materialised from
  // what is currently shown as checked rather than starting empty, or the
  // first untick would wipe every other value too.
  const listEl=byId('imfList');
  listEl.addEventListener('change',e=>{
    const cb=e.target.closest('input[type=checkbox]');if(!cb)return;
    if(!sarvImDraft.values)sarvImDraft.values=new Set(all.map(o=>o.value));
    if(cb.checked)sarvImDraft.values.add(cb.dataset.v);else sarvImDraft.values.delete(cb.dataset.v);
  });
  const search=byId('imfSearch');
  search.addEventListener('input',()=>{
    sarvImDraft.search=search.value;
    const at=search.selectionStart;
    imRenderFilterPanel_();
    const s2=byId('imfSearch');if(s2){s2.focus();try{s2.setSelectionRange(at,at)}catch(e){}}
  });
  // Select All / Clear act on WHAT IS SHOWN, so a search narrows what they
  // touch — same as Excel, and the only reading that is useful on a long list.
  byId('imfAll').addEventListener('click',()=>{
    if(!sarvImDraft.values)sarvImDraft.values=new Set(all.map(o=>o.value));
    clipped.forEach(o=>sarvImDraft.values.add(o.value));
    if(!term&&sarvImDraft.values.size>=all.length)sarvImDraft.values=null;   // everything = no restriction
    imRenderFilterPanel_();
  });
  byId('imfNone').addEventListener('click',()=>{
    if(!sarvImDraft.values)sarvImDraft.values=new Set(all.map(o=>o.value));
    clipped.forEach(o=>sarvImDraft.values.delete(o.value));
    imRenderFilterPanel_();
  });
  if(meta.numeric){
    const rd=()=>{
      const mn=byId('imfMin').value.trim(),mx=byId('imfMax').value.trim();
      sarvImDraft.min=mn===''?null:Number(mn);
      sarvImDraft.max=mx===''?null:Number(mx);
    };
    byId('imfMin').addEventListener('input',rd);
    byId('imfMax').addEventListener('input',rd);
  }
  byId('imfApply').addEventListener('click',imApplyFilter);
  byId('imfRemove').addEventListener('click',()=>imRemoveFilter(col));
  byId('imfCancel').addEventListener('click',imCloseFilterPanel);
  imPositionFilterPanel_(sarvImDraft.anchor);
}
window.imApplyFilter=function(){
  const col=sarvImPanelCol;
  // Said out loud rather than returning quietly: a dead Apply button used to
  // be indistinguishable from one that applied a filter matching everything.
  if(!col){showToast('The filter panel had already closed. Click the column\'s ▾ again to apply a filter.','warn');return;}
  const d=sarvImDraft||{};
  const label=SARV_IM_FILTER_COLS[col].label;
  let {min,max}=d;
  if(min!=null&&isNaN(min))min=null;
  if(max!=null&&isNaN(max))max=null;
  // A reversed range is a slip, not a request for an empty table.
  if(min!=null&&max!=null&&min>max){const t=min;min=max;max=t;}
  let values=d.values;
  /* NOTHING was ticked or unticked, but the panel's search box has a term in
     it. That box only narrows the option LIST — it is not itself a filter — so
     this case used to fall straight through to "no restriction" and Apply
     REMOVED the filter, putting the whole master back on screen. Which is
     precisely what it looked like: type YARN, press Apply, get every row.
     Read as what it plainly means instead — keep the values the search has
     left showing. */
  if(!values&&String(d.search||'').trim()&&(d.shownValues||[]).length)
    values=new Set(d.shownValues);
  /* The ticks are now read back OFF THE DOM, not only tracked through change
     events as they were before. The draft stays the source of truth for values
     that are not on screen (a long list renders the first 400, and the panel's
     search narrows that further), but whatever IS rendered is read directly —
     so a tick can no longer be lost because a change event did not land where
     this code expected it to, which would leave `values` null and Apply
     silently meaning "show everything". */
  const boxes=[...document.querySelectorAll('#imFilterPanel .imf-opt input[type=checkbox]')];
  if(boxes.length){
    if(!values)values=new Set(d.allValues||boxes.map(b=>b.dataset.v));
    boxes.forEach(b=>{if(b.checked)values.add(b.dataset.v);else values.delete(b.dataset.v);});
  }
  /* Everything ticked is the same as no filter, so it is stored as none — that
     is what keeps the header badge and the chip bar honest, because a green
     funnel that hides nothing is worse than no badge at all. Measured against
     allValues (what the panel offered, stranded values included), not against
     the shorter `options` list it used to use. */
  if(values){
    const all=d.allValues||(d.options||[]).map(o=>o.value);
    if(all.length&&values.size>=all.length&&all.every(v=>values.has(v)))values=null;
  }
  if(values==null&&min==null&&max==null){
    imRemoveFilter(col,true);
    showToast('No filter applied on <b>'+escText(label)+'</b>: every value was ticked, so the full list is shown.<br>'
      +'<span style="font-size:10px;">To keep only some values, press <b>Clear</b> in the panel, tick just those values, then Apply.</span>','warn');
    return;
  }
  if(values&&values.size===0){
    showToast('No value is ticked in <b>'+escText(label)+'</b>; with this filter the list will be empty','warn');
  }
  sarvImFilters[col]={values:values?new Set(values):null,min,max};
  imCloseFilterPanel();
  renderItemMasterTable();
  /* Always says what landed. If this toast does not appear, Apply never ran —
     which is a different fault from a filter that ran and matched everything,
     and the two were impossible to tell apart before. */
  showToast('<b>'+escText(label)+'</b> filter: '+escText(imFilterSummary_(col))
    +': <b>'+(sarvItemMasterShown||[]).length+'</b> of '+(sarvItemMasterRows||[]).length+' items shown');
};
/* quiet=true when imApplyFilter is the caller — it says its own piece, and two
   toasts for one button press read as something having gone wrong. */
window.imRemoveFilter=function(col,quiet){
  const had=imHasFilter_(col);
  delete sarvImFilters[col];
  if(sarvImPanelCol===col)imCloseFilterPanel();
  renderItemMasterTable();
  if(!quiet&&had)showToast('✖ Filter removed from <b>'+escText(SARV_IM_FILTER_COLS[col].label)+'</b>: '
    +'<b>'+(sarvItemMasterShown||[]).length+'</b> items shown');
};
window.imClearAllFilters=function(){
  const n=imActiveCols_().length;
  sarvImFilters={};
  imCloseFilterPanel();
  renderItemMasterTable();
  if(n)showToast('✖ All column filters removed ('+n+'): '
    +'<b>'+(sarvItemMasterShown||[]).length+'</b> items shown');
};
function imCloseFilterPanel(){
  const p=byId('imFilterPanel');if(p)p.style.display='none';
  sarvImPanelCol=null;sarvImDraft=null;
}
// Click anywhere else, Escape, or a scroll/resize that would leave the panel
// floating away from its header — all close it.
document.addEventListener('click',e=>{
  if(!sarvImPanelCol)return;
  if(e.target.closest&&e.target.closest('.im-fbtn'))return;   // handled by imOpenFilter
  imCloseFilterPanel();
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sarvImPanelCol)imCloseFilterPanel()});
/* A scroll or a resize used to CLOSE the panel. It now FOLLOWS its header
   instead, and only gives up once that header has actually scrolled out of
   sight. Closing was the wrong answer to the right problem: the panel is
   position:fixed, so it does have to be re-placed when the page moves under
   it — but any scroll anywhere fired this, including the one a tap on a
   sticky header can cause, so the panel could vanish in the same gesture
   that opened it, which is indistinguishable from "the filter does nothing".

   Capture phase, because a scroll inside the table's own overflow container
   does not bubble. The panel's own value list is excluded: it scrolls, and a
   long list would be unusable if scrolling it moved the panel. */
function imFollowAnchor_(){
  if(!sarvImPanelCol)return;
  const anchor=(sarvImDraft&&sarvImDraft.anchor)||byId('imF-'+sarvImPanelCol);
  const r=anchor&&anchor.getBoundingClientRect();
  // Scrolled out of view (or gone) — now there is nothing to hang off.
  if(!r||r.bottom<0||r.top>window.innerHeight||r.width===0){imCloseFilterPanel();return;}
  imPositionFilterPanel_(anchor);
}
window.addEventListener('resize',imFollowAnchor_);
document.addEventListener('scroll',e=>{
  if(!sarvImPanelCol)return;
  const p=byId('imFilterPanel'),t=e.target;
  if(p&&t&&t.nodeType===1&&p.contains(t))return;
  imFollowAnchor_();
},true);

/* What each applied filter looks like in a chip and in the header's tooltip. */
function imFilterSummary_(col){
  const f=sarvImFilters[col];if(!f)return '';
  const parts=[];
  if(f.min!=null||f.max!=null){
    parts.push(f.min!=null&&f.max!=null?(f.min+'–'+f.max):(f.min!=null?('≥ '+f.min):('≤ '+f.max)));
  }
  if(f.values){
    const v=[...f.values];
    parts.push(v.length===0?'none':v.length<=2?v.join(', '):(v.length+' selected'));
  }
  return parts.join(' · ');
}
// Header badges + the chip bar, rebuilt on every render so they can never drift
// from what is actually being applied.
function imRenderFilterIndicators_(){
  Object.keys(SARV_IM_FILTER_COLS).forEach(col=>{
    const btn=byId('imF-'+col);if(!btn)return;
    const on=imHasFilter_(col);
    btn.classList.toggle('on',on);
    btn.innerHTML=on?'&#9776;':'&#9662;';
    btn.title=on?(SARV_IM_FILTER_COLS[col].label+' filter: '+imFilterSummary_(col)+'. Click to change or remove')
                 :('Filter '+SARV_IM_FILTER_COLS[col].label);
  });
  const bar=byId('imFilterChips');if(!bar)return;
  const cols=imActiveCols_();
  if(!cols.length){bar.style.display='none';bar.innerHTML='';return;}
  bar.style.display='flex';
  bar.innerHTML='<span style="font-size:10px;font-weight:800;color:#475569;">FILTERS:</span>'
    +cols.map(c=>'<span class="imf-chip">'+escText(SARV_IM_FILTER_COLS[c].label)+': '+escText(imFilterSummary_(c))
      +'<button type="button" onclick="imRemoveFilter(\''+c+'\')" title="Remove this column\'s filter">&#10006;</button></span>').join('')
    +'<button type="button" onclick="imClearAllFilters()" style="background:#fef2f2;border:1px solid #fecaca;color:#b91c1c;'
    +'border-radius:12px;padding:3px 10px;font-size:10px;font-weight:800;cursor:pointer;">&#10006; Clear All Filters ('+cols.length+')</button>';
}
/* Minimum Stock Value for an item row. Stored in items.sub_category, which is
   free text — blank or legacy non-numeric content means "no MSV set", and such
   an item is neither below nor above one. */
function itemMsv_(it){
  const raw=it&&it.sub_category;
  if(raw==null||String(raw).trim()==='')return null;
  const n=Number(raw);
  return isNaN(n)?null:n;
}
/* GST % held on the Item Master row. A part's GST rate is a property of the
   part, not of the day it was bought, so it is set once on the item and read
   back here by every entry form. 18 is the default for an item saved before
   the column existed — the same number those forms hard-coded previously, so
   nothing changes for existing data until someone sets a rate explicitly.
   SARV_DEFAULT_GST is the single place that default lives. */
const SARV_DEFAULT_GST=18;
/* Columns on `items` that a database may simply not have yet, with the DDL
   that adds each one. Every save drops whichever of these the server says it
   does not know about and retries, so the rest of the item still saves and the
   user is told exactly what to run. gst_pct was the first; Item Size, Material
   Type and Standard Order Qty arrived with ITEM_MASTER_FIELDS_MIGRATION.sql
   and are handled the same way rather than each growing its own special case. */
const SARV_ITEM_OPTIONAL_COLUMNS={
  gst_pct:      {label:'GST %',              ddl:'alter table items add column gst_pct numeric default 18;'},
  item_size:    {label:'Item Size',          ddl:'alter table items add column item_size text;'},
  material_type:{label:'Material Type',      ddl:'alter table items add column material_type text;'},
  std_order_qty:{label:'Standard Order Qty', ddl:'alter table items add column std_order_qty numeric;'},
  // "default 5" also fills every existing item with 5 the moment the column is added.
  excess_tol_pct:{label:'PO Excess Allowed %', ddl:'alter table items add column excess_tol_pct numeric default 5;'}
};
/* Shown once per session PER COLUMN, with the exact migration, instead of the
   same vague line on every single item save. */
const sarvItemColumnWarned=new Set();
function warnItemColumnsMissing_(cols){
  const fresh=(cols||[]).filter(c=>SARV_ITEM_OPTIONAL_COLUMNS[c]&&!sarvItemColumnWarned.has(c));
  if(!fresh.length)return;
  fresh.forEach(c=>sarvItemColumnWarned.add(c));
  showToast(''+fresh.map(c=>SARV_ITEM_OPTIONAL_COLUMNS[c].label).join(' / ')+' was not saved: the items table has no '
    +fresh.map(c=>'<b>'+c+'</b>').join(', ')+' column.<br>'
    +'Run this once in Supabase → SQL Editor:<br>'
    +fresh.map(c=>'<code>'+SARV_ITEM_OPTIONAL_COLUMNS[c].ddl+'</code>').join('<br>')+'<br>'
    +"<code>notify pgrst, 'reload schema';</code><br>"
    +'Then save the item again; these fields will save from then on.','warn');
}
// Kept as a thin wrapper: older call sites still ask specifically about GST.
function warnGstColumnMissing_(){warnItemColumnsMissing_(['gst_pct'])}
/* Which optional column, if any, an error is complaining about. PostgREST
   reports a column it has not re-read yet exactly like a column that does not
   exist, so one test covers both "the column is missing" and "the column was
   just added and the schema cache is stale". */
function missingItemColumn_(e){
  const msg=(e&&e.message)||'';
  if(!/column|does not exist|schema cache/i.test(msg))return null;
  return Object.keys(SARV_ITEM_OPTIONAL_COLUMNS).find(c=>new RegExp('\\b'+c+'\\b','i').test(msg))||null;
}
async function saveItemRow_(payload,editingId){
  const run=p=>editingId
    ? SB.from('items').update(p).eq('id',editingId)
    : SB.from('items').insert(p);
  let body={...payload},dropped=[];
  let r=await run(body);
  /* The stale schema cache is by far the common case and a single retry clears
     it, so a column that really is there does get saved instead of being
     dropped on the spot. One retry for the whole payload, then the loop below
     peels off genuinely-absent columns one at a time — PostgREST only ever
     names the first one it trips over. */
  if(missingItemColumn_(r.error)){
    await new Promise(res=>setTimeout(res,700));
    r=await run(body);
  }
  // Bounded by the number of optional columns, so a server that keeps
  // complaining can never spin this forever.
  for(let i=0;i<Object.keys(SARV_ITEM_OPTIONAL_COLUMNS).length&&r.error;i++){
    const col=missingItemColumn_(r.error);
    if(!col||!(col in body))break;
    delete body[col];dropped.push(col);
    r=await run(body);
  }
  return {error:r.error,dropped:r.error?[]:dropped,droppedGst:!r.error&&dropped.includes('gst_pct')};
}
/* ── "Add New Item" popup (Item Configurations) ───────────────────
   The Item Name column only offers what the Item Master already holds, so a
   part that wasn't there yet meant leaving the half-typed entry, opening Item
   Master, adding it, and coming back. This popup writes the same items row —
   through saveItemRow_, so the gst_pct retry/fallback applies here too —
   refreshes the shared datalists and drops the new name straight into the
   entry that asked for it. */
// Which grid asked for the popup, so the saved name lands back in it:
// 'inward' | 'outward' | 'purchase' (the PR form's Items Required table).
const SARV_NEW_ITEM_TARGETS={
  inward:  {body:'itemTableBody',        nameSel:'.item-name',     add:()=>addNewRow(),           totals:()=>updateStoreTotals()},
  outward: {body:'outwardItemTableBody', nameSel:'.out-item-name', add:()=>addOutwardItemRow(),   totals:()=>updateOutTotals()},
  purchase:{body:'p_itemTableBody',      nameSel:'.col-name',      add:()=>addPurchaseMainRow(),  totals:()=>refreshPurchaseTotals()}
};
let sarvNewItemTarget='inward';
function openNewItemMasterModal(target){
  sarvNewItemTarget=SARV_NEW_ITEM_TARGETS[target]?target:'inward';
  let ov=byId('sarvNewItemModal');
  if(!ov){
    const FLD='class="form-control" style="height:30px;font-size:12px;"';
    const lbl=t=>'<label style="display:block;font-size:10px;font-weight:700;color:#475569;margin-bottom:2px;">'+t+'</label>';
    // One cell of the form grid. span=2 makes it run the full width.
    const cell=(t,inner,span)=>'<div'+(span===2?' style="grid-column:1 / -1;"':'')+'>'+lbl(t)+inner+'</div>';
    const txt=(id,ph,extra)=>'<input type="text" id="'+id+'" placeholder="'+ph+'" '+(extra||'')+' '+FLD+'>';
    const num=(id,ph,step)=>'<input type="number" id="'+id+'" placeholder="'+ph+'" min="0" step="'+step+'" '+FLD+'>';
    const sel=id=>'<select id="'+id+'" '+FLD+'></select>';
    ov=document.createElement('div');
    ov.id='sarvNewItemModal';
    ov.className='secure-modal-overlay';
    ov.style.cssText='display:none;align-items:center;justify-content:center;z-index:31000;';
    /* Laid out the way the Item Master form reads: identity first (name,
       description), then classification (category, make, size, material),
       then how it is counted (UOM, MSV, Standard Order Qty), then how it is
       priced (GST, rate).

       Item Size / Material Type / Standard Order Qty are here because this
       popup is the only way a PR or an entry row creates an item, and a part
       created without them comes out of the Item Master half-filled — then
       nobody goes back to finish it. Make / Brand, Item Size and Material Type
       all suggest what the master already holds, so the store's own vocabulary
       gets reused instead of five spellings of the same brand. */
    ov.innerHTML='<div class="secure-modal-box" style="max-width:520px;width:94vw;">'
      +'<h3 style="margin:0 0 2px;font-size:15px;color:#0f172a;">Add New Item</h3>'
      +'<p style="margin:0 0 14px;font-size:11px;color:#64748b;">It is saved to the Item Master and appears in the Item Name list immediately.</p>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px 12px;">'
        +cell('Item Name <span style="color:#dc2626;">&#9733;</span>',
              txt('ni_name','Start typing; saved items will be suggested','list="dl-ni-item-name" autocomplete="off"')
              +'<datalist id="dl-ni-item-name"></datalist>'
              +'<div id="ni_nameHint" style="min-height:13px;margin-top:3px;font-size:10px;font-weight:700;"></div>',2)
        +cell('Item Description',txt('ni_desc','Start typing; saved descriptions will be suggested','list="dl-ni-item-desc" autocomplete="off"')+'<datalist id="dl-ni-item-desc"></datalist>',2)
        +cell('Category',sel('ni_cat'))
        +cell('Make / Brand',txt('ni_make','Start typing; saved makes will be suggested','list="dl-ni-item-make" autocomplete="off"')+'<datalist id="dl-ni-item-make"></datalist>')
        +cell('Item Size',txt('ni_itemSize','e.g. 1/2 INCH, M8 x 40, 24&quot;','list="dl-ni-itemSize" autocomplete="off"')+'<datalist id="dl-ni-itemSize"></datalist>')
        +cell('Material Type',txt('ni_materialType','e.g. SS 304, MS, BRASS','list="dl-ni-materialType" autocomplete="off"')+'<datalist id="dl-ni-materialType"></datalist>')
        +cell('UOM',sel('ni_uom'))
        +cell('Minimum Stock Qty (MSV)',num('ni_msv','optional','any'))
        +cell('Standard Order Qty',num('ni_stdOrderQty','e.g. 10','any'))
        +cell('PO Excess Allowed %',num('ni_excessTol','5','any'))
        +cell('GST %',sel('ni_gst'))
        +cell('Rate (&#8377;)',num('ni_rate','0','.01'))
      +'</div>'
      +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px;">'
      +'<button type="button" id="ni_cancel" class="btn" style="background:#e2e8f0;color:#0f172a;">Cancel</button>'
      +'<button type="button" id="ni_save" class="btn btn-primary">Save Item</button>'
      +'</div></div>';
    /* Mounted on <body>, NOT inside #storeInterface. That panel is set to
       display:none whenever the Purchase panel is open (see activatePanel), so
       a popup living inside it was invisible when opened from the PERSONNEL
       ITEM REQUIREMENT FORM — and then appeared, already open, the next time
       Material Inward was shown. .secure-modal-box / .btn / .form-control are
       scoped to that panel, so #sarvNewItemModal carries its own copy of those
       styles in the stylesheet above. Same fix, and same reason, as
       #pwdGateModal. */
    document.body.appendChild(ov);
    byId('ni_cancel').onclick=closeNewItemMasterModal;
    byId('ni_save').onclick=saveNewItemFromModal_;
    ov.addEventListener('click',e=>{if(e.target===ov)closeNewItemMasterModal();});
    const nameBox=byId('ni_name');
    nameBox.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();saveNewItemFromModal_();}});
    // The suggestion list is there to stop a second copy of an item being
    // created, so the moment what is typed matches one, say so — the save
    // refuses it anyway, and this says why before the button is pressed.
    nameBox.addEventListener('input',refreshNewItemNameHint_);
  }
  // The dropdown under Item Name is the live Item Master list, so a part that
  // already exists is offered rather than entered a second time.
  const dl=byId('dl-ni-item-name');
  if(dl)dl.innerHTML=(sarvItemCatalog||[]).map(it=>
    '<option value="'+escText(String(it.name||''))+'">'+escText([it.make,it.category].filter(Boolean).join(' — '))+'</option>').join('');
  /* Item Description draws on what is already in the master too, so the same
     spec is worded the same way every time instead of ten near-copies. One
     entry per distinct description, labelled with the item it came from. */
  const dd=byId('dl-ni-item-desc');
  if(dd){
    const seen=new Set(), opts=[];
    (sarvItemCatalog||[]).forEach(it=>{
      const d=String(it.description||'').trim(); if(!d) return;
      const key=d.toUpperCase(); if(seen.has(key)) return;
      seen.add(key);
      opts.push('<option value="'+escText(d)+'">'+escText(String(it.name||''))+'</option>');
    });
    dd.innerHTML=opts.join('');
  }
  // Category / UOM / GST choices are mirrored off the Item Master form, so both
  // screens always offer exactly the same lists without a second copy to keep.
  const mirror=(from,to,fallback)=>{const s=byId(from),d=byId(to);if(d)d.innerHTML=s?s.innerHTML:fallback;};
  mirror('mi_category','ni_cat','<option value="">— Select —</option>');
  mirror('mi_uom','ni_uom','<option>PCS</option>');
  mirror('mi_gst','ni_gst','<option>5</option><option>12</option><option>18</option><option>28</option><option>0</option>');
  /* Make / Brand, Item Size and Material Type are free text with a suggestion
     list built from what the master already holds — the same lists the Item
     Master form offers, so a brand that has been typed once is offered back
     instead of re-spelled. Built here rather than mirrored off the Item Master
     datalists, because those are only filled when that panel has been opened. */
  {
    const fillDl=(dlId,vals)=>{
      const dl=byId(dlId);if(!dl)return;
      dl.innerHTML=[...new Set(vals.filter(v=>String(v||'').trim()))]
        .sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true,sensitivity:'base'}))
        .map(v=>'<option value="'+escText(String(v))+'">').join('');
    };
    fillDl('dl-ni-item-make',(sarvItemCatalog||[]).map(it=>it.make));
    fillDl('dl-ni-itemSize',(sarvItemCatalog||[]).map(itemSize_));
    fillDl('dl-ni-materialType',(sarvItemCatalog||[]).map(itemMaterial_));
  }
  ['ni_name','ni_desc','ni_make','ni_msv','ni_itemSize','ni_materialType','ni_stdOrderQty']
    .forEach(id=>{const e=byId(id);if(e)e.value='';});
  if(byId('ni_rate'))byId('ni_rate').value='0';
  if(byId('ni_excessTol'))byId('ni_excessTol').value=String(SARV_DEFAULT_EXCESS_TOL);
  if(byId('ni_cat'))byId('ni_cat').value='';
  if(byId('ni_gst'))byId('ni_gst').value=String(SARV_DEFAULT_GST);
  refreshNewItemNameHint_();
  ov.style.display='flex';
  setTimeout(()=>byId('ni_name')?.focus(),60);
}
function newItemDuplicate_(name){
  const key=String(name||'').trim().toUpperCase();
  if(!key)return null;
  return (sarvItemCatalog||[]).find(it=>String(it.name||'').trim().toUpperCase()===key)||null;
}
function refreshNewItemNameHint_(){
  const hint=byId('ni_nameHint');if(!hint)return;
  const dup=newItemDuplicate_(byId('ni_name')?.value);
  hint.style.color='#b45309';
  hint.textContent=dup?('This item is already in the master ('+(dup.item_code||dup.uom||'')+'). Select it from the list.'):'';
}
function closeNewItemMasterModal(){const ov=byId('sarvNewItemModal');if(ov)ov.style.display='none';}
async function saveNewItemFromModal_(){
  if(!SB_READY)return showToast('Please configure the Supabase URL/key','warn');
  const name=(byId('ni_name')?.value||'').trim().toUpperCase();
  if(!name){showToast('Item Name required!','error');byId('ni_name')?.focus();return;}
  // Same rule the Item Master screen applies: one name, one master row.
  if(newItemDuplicate_(name))
    return showToast('"'+name+'" is already in the Item Master. Select it from the list.','warn');
  const btn=byId('ni_save');
  if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const payload={
      name,
      description:(byId('ni_desc')?.value||'').trim()||null,
      category:byId('ni_cat')?.value||null,
      make:(byId('ni_make')?.value||'').trim()||null,
      // Minimum Stock Qty (MSV) rides in sub_category, exactly as the Item
      // Master form stores it — a column of its own would need a migration
      // and would orphan everything already saved there.
      sub_category:(byId('ni_msv')?.value||'').trim()||null,
      uom:(byId('ni_uom')?.value||'PCS').trim()||'PCS',
      rate:Number(byId('ni_rate')?.value||0),
      gst_pct:Number(byId('ni_gst')?.value||SARV_DEFAULT_GST),
      /* Three columns a database may not have yet — saveItemRow_ drops
         whichever the server rejects and warnItemColumnsMissing_ names the
         migration, so the rest of the item still saves. Blank stays null
         rather than an empty string, the same as the Item Master form. */
      item_size:(byId('ni_itemSize')?.value||'').trim()||null,
      material_type:(byId('ni_materialType')?.value||'').trim()||null,
      std_order_qty:(byId('ni_stdOrderQty')?.value||'').trim()===''?null:Number(byId('ni_stdOrderQty').value),
      excess_tol_pct:excessTolFromBox_('ni_excessTol')
    };
    const code=(name.replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,28)||'ITEM')+'-'+String(Date.now()).slice(-4);
    const {error,dropped}=await saveItemRow_({item_code:code,...payload},null);
    if(error)throw error;
    warnItemColumnsMissing_(dropped);
    // The shared catalog is refreshed first so the new name already resolves
    // when it lands in the row below; the heavier Item Master reload follows.
    const q=await SB.from('items').select('*').order('name');
    if(!q.error&&q.data)refreshItemDatalist(q.data);
    closeNewItemMasterModal();
    fillNewItemIntoEntryRow_(name);
    showToast('"'+name+'" added to the Item Master');
    if(typeof loadItemMaster==='function')loadItemMaster().catch(()=>{});
  }catch(e){dbError(e);}
  finally{if(btn){btn.disabled=false;btn.innerHTML='Save Item';}}
}
/* Drops the new name into the first empty Item Name box of the entry that
   asked for it, adding a row when every one is filled, and runs the normal
   autofill so Description / Category / UOM / GST arrive with it. */
function fillNewItemIntoEntryRow_(name){
  const t=SARV_NEW_ITEM_TARGETS[sarvNewItemTarget]||SARV_NEW_ITEM_TARGETS.inward;
  const tb=byId(t.body);
  if(!tb)return;
  // The PR grid's rows are plain <tr>; the two store grids interleave
  // .po-info-row sub-rows, which carry no name box — querySelectorAll on the
  // name class skips them either way.
  let box=[...tb.querySelectorAll(t.nameSel)].find(el=>!String(el.value||'').trim());
  if(!box){const tr=t.add();box=tr&&tr.querySelector(t.nameSel);}
  if(!box)return;
  box.value=name;
  applyItemAutofill(name,box.closest('tr'),sarvNewItemTarget,true);
  box.focus();
  t.totals();
}
window.openNewItemMasterModal=openNewItemMasterModal;
function itemGst_(it){
  const raw=it&&it.gst_pct;
  if(raw==null||String(raw).trim()==='')return SARV_DEFAULT_GST;
  const n=Number(raw);
  return isNaN(n)?SARV_DEFAULT_GST:n;
}
/* Item Size / Material Type / Standard Order Qty — three more properties that
   belong to the PART rather than to a particular purchase. Read through
   helpers for the same reason itemMsv_ exists: on a database where the
   migration has not been run yet the column simply is not on the row, and
   every caller has to treat that as "not set" rather than as undefined. */
/* Feeds the Item Size / Material Type suggestion lists from what the master
   already holds, so the store's own vocabulary gets offered back instead of a
   dropdown someone has to maintain. Both inputs stay free text — a suggestion
   list never rejects anything typed past it. */
function refreshItemAttributeDatalists_(items){
  const fill=(dlId,vals)=>{
    const dl=byId(dlId);if(!dl)return;
    dl.innerHTML=[...new Set(vals.filter(Boolean))]
      .sort((a,b)=>a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'}))
      .map(v=>'<option value="'+escText(v)+'">').join('');
  };
  // Make / Brand gets the same treatment as Item Size and Material Type: the
  // Item Master form's own box offers back every brand already on file, so the
  // same make is not re-spelled three ways across the catalogue.
  fill('dl-mi-make',(items||[]).map(it=>{const v=it&&it.make;return String(v==null?'':v).trim()||null}));
  fill('dl-mi-itemSize',(items||[]).map(itemSize_));
  fill('dl-mi-materialType',(items||[]).map(itemMaterial_));
  /* Description, on the same footing: "100GM CONE" is written once and then
     offered back to every item that shares it, instead of being retyped as
     "100 GM CONE" and "100gm cone" on the next two. */
  fill('dl-mi-itemDesc',(items||[]).map(it=>{const v=it&&it.description;return String(v==null?'':v).trim()||null}));
  /* ITEM NAME. Two things make it its own loop rather than another fill():
       • PLAIN names only — never the "NAME [ITEM_CODE]" form the Inward /
         Outward / PR boxes use for duplicated names. Those boxes RESOLVE what
         is picked back to an item; this one SAVES it as the name, so a tagged
         value would land a bracketed code in the master.
       • Each option carries "Category — Description" as its label, which the
         browser prints beside the value. Names here run long and alike
         ("BEARING 6204", "BEARING 6204 ZZ"), and that one line is what tells
         them apart without leaving the box.
     Deduped case-insensitively: two rows already sharing a name — which the
     master allows historically — must not offer the same text twice. */
  {
    const dl=byId('dl-mi-itemName');
    if(dl){
      const seen=new Set(),opts=[];
      (items||[]).forEach(it=>{
        const n=String((it&&it.name)||'').trim();
        if(!n)return;
        const k=n.toUpperCase();
        if(seen.has(k))return;
        seen.add(k);
        opts.push({n,hint:[it.category,it.description]
          .map(x=>String(x==null?'':x).trim()).filter(Boolean).join(' — ')});
      });
      opts.sort((a,b)=>a.n.localeCompare(b.n,undefined,{numeric:true,sensitivity:'base'}));
      dl.innerHTML=opts.map(o=>'<option value="'+escText(o.n)+'">'+escText(o.hint)+'</option>').join('');
    }
  }
}
/* ── "This name is already in the master" ─────────────────────────────
   The Item Name box now offers every name already on file, so the one thing
   it can be used to do by accident is pick a name that exists — which
   addMasterItem refuses, and rightly: the entry forms match typed names back
   to the master and the list pools balances by name, so two rows sharing one
   would merge two different items' stock.

   Said HERE, as the name is typed, that dead end becomes the useful half of
   the dropdown: it answers "is this part already in the master?" before the
   rest of the form is filled in, and offers that row for editing instead.

   Nothing is auto-filled on a pick. Category, UOM, Rate and the rest may
   already have been typed, and a dropdown that quietly overwrote them would
   be worse than no dropdown. */
function miSyncItemNameHint_(){
  const box=byId('mi_itemNameHint');if(!box)return;
  const typed=String(byId('mi_itemName')?.value||'').trim().toUpperCase();
  // The Item Master panel's own list where it is loaded, the shared catalogue
  // otherwise — this form can be opened before loadItemMaster has answered.
  const pool=(sarvItemMasterRows||[]).length?sarvItemMasterRows.map(r=>r.it):(sarvItemCatalog||[]);
  // An item being EDITED is not a clash with itself.
  const hit=typed?pool.find(it=>it&&String(it.name||'').trim().toUpperCase()===typed
    &&String(it.id)!==String(sarvEditingItemId)):null;
  if(!hit){box.style.display='none';box.innerHTML='';return;}
  const canEdit=sarvCan('EDIT');
  box.innerHTML='<b>'+escText(hit.name)+'</b> is already in the master'
    +(hit.item_code?(' <span style="color:#92400e;">('+escText(hit.item_code)+')</span>'):'')
    +'; a new item with this name will not be saved.'
    +(canEdit?' <a href="#" id="mi_itemNameEditLink" style="color:#b45309;font-weight:800;">Edit that item instead</a>':'');
  box.style.display='block';
  /* Bound, not an inline onclick: an id goes into that attribute, and a uuid
     through escText would come back with its quotes escaped into the JS. */
  if(canEdit)byId('mi_itemNameEditLink')?.addEventListener('click',e=>{
    e.preventDefault();editMasterItem(hit.id);
  });
}
function itemSize_(it){const v=it&&it.item_size;return String(v==null?'':v).trim()||null}
function itemMaterial_(it){const v=it&&it.material_type;return String(v==null?'':v).trim()||null}
function itemStdOrderQty_(it){
  const raw=it&&it.std_order_qty;
  if(raw==null||String(raw).trim()==='')return null;
  const n=Number(raw);
  return isNaN(n)?null:n;
}
/* ── PO Excess Allowed % ─────────────────────────────────────────────
   How far over its PO line this item may be received — qty AND weight, at
   the PO's own rate — without going to the MD for Inward Approval. Suppliers
   of yarn, fabric, chemicals and the like cannot cut a delivery to the exact
   kilo, and sending every 2 % overrun to the MD buried the real exceptions.
   Measured on the PO line's ordered qty / weight, CUMULATIVELY across all
   receipts against that line (docStripParts_ already counts what came before),
   so three small overruns cannot add up past the limit. Past it, or at any
   other rate, the MD approves as before — see inwardDocOverrides.
   5 % for every item with nothing saved (a database without the column, or an
   item saved before it existed); 0 means "no excess at all without the MD". */
const SARV_DEFAULT_EXCESS_TOL=5;
function itemExcessTol_(it){
  const raw=it&&it.excess_tol_pct;
  if(raw==null||String(raw).trim()==='')return SARV_DEFAULT_EXCESS_TOL;
  const n=Number(raw);
  return isNaN(n)||n<0?SARV_DEFAULT_EXCESS_TOL:n;
}
// The Item Master row behind an Inward row: the pinned id first, else the name.
function itemForInwardRow_(r){
  const id=String((r&&r.itemId)||'');
  const cat=sarvItemCatalog||[];
  if(id){const hit=cat.find(it=>String(it.id)===id);if(hit)return hit;}
  const n=String((r&&r.name)||'').trim().toLowerCase();
  return n?(cat.find(it=>String(it.name||'').trim().toLowerCase()===n)||null):null;
}
// The value an Excess % box saves: blank or nonsense falls back to the 5 % default, capped at 100.
function excessTolFromBox_(id){
  const raw=String(byId(id)?.value||'').trim();
  const n=Number(raw);
  if(raw===''||isNaN(n)||n<0)return SARV_DEFAULT_EXCESS_TOL;
  return Math.min(100,n);
}
function isBelowMsv_(row){
  const msv=itemMsv_(row.it);
  return msv!=null&&msv>0&&row.bal<msv;
}
/* Sortable columns, and how each one's value is read off a row. The text
   columns sort alphabetically, the numeric ones by value — a Code like
   "ITEM-9" must sit next to "ITEM-10" by name, not by number. */
const SARV_ITEM_SORTERS={
  code:{text:true, get:r=>r.it.item_code},
  name:{text:true, get:r=>r.it.name},
  cat: {text:true, get:r=>r.it.category},
  size:{text:true, get:r=>itemSize_(r.it)},
  mat: {text:true, get:r=>itemMaterial_(r.it)},
  msv: {text:false,get:r=>itemMsv_(r.it)},
  soq: {text:false,get:r=>itemStdOrderQty_(r.it)},
  xtol:{text:false,get:r=>itemExcessTol_(r.it)},
  in:  {text:false,get:r=>r.inQty},
  out: {text:false,get:r=>r.outQty},
  bal: {text:false,get:r=>r.bal},
  pipe:{text:false,get:r=>r.pipe==null?null:r.pipe}
};
/* Sort state. key===null means the list keeps the name order it arrives in. */
let sarvItemMasterSort={key:null,dir:1};
window.sortItemMaster=function(key){
  // Same column again flips the direction; a different column starts ascending.
  if(sarvItemMasterSort.key===key)sarvItemMasterSort.dir=-sarvItemMasterSort.dir;
  else sarvItemMasterSort={key,dir:1};
  renderItemMasterTable();
};
function updateItemMasterSortIndicators_(){
  Object.keys(SARV_ITEM_SORTERS).forEach(k=>{
    const el=byId('imSort-'+k);if(!el)return;
    const on=sarvItemMasterSort.key===k;
    el.innerHTML=on?(sarvItemMasterSort.dir===1?'&#9650;':'&#9660;'):'&#8693;';
    el.style.opacity=on?'1':'0.35';
  });
}
window.renderItemMasterTable=function(){
  const tb=byId('itemMasterBody'),cnt=byId('itemMasterCount');
  if(!tb)return;
  const q=(byId('itemMasterSearch')?.value||'').toLowerCase().trim();
  const msvFilter=byId('itemMasterMsvFilter')?.value||'ALL';
  imPruneSlicers_();
  const hiddenCols=imApplyColVisibility_();
  /* The search box and the Stock dropdown live in imBasePass_, the column
     filters in imColPass_, and imRowPass_ puts them together — the same three
     functions the dependent option lists use. One code path, so what a column
     filter OFFERS and what the table then SHOWS can never disagree. */
  const rows=sarvItemMasterRows.filter(row=>imRowPass_(row,null));
  const sorter=SARV_ITEM_SORTERS[sarvItemMasterSort.key];
  if(sorter){
    const dir=sarvItemMasterSort.dir;
    rows.sort((a,b)=>{
      let x=sorter.get(a),y=sorter.get(b);
      if(sorter.text){x=String(x==null?'':x).trim()||null;y=String(y==null?'':y).trim()||null;}
      // A missing value — no MSV, a blank Category — stays at the bottom in
      // BOTH directions. It isn't "smaller than zero" or "before A"; it simply
      // isn't part of the comparison, and flipping it to the top on a
      // descending sort would bury the rows that were actually asked for.
      if(x==null&&y==null)return 0;
      if(x==null)return 1;
      if(y==null)return -1;
      // localeCompare with numeric:true keeps ITEM-2 before ITEM-10.
      return (sorter.text?String(x).localeCompare(String(y),undefined,{numeric:true,sensitivity:'base'}):(x-y))*dir;
    });
  }
  /* Exactly the rows on screen, in the order they are on screen — kept here so
     Download CSV / PDF export WHAT IS BEING LOOKED AT rather than re-deriving
     it. Re-deriving would mean a second copy of the filter chain and the sort,
     and the day the two read differently the export would quietly be of some
     other list. Set before the two early returns below, so an emptied filter
     leaves it empty rather than stale. */
  sarvItemMasterShown=rows;
  updateItemMasterSortIndicators_();
  imRenderFilterIndicators_();
  imRenderSlicers_();
  // The chip bar appears and disappears with the filters, which moves the top
  // of the list — so the height is re-fitted on every render, not just on load.
  fitItemListHeight_();
  const activeCols=imActiveCols_();
  const slicerOn=imActiveSlicerCols_().length>0;
  const filterActive=activeCols.length>0||slicerOn||!!q||msvFilter!=='ALL';
  if(cnt)cnt.textContent=filterActive?`${rows.length} of ${sarvItemMasterRows.length} items`:`${sarvItemMasterRows.length} items`;
  if(!sarvItemMasterRows.length){
    tb.innerHTML='<tr><td colspan="20" style="text-align:center;padding:20px;color:#94a3b8;">No items yet — Add your first item above</td></tr>';
    return;
  }
  if(!rows.length){
    /* An empty list has to say WHICH filter emptied it, and give the way out
       in the same breath. "No items match" on its own is how someone decides
       their Item Master has lost its data. */
    const why=(activeCols.length||slicerOn)
      ? 'No items left after these filters: '
        +activeCols.map(c=>SARV_IM_FILTER_COLS[c].label+' ('+imFilterSummary_(c)+')')
          .concat(imSlicerSummary_().map(s=>'Slicer '+s)).join(', ')
      : msvFilter==='BELOW'?'No item is below its MSV (items without an MSV are not included in this filter).'
      : msvFilter==='ABOVE'?'No item is above its MSV (items without an MSV are not included in this filter).'
      : 'No item matches this search.';
    tb.innerHTML='<tr><td colspan="20" style="text-align:center;padding:20px;color:#94a3b8;">'+escText(why)
      +(activeCols.length||slicerOn?'<br>':'')
      +(activeCols.length?'<button type="button" onclick="imClearAllFilters()" style="margin-top:8px;background:#fef2f2;border:1px solid #fecaca;color:#b91c1c;border-radius:12px;padding:4px 14px;font-size:11px;font-weight:800;cursor:pointer;">&#10006; Clear All Filters</button>':'')
      +(slicerOn?'<button type="button" onclick="imClearSlicers()" style="margin:8px 0 0 6px;background:#f5f3ff;border:1px solid #ddd6fe;color:#6d28d9;border-radius:12px;padding:4px 14px;font-size:11px;font-weight:800;cursor:pointer;">&#10006; Clear Slicers</button>':'')
      +'</td></tr>';
    return;
  }
  let totalIn=0,totalOut=0,totalBal=0,totalPipe=0;
  /* Display only: a whole number stays as it is (12), a decimal one is
     rounded to two places (12.345 → 12.35, 0.1+0.2 → 0.30). The MSV check,
     sorting and filters still work on the exact figures. */
  const q2=v=>{const n=Number(v);if(v==null||v===''||!isFinite(n))return v;return Number.isInteger(n)?String(n):n.toFixed(2);};
  // Admin Panel › Tab Visibility › Item Master › New PR Generation (default: Admin only).
  const prAdmin=sarvTabVisible('MD_ITEM_NEWPR');
  byId('itemMasterTable')?.classList.toggle('im-hide-newpr',!prAdmin);
  const bodyRows=rows.map((row,i)=>{
    const{it,inQty,outQty,bal}=row;
    totalIn+=inQty;totalOut+=outQty;totalBal+=bal;totalPipe+=pNum(row.pipe);
    const balColor=bal>0?'#166534':bal<0?'#dc2626':'#64748b';
    // Minimum Stock Value — read through the same helper the stock filter and
    // the sort use, so the red low-stock flag and the "Below the MSV" view can
    // never disagree about what counts as below.
    const msv=itemMsv_(it);
    const soq=itemStdOrderQty_(it);
    const below=isBelowMsv_(row);
    return `<tr style="border-bottom:1px solid #f1f5f9;font-size:11px;" data-id="${it.id}">
        <td style="padding:5px 6px;text-align:center;color:#94a3b8;">${i+1}</td>
        <td data-imc="code" style="padding:5px 6px;font-weight:700;color:#0369a1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${escText(it.item_code)}">${escText(it.item_code)}</td>
        <td data-imc="name" style="padding:5px 6px;font-weight:700;">${escText(it.name)}</td>
        <td data-imc="desc" style="padding:5px 6px;color:#64748b;">${escText(it.description||'—')}</td>
        <td data-imc="cat" style="padding:5px 6px;">${escText(it.category||'—')}</td>
        <td data-imc="size" style="padding:5px 6px;text-align:center;font-weight:600;color:#334155;">${escText(itemSize_(it)||'—')}</td>
        <td data-imc="mat" style="padding:5px 6px;color:#334155;">${escText(itemMaterial_(it)||'—')}</td>
        <td data-imc="rate" style="padding:5px 6px;text-align:right;">₹${Number(it.rate||0).toFixed(2)}</td>
        <td data-imc="gst" style="padding:5px 6px;text-align:center;color:#334155;">${itemGst_(it)}%</td>
        <td data-imc="uom" style="padding:5px 6px;text-align:center;font-weight:700;">${escText(it.uom||'PCS')}</td>
        <td data-imc="make" style="padding:5px 6px;color:#64748b;">${escText(it.make||'—')}</td>
        <td data-imc="msv" style="padding:5px 6px;text-align:center;font-weight:600;color:#475569;">${msv!=null?q2(msv):'—'}</td>
        <td data-imc="soq" style="padding:5px 6px;text-align:center;font-weight:600;color:#475569;">${soq!=null?q2(soq):'—'}</td>
        <td data-imc="xtol" style="padding:5px 6px;text-align:center;font-weight:600;color:#7c3aed;" title="Up to this % over the PO line (qty / weight, same rate) is received without MD Inward Approval${it.excess_tol_pct==null||String(it.excess_tol_pct).trim()===''?' · default':''}">${q2(itemExcessTol_(it))}%</td>
        <td data-imc="in" style="padding:5px 6px;text-align:center;font-weight:600;color:#15803d;">${q2(inQty)}</td>
        <td data-imc="out" style="padding:5px 6px;text-align:center;font-weight:600;color:#b91c1c;">${q2(outQty)}</td>
        <td data-imc="bal" style="padding:5px 6px;text-align:center;background:${below?'#fee2e2':'transparent'};font-weight:700;color:${below?'#b91c1c':balColor};"${below?` title="Balance ${q2(bal)} is below the minimum stock qty of ${q2(msv)}"`:''}>${q2(bal)}${below?'':''}</td>
        <td data-imc="pipe" style="padding:5px 6px;text-align:center;">${imPipeCell_(it,q2)}</td>
        <td class="im-newpr-col" style="padding:5px 6px;text-align:center;"><input type="checkbox" class="im-pr-sel" data-id="${it.id}"${sarvItemPrSel.has(String(it.id))?' checked':''}${prAdmin?'':' disabled'} title="${prAdmin?(soq!=null?'Qty '+soq+' on the New PR (Std Order Qty)':'No Std Order Qty set; enter the qty on the PR yourself'):'Only the Admin can tick this'}" style="width:14px;height:14px;cursor:${prAdmin?'pointer':'not-allowed'};"></td>
        <td style="padding:5px 6px;text-align:center;">
          ${(sarvCan('EDIT')||sarvCan('DELETE'))?`${sarvCan('EDIT')?`<button onclick="editMasterItem('${it.id}')" style="background:#eff6ff;border:1px solid #93c5fd;color:#1d4ed8;border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;margin-right:4px;" title="Edit ${escText(it.item_code||'')} : change the item details">✎</button>`:''}${sarvCan('DELETE')?`<button onclick="deleteMasterItem('${it.id}')" style="background:#fef2f2;border:1px solid #fca5a5;color:#dc2626;border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;" title="Delete">✕</button>`:''}`:'<span style="color:#cbd5e1;">—</span>'}
        </td>
      </tr>`;
  }).join('');
  // Subtotal row pinned at the top of the item list, above all rows,
  // reflecting whatever the current search/category filter is showing.
  // colspan is 11: the label runs from # through Make. MSV and Standard Order
  // Qty then sit between Make and IN Qty, both unsummed — a minimum stock
  // level and a standard order size are per-item settings, and adding them up
  // across the list would be a number that means nothing.
  // Columns hidden from the Columns popup drop out of that span, or the
  // figures would slide out from under their own headers.
  const labelSpan=1+IM_LABEL_COLS.filter(k=>!hiddenCols.has(k)).length;
  const totalsRow=`<tr style="background:#f1f5f9;color:#0f172a;font-weight:700;border-bottom:2px solid #cbd5e1;">
      <td colspan="${labelSpan}" style="padding:6px 8px;text-align:right;">SUBTOTAL (${rows.length} shown)</td>
      <td data-imc="msv" style="padding:6px;text-align:center;color:#94a3b8;">—</td>
      <td data-imc="soq" style="padding:6px;text-align:center;color:#94a3b8;">—</td>
      <td data-imc="xtol" style="padding:6px;text-align:center;color:#94a3b8;">—</td>
      <td data-imc="in" style="padding:6px;text-align:center;color:#15803d;">${q2(totalIn)}</td>
      <td data-imc="out" style="padding:6px;text-align:center;color:#b91c1c;">${q2(totalOut)}</td>
      <td data-imc="bal" style="padding:6px;text-align:center;color:${totalBal<0?'#b91c1c':'#0f172a'};">${q2(totalBal)}</td>
      <td data-imc="pipe" style="padding:6px;text-align:center;color:#1d4ed8;" title="Pending PR / PO qty of the items shown">${sarvImPipe?q2(totalPipe):'…'}</td>
      <td class="im-newpr-col" style="padding:6px;text-align:center;" title="Ticked for New PR">${sarvItemPrSel.size||'—'}</td>
      <td></td>
    </tr>`;
  tb.innerHTML=totalsRow+bodyRows;
  sarvSyncItemPrSelUi_();
};
/* ══ ITEM MASTER → CSV / PDF ════════════════════════════════════════
   What the two buttons above the list download.

   Both export the FILTERED list — whatever the search box, the Stock dropdown
   and the column filters have left on screen, in the order the column sort put
   it in. sarvItemMasterShown is that exact set, stashed by
   renderItemMasterTable, so neither file can be of a different list from the
   one being looked at.

   Why this replaced exportTableCSV() on this table: that helper scrapes the
   rendered DOM, which on this table meant
     • headers carrying the sort arrow and the filter caret — "Code⇕▾";
     • a "#" serial column, the NEW PR tick column and the column, none of
       which are data;
     • Rate as "₹1,234.00", GST as "18%", Balance as "12" — text, so a
       spreadsheet can neither sum nor sort any of it.
   The columns below are the ones the Item Master actually holds, each read
   through the SAME helper the table reads (itemMsv_ / itemStdOrderQty_ /
   itemSize_ / itemMaterial_ / itemGst_), so a figure on paper is the figure on
   screen. The flag becomes a column of its own — Stock Status — because a
   warning sign glued onto a number is unusable in a filter, and BELOW MSV in
   its own column is exactly what somebody sorting a purchase list wants.

   cellWidth is in mm and the sixteen add up to 281 — the usable width of an
   A4 landscape page at an 8mm margin. Change one and another has to give. */
const IM_EXPORT_COLS=[
  {k:'code', h:'Item Code',           w:20, get:r=>r.it.item_code||''},
  {k:'name', h:'Item Name',           w:34, get:r=>r.it.name||''},
  {k:'desc', h:'Description',         w:32, get:r=>r.it.description||''},
  {k:'cat',  h:'Category',            w:20, get:r=>r.it.category||''},
  {k:'size', h:'Size',                w:15, tint:[236,254,255], get:r=>itemSize_(r.it)||''},
  {k:'mat',  h:'Material',            w:17, tint:[236,254,255], get:r=>itemMaterial_(r.it)||''},
  {k:'rate', h:'Rate',                w:14, num:true, money:true, get:r=>Number(r.it.rate||0)},
  {k:'gst',  h:'GST %',               w:10, num:true, tint:[245,243,255], get:r=>itemGst_(r.it)},
  {k:'uom',  h:'UOM',                 w:11, get:r=>r.it.uom||'PCS'},
  {k:'make', h:'Make',                w:17, get:r=>r.it.make||''},
  {k:'msv',  h:'Min Stock Qty (MSV)', w:16, num:true, tint:[255,251,235], get:r=>itemMsv_(r.it)},
  {k:'soq',  h:'Std Order Qty',       w:15, num:true, tint:[253,242,248], get:r=>itemStdOrderQty_(r.it)},
  {k:'xtol', h:'PO Excess Allowed %', w:15, num:true, tint:[245,243,255], get:r=>itemExcessTol_(r.it)},
  {k:'in',   h:'IN Qty',              w:14, num:true, total:true, tint:[240,253,244], get:r=>r.inQty},
  {k:'out',  h:'OUT Qty',             w:14, num:true, total:true, tint:[254,242,242], get:r=>r.outQty},
  {k:'bal',  h:'Balance Qty',         w:15, num:true, total:true, tint:[239,246,255], lowFlag:true, get:r=>r.bal},
  // Open PO qty still to come in + PR qty not yet on any PO (imLoadPipeline_).
  // Blank if the lookup hasn't finished, rather than a misleading 0.
  {k:'pipe', h:'Pending PR / PO Qty', w:16, num:true, total:true, get:r=>r.pipe==null?null:r.pipe},
  // Blank where the item has no MSV: it cannot be judged against one, which is
  // the same reason such items fall out of both Stock filter views.
  {k:'stk',  h:'Stock Status',        w:17, center:true, lowFlag:true,
             get:r=>itemMsv_(r.it)==null?'':(isBelowMsv_(r)?'BELOW MSV':'OK')}
];
/* Which of those sixteen go into the file — chosen in the popup both download
   buttons now open, and remembered per browser so the same report does not
   have to be re-ticked every day. `k` is what is stored, never the index: a
   column inserted into the list above must not silently shift somebody's
   saved choice onto its neighbour.
   Unknown keys (a saved choice from a build that had a column this one does
   not) are dropped on read, and an empty / unreadable selection falls back to
   all sixteen — the behaviour before the popup existed. */
const IM_EXPORT_SEL_KEY='sarv_im_export_cols';
function imExportSelKeys_(){
  let saved=null;
  try{saved=JSON.parse(localStorage.getItem(IM_EXPORT_SEL_KEY)||'null');}catch(e){}
  const all=IM_EXPORT_COLS.map(c=>c.k);
  if(!Array.isArray(saved))return all;
  const keep=saved.filter(k=>all.includes(k));
  return keep.length?keep:all;
}
function imExportSaveSelKeys_(keys){
  try{localStorage.setItem(IM_EXPORT_SEL_KEY,JSON.stringify(keys));}catch(e){}
}
// Always in the order of IM_EXPORT_COLS, never the order they were ticked in:
// a report whose columns move around between downloads cannot be compared with
// last week's copy of itself.
function imExportSelCols_(){
  const keys=new Set(imExportSelKeys_());
  return IM_EXPORT_COLS.filter(c=>keys.has(c.k));
}
/* One line saying what the file is OF. Printed on the PDF and written as the
   CSV's first line, because a filtered export that does not say what it was
   filtered by gets mailed on and read as the whole Item Master. */
function imFilterText_(){
  const bits=[];
  const q=String(byId('itemMasterSearch')?.value||'').trim();
  if(q)bits.push('Search: "'+q+'"');
  const msv=byId('itemMasterMsvFilter')?.value||'ALL';
  if(msv==='BELOW')bits.push('Stock: Below the MSV');
  else if(msv==='ABOVE')bits.push('Stock: Above the MSV');
  // The same labels and the same summaries the filter chips show on screen.
  imActiveCols_().forEach(c=>bits.push(SARV_IM_FILTER_COLS[c].label+': '+imFilterSummary_(c)));
  imSlicerSummary_().forEach(s=>bits.push('Slicer '+s));
  const srt=SARV_ITEM_SORTERS[sarvItemMasterSort&&sarvItemMasterSort.key];
  const sortTxt=srt?('Sorted by '+(SARV_IM_FILTER_COLS[sarvItemMasterSort.key]||{label:sarvItemMasterSort.key}).label
    +' ('+(sarvItemMasterSort.dir<0?'descending':'ascending')+')'):'';
  if(!bits.length)return 'Filter: none (the whole Item Master)'+(sortTxt?('   ·   '+sortTxt):'');
  return bits.join('   ·   ')+(sortTxt?('   ·   '+sortTxt):'');
}
/* The rows to export, or null after saying why there are none. Deliberately
   refuses rather than writing a header-only file: a 1-line CSV looks like the
   data is gone, and the reason is always a filter that is still on screen. */
function imExportRows_(what){
  const rows=(sarvItemMasterShown||[]).filter(Boolean);
  if(!rows.length){
    showToast('No items for '+what+'; the list is empty. Check the search / filter first.'
      +(imActiveCols_().length?' (or press <b>Clear All Filters</b>)':''),'warn');
    return null;
  }
  return rows;
}
// Figures as NUMBERS in the CSV — no ₹, no %, no — so Excel can sum, sort
// and pivot them. A blank stays blank: 0 and "not set" are different answers
// (an item with no MSV has not been given one; an MSV of 0 has).
function imCsvCell_(col,row){
  const v=col.get(row);
  if(!col.num)return v==null?'':String(v);
  if(v==null||v==='')return '';
  const n=Number(v);
  if(!isFinite(n))return '';
  return col.money?Number(n.toFixed(2)):Number(n.toFixed(3));
}
function imRunExportCsv_(cols){
  cols=(cols&&cols.length)?cols:imExportSelCols_();
  const rows=imExportRows_('CSV');if(!rows)return;
  const head=cols.map(c=>c.h);
  const data=rows.map(r=>cols.map(c=>imCsvCell_(c,r)));
  /* The three columns that are a stock position get a TOTAL row, and only
     those three. Rate, GST, MSV and Std Order Qty are per-item settings —
     adding them down the list produces a number that means nothing, which is
     also why the on-screen SUBTOTAL row leaves them as "—". Last row, not
     first, so the sheet can be sorted or filtered without a total landing in
     the middle of the data. */
  const sum=c=>rows.reduce((s,r)=>s+pNum(c.get(r)),0);
  /* The label goes in the first column that is NOT being totalled — otherwise
     a selection that leads with IN Qty would have its own total overwritten by
     the word "TOTAL". With nothing but figures selected there is nowhere to put
     it, and the row is figures alone. */
  const labelAt=cols.findIndex(c=>!c.total);
  const totals=cols.map((c,i)=>i===labelAt?('TOTAL — '+rows.length+' item(s)')
    :(c.total?Number(sum(c).toFixed(3)):''));
  /* Header on ROW 1, nothing above it. A title / "filtered by" banner was
     tried here and taken out: it pushes the header to row 2, and every
     spreadsheet import, pivot table and VLOOKUP on the other side reads row 1
     as the header. What the file was filtered by is said in the toast instead,
     and printed in full on the PDF, which is a report rather than a dataset. */
  downloadCSV('SARV_Item_Master_'+today()+'.csv',[head,...data,totals]);
  showToast('CSV downloaded — '+rows.length+' item'+(rows.length===1?'':'s')
    +' of '+(sarvItemMasterRows||[]).length+' · '+cols.length+' column'+(cols.length===1?'':'s')
    +'<br><span style="font-size:10px;">'+escText(imFilterText_())+'</span>');
}
async function imRunExportPdf_(cols){
  cols=(cols&&cols.length)?cols:imExportSelCols_();
  const rows=imExportRows_('PDF');if(!rows)return;
  if(!jspdfNativeReady_())return showToast('jsPDF did not load. Please refresh the page.','error');
  const {jsPDF}=window.jspdf;
  const doc=new jsPDF({unit:'mm',format:'a4',orientation:'landscape'});
  const pageW=doc.internal.pageSize.getWidth(),pageH=doc.internal.pageSize.getHeight();
  const M=8,W=pageW-M*2;
  let y=M;
  try{
    const logoW=24,logoH=logoW*161/320;
    doc.addImage(SARV_LOGO_DATA_URL,'PNG',pageW-M-logoW,y,logoW,logoH);
  }catch(e){}
  doc.setFont(undefined,'bold');doc.setFontSize(13);doc.setTextColor(10,58,94);
  doc.text(SARV_COMPANY.fullName,M,y+5);
  doc.setFontSize(9.5);doc.setTextColor(0,0,0);
  doc.text(SARV_COMPANY.unit+' — ITEM MASTER',M,y+10.5);
  doc.setFont(undefined,'normal');doc.setFontSize(7);doc.setTextColor(71,85,105);
  doc.text(doc.splitTextToSize(imFilterText_(),W-30),M,y+15);
  doc.text('Printed On: '+pStamp()+'   ·   '+rows.length+' item(s) of '+(sarvItemMasterRows||[]).length,M,y+19.5);
  doc.setTextColor(0,0,0);
  y+=23;
  // Printed the way the screen prints them: a whole number plain, a decimal to
  // two places. Same rule as renderItemMasterTable's q2.
  const q2=v=>{if(v==null||v==='')return '';const n=Number(v);if(!isFinite(n))return '';
    return Number.isInteger(n)?String(n):n.toFixed(2);};
  const cell=(c,r)=>{
    const v=c.get(r);
    if(!c.num)return v==null?'':String(v);
    return c.money?((v===0||v)?nNum_(v):''):q2(v);
  };
  const body=rows.map(r=>cols.map(c=>cell(c,r)));
  const sum=c=>rows.reduce((s,r)=>s+pNum(c.get(r)),0);
  /* Footer totals for the stock columns only — the same ones the on-screen
     SUBTOTAL row adds up, for the same reason. colSpan swallows the columns
     before the first of them so the label sits against the figures; with none
     of them selected there is nothing to total and the footer is dropped
     rather than printed as an empty band. */
  const firstTotal=cols.findIndex(c=>c.total);
  let foot=[];
  if(firstTotal>0){
    // The usual shape: descriptive columns lead, so one merged cell carries
    // the label right up against the figures.
    foot=[[{content:'TOTAL — '+rows.length+' item(s)',colSpan:firstTotal,
            styles:{halign:'right',fontStyle:'bold'}}]
      .concat(cols.slice(firstTotal).map(c=>c.total?q2(sum(c)):''))];
  }else if(firstTotal===0){
    // A selection that LEADS with a stock figure — there is no column in front
    // of it to merge the label into, so the footer is the figures alone.
    foot=[cols.map(c=>c.total?q2(sum(c)):'')];
  }
  /* Widths are declared for the full sixteen columns and add up to the page.
     A SUBSET would leave the table short of the right margin — or, if more
     were ever added, run off it — so they are scaled to whatever was picked.
     tableWidth:W keeps autoTable honest about the total either way. */
  const wSum=cols.reduce((s,c)=>s+c.w,0)||1;
  const colStyles={};
  cols.forEach((c,i)=>{
    colStyles[i]={cellWidth:c.w*W/wSum};
    if(c.num)colStyles[i].halign='right';
    if(c.center)colStyles[i].halign='center';
    if(i===0)colStyles[i].fontStyle='bold';
  });
  doc.autoTable({
    head:[cols.map(c=>c.h)],body,foot,startY:y,
    margin:{left:M,right:M,top:M},tableWidth:W,
    styles:{fontSize:6,cellPadding:1.1,overflow:'linebreak',textColor:[0,0,0],
            lineColor:[203,213,225],lineWidth:0.15,valign:'middle'},
    headStyles:{fillColor:[15,23,42],textColor:[255,255,255],fontStyle:'bold',
                halign:'center',fontSize:5.6,lineWidth:0.15},
    footStyles:{fillColor:[241,245,249],textColor:[15,23,42],fontStyle:'bold',
                halign:'right',lineWidth:0.15},
    columnStyles:colStyles,
    theme:'grid',
    /* The print keeps the screen's own column tints, so the paper and the
       browser are the same document. And a row BELOW its MSV is the one thing
       this list exists to catch, so its Balance and Stock Status cells go red
       and bold here exactly as they do on screen.
       Both are read off the COLUMN OBJECT (c.tint / c.lowFlag), never off the
       column index: the user picks which columns to print, so index 14 is no
       longer necessarily Balance Qty. */
    didParseCell:h=>{
      if(h.section!=='body')return;
      const c=cols[h.column.index];if(!c)return;
      if(c.tint)h.cell.styles.fillColor=c.tint;
      const r=rows[h.row.index];if(!r)return;
      const below=itemMsv_(r.it)!=null&&isBelowMsv_(r);
      if(below&&c.lowFlag){
        h.cell.styles.fillColor=[254,226,226];
        h.cell.styles.textColor=[185,28,28];
        h.cell.styles.fontStyle='bold';
      }else if(c.k==='bal'&&pNum(r.bal)<0){
        h.cell.styles.textColor=[220,38,38];h.cell.styles.fontStyle='bold';
      }
    }
  });
  const pages=doc.internal.getNumberOfPages();
  for(let i=1;i<=pages;i++){
    doc.setPage(i);doc.setFontSize(6.5);doc.setTextColor(100,116,139);
    doc.text(SARV_COMPANY.juris,M,pageH-5);
    doc.text('Page '+i+' of '+pages,pageW-M,pageH-5,{align:'right'});
  }
  const name='SARV_Item_Master_'+today()+'.pdf';
  const blob=doc.output('blob');
  downloadBlob(blob,name);
  // Same preview the other reports open with, so the file can be checked (and
  // shared) without hunting through the Downloads folder.
  showSarvPdfPreview(blob,name,'');
  showToast('Item Master PDF ready — '+rows.length+' item'+(rows.length===1?'':'s')
    +' · '+cols.length+' column'+(cols.length===1?'':'s'));
}
/* ══ EXPORT COLUMN PICKER ═══════════════════════════════════════════
   Both download buttons open this first. The list already filters down to a
   handful of items; what nobody could do until now was cut it down to the
   handful of COLUMNS a given report is about — a purchase list wants Code,
   Name, MSV, Balance and nothing else, and a sixteen-column sheet has to be
   edited by hand every time to become one.

   The rows are never in question here: the export is always of the FILTERED
   list, exactly as on screen, which is why the header of this popup states
   how many rows and under which filters rather than offering a choice about
   it. Only the columns are chosen, and the choice is remembered per browser
   (IM_EXPORT_SEL_KEY) so a daily report is ticked once, not daily.

   Built on demand and reused, like the PO Details overlay — markup that only
   exists once somebody asks for it cannot be left half-wired in the page. */
function imCloseExportPick(){const ov=byId('imExportPickOverlay');if(ov)ov.style.display='none';}
window.imCloseExportPick=imCloseExportPick;
function imOpenExportPick_(kind){
  // Nothing to export: say so here rather than after the columns are chosen.
  if(!imExportRows_(kind||'Download'))return;
  let ov=byId('imExportPickOverlay');
  if(!ov){
    ov=document.createElement('div');
    ov.id='imExportPickOverlay';
    ov.className='secure-modal-overlay';
    ov.style.cssText='display:none;align-items:center;justify-content:center;z-index:29500;padding:14px;';
    ov.innerHTML='<div style="background:#fff;width:min(560px,96vw);max-height:92vh;border-radius:12px;'
      +'box-shadow:0 25px 60px rgba(0,0,0,.35);display:flex;flex-direction:column;overflow:hidden;">'
      +'<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:#0f172a;color:#fff;">'
        +'<strong id="imxTitle" style="font-size:13px;">Choose columns</strong>'
        +'<span style="flex:1;"></span>'
        +'<button type="button" id="imxClose" style="border:1px solid #64748b;background:transparent;color:#fff;'
        +'border-radius:6px;padding:4px 9px;font-size:15px;cursor:pointer;">&#10005;</button></div>'
      +'<div id="imxScope" style="padding:8px 14px;background:#f8fafc;border-bottom:1px solid #e2e8f0;'
        +'font-size:11px;color:#334155;font-weight:600;"></div>'
      +'<div style="display:flex;align-items:center;gap:8px;padding:8px 14px 4px;">'
        +'<span style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.3px;">'
        +'Only ticked columns go into the CSV / PDF</span>'
        +'<span style="flex:1;"></span>'
        +'<button type="button" id="imxAll" style="background:#f0fdf4;border:1px solid #86efac;color:#15803d;'
        +'border-radius:5px;padding:3px 9px;font-size:10px;font-weight:800;cursor:pointer;">Select All</button>'
        +'<button type="button" id="imxNone" style="background:#fef2f2;border:1px solid #fecaca;color:#b91c1c;'
        +'border-radius:5px;padding:3px 9px;font-size:10px;font-weight:800;cursor:pointer;">Clear</button></div>'
      +'<div id="imxList" style="flex:1;overflow-y:auto;padding:4px 14px 10px;display:grid;'
        +'grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:2px 14px;"></div>'
      +'<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:#f8fafc;'
        +'border-top:1px solid #e2e8f0;">'
        +'<span id="imxCount" style="font-size:11px;font-weight:800;color:#0369a1;"></span>'
        +'<span style="flex:1;"></span>'
        +'<button type="button" class="imx-go" id="imxCsv" style="background:#16a34a;color:#fff;border:0;border-radius:6px;'
        +'padding:7px 14px;font-size:12px;font-weight:800;cursor:pointer;">Download CSV</button>'
        +'<button type="button" class="imx-go" id="imxPdf" style="background:#dc2626;color:#fff;border:0;border-radius:6px;'
        +'padding:7px 14px;font-size:12px;font-weight:800;cursor:pointer;">Download PDF</button>'
        +'<button type="button" id="imxCancel" style="background:#e2e8f0;color:#475569;border:0;border-radius:6px;'
        +'padding:7px 12px;font-size:12px;font-weight:700;cursor:pointer;">Cancel</button></div>'
      +'</div>';
    /* Inside #storeInterface, NOT on <body> — the same place the PO Details
       overlay puts itself, and for the same reason. store.css writes that rule
       as "#storeInterface .secure-modal-overlay" (a comment between the two
       selectors makes it a descendant combinator), so an overlay parked on
       <body> inherits none of its positioning: it comes out position:static
       with no backdrop, i.e. a white slab below the fold. See the
       #pwdGateModal / #sarvNewItemModal note in store.css. */
    (byId('storeInterface')||document.body).appendChild(ov);
    byId('imxClose').addEventListener('click',imCloseExportPick);
    byId('imxCancel').addEventListener('click',imCloseExportPick);
    // Backdrop click closes; a click inside the card must not.
    ov.addEventListener('click',e=>{if(e.target===ov)imCloseExportPick();});
    // Escape too, like every other popup on this screen. Bound to the document
    // once, with the open check inside, so it costs nothing while shut.
    document.addEventListener('keydown',e=>{
      if(e.key==='Escape'&&byId('imExportPickOverlay')?.style.display==='flex')imCloseExportPick();
    });
    byId('imxAll').addEventListener('click',()=>imxSetAll_(true));
    byId('imxNone').addEventListener('click',()=>imxSetAll_(false));
    byId('imxList').addEventListener('change',imxSyncCount_);
    /* One popup, two downloads. The format is chosen AFTER the columns; the
       toolbar used to have two buttons that opened the same popup, now it has
       one and the format is chosen down here. Bound once: neither handler
       closes over anything that changes between openings. */
    const run=fmt=>{
      const keys=[...document.querySelectorAll('#imxList .imx-col:checked')].map(x=>x.value);
      if(!keys.length)return showToast('Tick at least one column','warn');
      imExportSaveSelKeys_(keys);
      const picked=imExportSelCols_();
      imCloseExportPick();
      if(fmt==='PDF')imRunExportPdf_(picked).catch(dbError);
      else imRunExportCsv_(picked);
    };
    byId('imxCsv').addEventListener('click',()=>run('CSV'));
    byId('imxPdf').addEventListener('click',()=>run('PDF'));
  }
  /* The old CSV / PDF entry points (downloadItemMasterCsv / …Pdf) still come
     here; in that case the button for the requested format gets the focus. */
  ov.dataset.kind=kind||'';
  byId('imxTitle').innerHTML='Download: choose columns';
  const rows=(sarvItemMasterShown||[]).length;
  byId('imxScope').innerHTML='<b>'+rows+'</b> item'+(rows===1?'':'s')
    +' will be exported (with the list\'s current filters): <span style="color:#64748b;">'
    +escText(imFilterText_())+'</span>';
  const sel=new Set(imExportSelKeys_());
  byId('imxList').innerHTML=IM_EXPORT_COLS.map(c=>
     '<label style="display:flex;align-items:center;gap:7px;padding:3px 0;font-size:11.5px;'
    +'font-weight:600;color:#0f172a;cursor:pointer;">'
    +'<input type="checkbox" class="imx-col" value="'+escText(c.k)+'"'+(sel.has(c.k)?' checked':'')
    +' style="width:14px;height:14px;cursor:pointer;">'
    +'<span>'+escText(c.h)+'</span></label>').join('');
  imxSyncCount_();
  ov.style.display='flex';
  const pref=kind==='PDF'?byId('imxPdf'):kind==='CSV'?byId('imxCsv'):null;
  if(pref)pref.focus();
}
function imxSetAll_(on){
  document.querySelectorAll('#imxList .imx-col').forEach(cb=>{cb.checked=on;});
  imxSyncCount_();
}
function imxSyncCount_(){
  const el=byId('imxCount');if(!el)return;
  const n=document.querySelectorAll('#imxList .imx-col:checked').length;
  el.textContent=n+' of '+IM_EXPORT_COLS.length+' columns selected';
  el.style.color=n?'#0369a1':'#b91c1c';
  document.querySelectorAll('#imExportPickOverlay .imx-go').forEach(go=>{
    go.disabled=!n;go.style.opacity=n?'1':'.5';go.style.cursor=n?'pointer':'not-allowed';
  });
}
/* What the two toolbar buttons call: pick the columns, then export.

   The workers above are named imRunExportCsv_ / imRunExportPdf_ and NOT
   downloadItemMasterCsv / …Pdf, which is what they were called first. In a
   classic script a top-level `function downloadItemMasterCsv(){}` and
   `window.downloadItemMasterCsv` are the SAME binding, so these two lines
   replaced the workers outright: the picker's Download button called the bare
   name, got the picker-opener back, and re-opened the popup it had just
   closed — "the button does nothing". Separate names, no shadowing. */
window.downloadItemMaster=()=>imOpenExportPick_('');
window.downloadItemMasterCsv=()=>imOpenExportPick_('CSV');
window.downloadItemMasterPdf=()=>imOpenExportPick_('PDF');
/* ── Item Master → New PR ────────────────────────────────────────────
   The Admin ticks items in the NEW PR column (kept across search / filter /
   re-render) and presses Generate New PR: the PR form opens with one row per
   item, qty = its STD ORDER QTY, and Purchaser Name picked from the item's
   Category (category_purchasers) — the same auto-pick a hand-typed row gets.
   Requested By, Required By and the rest are filled in on the form as usual,
   and nothing is saved until Submit. */
const sarvItemPrSel=new Set();
function sarvSyncItemPrSelUi_(){
  const admin=sarvTabVisible('MD_ITEM_NEWPR'),n=sarvItemPrSel.size;
  const btn=byId('imGenPrBtn'),clr=byId('imPrSelClearBtn'),cnt=byId('imPrSelCount');
  if(btn){btn.style.display=admin?'':'none';btn.disabled=!n;btn.style.opacity=n?'1':'.55';}
  if(clr)clr.style.display=(admin&&n)?'':'none';
  if(cnt)cnt.textContent=n;
  const all=byId('imPrSelAll');
  if(all){
    const boxes=[...document.querySelectorAll('#itemMasterBody .im-pr-sel')];
    all.disabled=!admin;all.style.cursor=admin?'pointer':'not-allowed';
    all.checked=boxes.length>0&&boxes.every(b=>b.checked);
    all.indeterminate=!all.checked&&boxes.some(b=>b.checked);
  }
}
window.sarvClearItemPrSel=function(){sarvItemPrSel.clear();renderItemMasterTable();};
// Requested By default for a generated PR. Used by the Trims Manager route
// only: a PR from the Item Master leaves Requested By blank and the user must
// pick the person (sarvPrNeedsRequester_ makes Submit insist on it).
const SARV_GEN_PR_EMP_CODE='1439';
let sarvPrNeedsRequester_=false;     // set by Item Master → New PR, cleared by clearPrForm
window.sarvGenerateNewPrFromItems=async function(){
  if(!sarvTabVisible('MD_ITEM_NEWPR'))return showToast('Your role cannot create a New PR from the Item Master','warn');
  const picked=sarvItemMasterRows.map(r=>r.it).filter(it=>sarvItemPrSel.has(String(it.id)));
  if(!picked.length)return showToast('Tick items in the NEW PR column first','warn');
  const noSoq=picked.filter(it=>itemStdOrderQty_(it)==null);
  if(!(await sarvFillPrFromItems_(picked.map(it=>({it,qty:itemStdOrderQty_(it)})))))return;
  sarvItemPrSel.clear();
  showToast('Filled '+picked.length+' item(s) into the New PR form: qty = Std Order Qty, Purchaser from Category. Choose <b>Requested By</b> (Employee Code) and <b>Required By</b> yourself; choose the Machine on the first row and it applies to all rows.');
  if(noSoq.length)showToast('These items had no Std Order Qty; enter the qty yourself: '+noSoq.map(it=>it.name).slice(0,5).join(', ')+(noSoq.length>5?' …':''),'warn');
};
/* Opens New Entry on a clean form and puts one row per Item Master item in it.
   list = [{it, qty, remark}]. Requested By is left blank and Submit insists on
   it (sarvPrNeedsRequester_). Shared by Item Master › Generate New PR and
   My Day › Below-MSV (store-mytasks.js), so both fill the form the same way.
   Returns false if the PR form could not be reached. */
async function sarvFillPrFromItems_(list){
  // Open New Entry the way the Home page does, on a clean form.
  sarvNavigateFromHome('PR');
  clearPrForm();
  const tb=byId('p_itemTableBody');if(!tb)return false;
  tb.innerHTML='';
  (list||[]).forEach(x=>{
    const it=x.it||{};
    const tr=addPurchaseMainRow();if(!tr)return;
    const set=(s,v)=>{const e=tr.querySelector(s);if(e)e.value=v??'';};
    // Pinned to this exact Item Master row, so a same-named duplicate can't be bound on save.
    tr.dataset.itemId=it.id;
    set('.col-name',it.name||'');set('.col-desc',it.description||'');set('.col-make',it.make||'');
    set('.col-cat',it.category||'');set('.col-uom',it.uom||'');
    set('.col-qty',x.qty!=null&&x.qty!==''?x.qty:'');
    if(x.remark)set('.col-rem',x.remark);
    const nameEl=tr.querySelector('.col-name');
    if(nameEl){nameEl.readOnly=true;nameEl.style.background='#f1f5f9';nameEl.style.cursor='not-allowed';nameEl.title='From the Item Master; to change it, remove the row and add a new one';}
    // Purchaser by Category — first row fills it, a disagreeing row warns (applyCategoryPurchaser).
    applyCategoryPurchaser(it.category);
  });
  refreshPurchaseTotals();
  await sarvPrFillRequester_({requester:false});
  sarvPrNeedsRequester_=true;
  if(typeof highlightRequiredField==='function')highlightRequiredField('p_reqEmpCode');
  sarvPrWireMachineCopy_();
  return true;
}
/* ── Two shared parts of a generated PR form ─────────────────────────
   A PR made from the Item Master and one made from the Trims Manager both go
   through these two functions, so both are filled in exactly the same way. */
async function sarvPrFillRequester_(opts){
  const fillRequester=!(opts&&opts.requester===false);
  /* Required By is left BLANK on a generated form too, exactly as on a
     hand-started one. It used to arrive pre-filled with today + 7 days, which
     is the one field on this form nobody else can answer — the date the
     material is actually needed by. A guessed default was going to the
     Purchaser unread, so the requester has to type it;
     saveRequirementWithPdf_ refuses a blank. */
  const rb=byId('p_requiredByDate');
  if(rb){rb.value='';rb.min=today();rb.dispatchEvent(new Event('change'));}
  // Requested By: the default Employee Code, filled through the same lookup as
  // typing it. Skipped for an Item Master PR, where the user picks the person.
  const ec=byId('p_reqEmpCode');
  if(ec&&fillRequester){
    if(!lookupEmployee(SARV_GEN_PR_EMP_CODE)&&SB_READY){try{await loadEmployeeMaster();}catch(e){}}
    ec.value=SARV_GEN_PR_EMP_CODE;
    onEmpCodeInput(SARV_GEN_PR_EMP_CODE);
    if(!lookupEmployee(SARV_GEN_PR_EMP_CODE))showToast('Employee Code '+SARV_GEN_PR_EMP_CODE+' was not found in the Employee Master; fill in Requested By yourself','warn');
  }
}
/* Machine: picking it on the FIRST row puts the same machine on every other
   row. A row whose machine was changed by hand (no longer blank / no longer
   the first row's previous pick) is left alone. */
function sarvPrWireMachineCopy_(){
  const tb=byId('p_itemTableBody');if(!tb)return;
  const genRows=[...tb.querySelectorAll('tr')];
  const firstMc=genRows[0]&&genRows[0].querySelector('.col-machine');
  if(!firstMc||genRows.length<2)return;
  let prev=firstMc.value||'';
  const copy=()=>{
    const v=String(firstMc.value||'').trim();
    // Only a real Machine Master value is copied — an invalid one is cleared on blur anyway.
    if(v&&sarvMachineCatalog.length&&!machineValidValues_().some(x=>x.toLowerCase()===v.toLowerCase()))return;
    genRows.slice(1).forEach(tr=>{
      const mc=tr.querySelector('.col-machine');if(!mc||!tr.isConnected)return;
      if(!mc.value||mc.value===prev)mc.value=v;
    });
    prev=v;
  };
  firstMc.addEventListener('change',copy);
  firstMc.title='Choosing a machine here applies the same machine to all the rows below';
}

/* ══ TRIMS SHEET → NEW PR ════════════════════════════════════════════
   Manufacturing › Trims Manager (iframe) has a NEW PR column after Lot Req
   Qty; ticking items there and pressing "Generate New PR" makes that page
   call THIS function. Reason: the PR form is on this page and the trims sheet
   is in the iframe, so the PR-creation code isn't written twice, and a PR made
   from the Item Master and one made from trims are identical
   (sarvPrFillRequester_ / sarvPrWireMachineCopy_ serve both).

   The qty comes from the trims sheet (FINAL PO QTY = Lot Req × (1 + Wastage%));
   the Item Master's Std Order Qty is not the answer here: the lot says how
   much is needed, not the item master.

   Access: HOME_PR. Deliberately not the Item Master's MD_ITEM_NEWPR, which is
   Admin-only, because the merchandiser who fills the trims sheet is the one
   who raises the PR. The rule is simple: whoever can open the PR form can
   raise a PR from here. */
let sarvTrimsPrPending=null;   // {uids:[], orderNo, at}; used to send the number back once the PR is saved
window.sarvGenerateNewPrFromTrims=async function(req){
  try{
    if(!sarvTabVisible('HOME_PR')){
      showToast('Your role cannot create a Purchase Requirement','warn');
      return { ok:false, error:'Your role cannot create a PR' };
    }
    const items=(req&&Array.isArray(req.items))?req.items.filter(x=>x&&x.itemId&&pNum(x.qty)>0):[];
    if(!items.length) return { ok:false, error:'No items received (itemId or qty empty)' };

    // The full item from the Item Master: Description / Make / Category / UOM
    // come from there, not from the trims sheet, so the PR says what the master
    // says. The same resolver used for PO lines.
    const resolve=await poLineItemResolver_(items.map(x=>({ item_id:x.itemId, item_name:x.name })));

    sarvNavigateFromHome('PR');
    clearPrForm();                 // this also clears sarvTrimsPrPending, which is why pending is set BELOW
    const tb=byId('p_itemTableBody');
    if(!tb) return { ok:false, error:'PR form not found' };
    tb.innerHTML='';
    const unresolved=[], used=[];
    items.forEach(x=>{
      const it=resolve({ item_id:x.itemId, item_name:x.name })||{};
      const tr=addPurchaseMainRow();if(!tr)return;
      const set=(s,v)=>{const e=tr.querySelector(s);if(e)e.value=v??'';};
      // Pinned to this exact Item Master row, so a same-named duplicate can't be bound on save.
      tr.dataset.itemId=it.id||x.itemId;
      if(!it.id)unresolved.push(x.name||'(no name)');
      set('.col-name',it.name||x.name||'');
      set('.col-desc',it.description||'');
      set('.col-make',it.make||'');
      set('.col-cat',it.category||'');
      set('.col-uom',it.uom||'');
      set('.col-qty',pNum(x.qty));
      set('.col-rem',x.remark||'');
      const nameEl=tr.querySelector('.col-name');
      if(nameEl){nameEl.readOnly=true;nameEl.style.background='#f1f5f9';nameEl.style.cursor='not-allowed';nameEl.title='From the Trims sheet; to change it, remove the row and add a new one';}
      // Purchaser by Category — first row fills it, a disagreeing row warns.
      applyCategoryPurchaser(it.category);
      used.push(x.uid);
    });
    refreshPurchaseTotals();
    await sarvPrFillRequester_();
    sarvPrWireMachineCopy_();

    /* Now we remember which trims rows this PR came from. On Submit the PR No
       goes straight back to those rows: sarvTrimsPrNotify_. */
    sarvTrimsPrPending={ uids:used, orderNo:(req&&req.orderNo)||'', at:Date.now() };

    const lots=(req&&Array.isArray(req.lots))?req.lots.join(', '):'';
    showToast('Filled '+used.length+' item(s) from the Trims sheet into the New PR form'
      +(req&&req.orderNo?' — Order '+escText(req.orderNo):'')+(lots?' · Lot '+escText(lots):'')
      +'. Qty = Final PO Qty (Lot Req + Wastage). Fill in <b>Required By</b> and the <b>Machine</b> on the first row, then Submit; the PR No will be set in the Trims sheet automatically.');
    if(unresolved.length)showToast(''+unresolved.length+' item(s) not found in the Item Master; Description / Category are empty: '+unresolved.slice(0,3).map(escText).join(', ')+(unresolved.length>3?' …':''),'warn');
    return { ok:true, filled:used.length };
  }catch(e){
    console.error('[SARV] Trims → PR failed:',e);
    return { ok:false, error:(e&&e.message)||String(e) };
  }
};
// The Trims Manager iframe; there is only one in the ERP.
function sarvTrimsFrameWin_(){
  try{ return byId('trimsFrame')?.contentWindow||null; }catch(e){ return null; }
}
/* As soon as the PR is saved, its number is sent to the trims rows it came
   from. A one-time job: pending ends here, so that the next PR (one without
   trims) doesn't land on that sheet by mistake.

   If the Trims page is closed / changed, nothing breaks: its trimsPrSaved
   reports that itself, and the fallback toast here tells the user to select
   it in the PR NO. column themselves. */
function sarvTrimsPrNotify_(reqNo){
  const p=sarvTrimsPrPending;
  if(!p||!reqNo)return;
  sarvTrimsPrPending=null;
  const w=sarvTrimsFrameWin_();
  try{
    if(w&&typeof w.trimsPrSaved==='function'){
      /* The result is shown HERE, not in the iframe: while submitting the PR
         the user is on this panel and the trims page is hidden, so a toast
         there would be seen by nobody. The Trims sheet also leaves a banner
         on its side until Save. */
      Promise.resolve(w.trimsPrSaved(reqNo,p.uids,p.orderNo))
        .then(res=>{ if(res&&res.msg)showToast((res.ok?'':'')+res.msg, res.ok?'success':'warn'); })
        .catch(e=>console.warn('[SARV] trims PR write-back failed:',e&&e.message||e));
      return;
    }
  }catch(e){ console.warn('[SARV] trims PR write-back skipped:',e.message||e); }
  showToast('PR '+escText(reqNo)+' has been created. Trims Manager was not open, so select it yourself in its PR NO. column (Manufacturing › Trims Manager → ⟳ Store Data).','warn');
}
document.addEventListener('DOMContentLoaded',()=>{
  byId('itemMasterBody')?.addEventListener('change',e=>{
    const cb=e.target.closest('.im-pr-sel');if(!cb)return;
    if(!sarvTabVisible('MD_ITEM_NEWPR')){cb.checked=false;return showToast('Your role does not have access to New PR Generation','warn');}
    if(cb.checked)sarvItemPrSel.add(String(cb.dataset.id));else sarvItemPrSel.delete(String(cb.dataset.id));
    // Subtotal cell + button count, without re-rendering (keeps scroll position).
    const sub=byId('itemMasterBody').querySelector('tr td[title="Ticked for New PR"]');if(sub)sub.textContent=sarvItemPrSel.size||'—';
    sarvSyncItemPrSelUi_();
  });
  byId('imPrSelAll')?.addEventListener('click',e=>e.stopPropagation());
  byId('imPrSelAll')?.addEventListener('change',e=>{
    if(!sarvTabVisible('MD_ITEM_NEWPR')){e.target.checked=false;return;}
    // Every item the current search / filters are showing.
    document.querySelectorAll('#itemMasterBody .im-pr-sel').forEach(cb=>{
      cb.checked=e.target.checked;
      if(cb.checked)sarvItemPrSel.add(String(cb.dataset.id));else sarvItemPrSel.delete(String(cb.dataset.id));
    });
    const sub=byId('itemMasterBody').querySelector('tr td[title="Ticked for New PR"]');if(sub)sub.textContent=sarvItemPrSel.size||'—';
    sarvSyncItemPrSelUi_();
  });
});
/* Item Master column resize — Code / Item Name / Description. Drag a header's
   right edge; double-click the edge to go back to the default width. Widths
   are remembered per browser. The table is table-layout:fixed, so a width set
   on the <th> is exactly what the column gets. A drag must not also count as
   a click on the header, or Code / Item Name would re-sort on every resize. */
(function initItemMasterColResize(){
  const KEY='sarv_im_colw', MIN=40;
  let saved={};
  try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch(e){}
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(saved));}catch(e){}};
  function init(){
    const table=byId('itemMasterTable');
    if(!table)return;
    table.querySelectorAll('th.im-resizable').forEach(th=>{
      const col=th.dataset.col, grip=th.querySelector('.im-col-resizer');
      const defaultW=th.style.width;
      if(saved[col])th.style.width=saved[col]+'px';
      if(!grip||grip.dataset.imGripBound)return;
      grip.dataset.imGripBound='1';
      grip.addEventListener('pointerdown',e=>{
        e.preventDefault(); e.stopPropagation();
        const startX=e.clientX, startW=th.getBoundingClientRect().width;
        let moved=false;
        grip.classList.add('active');
        /* Listeners on WINDOW, not on the grip, and attached BEFORE
           setPointerCapture — which can throw (InvalidPointerId) and used to
           leave the drag with no way to end: `justResized` stayed true and the
           capture-phase swallower that read it then ate EVERY click in the
           table — sort, the filter funnels, Edit, Delete, the New PR ticks —
           until the page was reloaded. That swallower is gone too; the only
           thing that now consults this drag is the header click handler
           (imHeaderClick_), so even a stuck drag cannot reach the rows. */
        const move=ev=>{
          if(Math.abs(ev.clientX-startX)>2)moved=true;
          th.style.width=Math.max(MIN,Math.round(startW+ev.clientX-startX))+'px';
        };
        const up=()=>{
          window.removeEventListener('pointermove',move);
          window.removeEventListener('pointerup',up);
          window.removeEventListener('pointercancel',up);
          window.removeEventListener('blur',up);
          grip.classList.remove('active');
          if(moved){saved[col]=parseInt(th.style.width,10);save();}
          /* Only a real DRAG suppresses the header click that follows it. A
             plain click on the grip moves nothing, so it must not cost the
             user a sort or a filter — which it did before. */
          sarvImHdrSuppress=moved;
          setTimeout(()=>{sarvImHdrSuppress=false;},0);
          try{grip.releasePointerCapture(e.pointerId);}catch(err){}
        };
        window.addEventListener('pointermove',move);
        window.addEventListener('pointerup',up);
        window.addEventListener('pointercancel',up);
        window.addEventListener('blur',up);     // alt-tab mid-drag
        try{grip.setPointerCapture(e.pointerId);}catch(err){}
      });
      grip.addEventListener('dblclick',e=>{
        e.stopPropagation();
        th.style.width=defaultW; delete saved[col]; save();
      });
    });
  }
  // Exposed so the header wiring can re-run it when the panel is shown — the
  // resizer and the click delegation are two halves of the same header.
  window.initItemMasterColResize_=init;
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
/* ══ ITEM MASTER HEADER — SORT + FILTER WIRING ══════════════════════
   ONE delegated click listener on the <thead>, instead of an onclick= on
   every <th> and another on every ▾ button.

   Why it was rewired. The old arrangement needed three things to line up on
   every header cell: the <th>'s own onclick for the sort, the funnel's own
   onclick for the filter, and an ev.stopPropagation() inside imOpenFilter to
   stop the funnel's click ALSO re-sorting the column underneath the panel it
   had just opened. On top of that sat a capture-phase click swallower on the
   whole <table>, which the column resizer switched on and — if its pointerup
   was ever missed — never switched off again, leaving every click in the
   table dead. Any one of those three going wrong looked identical from the
   outside: "filter does nothing".

   Now the header carries DATA, not behaviour — data-fcol="cat" on the funnel,
   data-sort="cat" on the cell — and this one handler reads it. There is no
   ordering to get right, nothing to stopPropagation past, and a header cell
   added later works with no JavaScript change at all.

   Bound idempotently (dataset.imHdrBound) from DOMContentLoaded AND from
   every path that shows the panel, so it is wired whether this script ran
   before or after the markup was parsed. */
let sarvImHdrSuppress=false;      // a column drag just happened — not a click
function imHeaderClick_(e){
  // A finished resize drag is not a header click. Scoped to the header alone,
  // so even if this ever latched it could not touch the rows.
  if(sarvImHdrSuppress){e.preventDefault();return;}
  if(e.target.closest('.im-col-resizer'))return;       // the grip, mid-drag
  const fb=e.target.closest('.im-fbtn');
  if(fb){
    /* The funnel. preventDefault + stopPropagation here are what keep the
       document-level "click outside closes the panel" listener from closing
       the panel in the same gesture that opened it. */
    e.preventDefault();e.stopPropagation();
    imOpenFilter(e,fb.dataset.fcol);
    return;
  }
  // Anything else in a sortable cell sorts it.
  const th=e.target.closest('th[data-sort]');
  if(th&&th.dataset.sort)sortItemMaster(th.dataset.sort);
}
function initItemMasterHeader_(){
  const head=document.querySelector('#itemMasterTable thead');
  if(!head)return;
  if(!head.dataset.imHdrBound){
    head.addEventListener('click',imHeaderClick_);
    head.dataset.imHdrBound='1';
  }
  // The width grips live in the same header and are bound the same way (the
  // guard inside makes a second call free).
  if(typeof window.initItemMasterColResize_==='function')window.initItemMasterColResize_();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initItemMasterHeader_);
else initItemMasterHeader_();
/* Several Item Master rows are allowed to carry the SAME name (same part,
   different spec / make / description). A native <datalist> reports which
   option the user picked ONLY through that option's value, so same-named
   options must not share one value — otherwise every pick resolved to
   whichever row happened to come first and filled that row's Description /
   Spec / Category / UOM, no matter which line was chosen in the popup.

   Duplicated names therefore carry their item_code — "BEARING 6204 [BRG-6204-1]"
   — which is the unique handle for an Item Master row. A name that appears
   once stays exactly as it was, so nothing changes for the common case.
   lookupItem() understands both forms, and applyItemAutofill() puts the clean
   name back in the field once the pick has been resolved. */
function itemDropdownValue(it,dupNames){
  const name=String(it&&it.name||'').trim();
  const code=String(it&&it.item_code||'').trim();
  if(!code||!dupNames||!dupNames.has(name.toLowerCase()))return name;
  return name+' ['+code+']';
}
/* Everything an Item Name box is allowed to hold: every master name, plus the
   "NAME [ITEM_CODE]" form the dropdown uses for duplicated names. Without the
   tagged forms the Master Data check on blur would wipe a freshly picked
   duplicate before applyItemAutofill had put the plain name back. */
function itemNameMasterValues(){
  const dup=itemDuplicateNames(sarvItemCatalog),out=[];
  (sarvItemCatalog||[]).forEach(it=>{
    const name=String(it&&it.name||'').trim();
    if(name)out.push(name);
    const tagged=itemDropdownValue(it,dup);
    if(tagged&&tagged!==name)out.push(tagged);
  });
  return out;
}
// Lowercased names that occur more than once in the given item list.
function itemDuplicateNames(items){
  const seen=new Map();
  (items||[]).forEach(it=>{
    const k=String(it&&it.name||'').trim().toLowerCase();
    if(k)seen.set(k,(seen.get(k)||0)+1);
  });
  return new Set([...seen.entries()].filter(([,n])=>n>1).map(([k])=>k));
}
function refreshItemDatalist(items){
  sarvItemCatalog=items; // Keep global cache in sync
  // Inward + Outward + PR item name datalists
  const dupNames=itemDuplicateNames(items);
  ['dl-item-name','dl-out-item-name','p_dl-item-names'].forEach(dlId=>{
    const dl=byId(dlId);if(!dl)return;
    dl.innerHTML=items.map(it=>`<option value="${escText(itemDropdownValue(it,dupNames))}">${escText(it.category||'')} — ${escText(it.description||'')}</option>`).join('');
  });
  /* Make / Brand suggestions, everywhere the field appears. p_dl-item-makes
     is the PR form's list — the datalist has been in the markup all along but
     nothing ever filled it, so the PR's MAKE column was the one place a brand
     had to be typed from memory. */
  const makeSet=[...new Set(items.map(x=>x.make).filter(Boolean))]
    .sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true,sensitivity:'base'}));
  ['dl-item-make','dl-out-item-make','p_dl-item-makes'].forEach(dlId=>{const dl=byId(dlId);if(!dl)return;dl.innerHTML=makeSet.map(m=>`<option value="${escText(m)}">`).join('');});
  /* The Item Master form's OWN five boxes (dl-mi-*: Item Name, Description,
     Make, Size, Material Type). That panel fills them itself when it loads,
     but this runs on every item-catalogue refresh — so the suggestions are
     already there the first time the Add New Item form is opened, which is
     what the single dl-mi-make line used to do here on its own. One call, so
     the two paths cannot fill the lists differently. */
  refreshItemAttributeDatalists_(items);
}

function refreshSupplierDatalist(suppliers){
  sarvSupplierCatalog=suppliers; // Keep global cache in sync
  // Material Inward "Supplier Name", Material Outward "Party Name", and
  // Build PO "Vendor (M/s)" all draw from the same Supplier Master list.
  ['dl-supplierName','dl-outPartyName','p_vendorDatalist'].forEach(dlId=>{
    const dl=byId(dlId);if(!dl)return;
    dl.innerHTML=suppliers.map(s=>`<option value="${escText(s.supplier_name)}">`).join('');
  });
}

window.loadItemMaster=async function(){
  const tb=byId('itemMasterBody');
  if(!tb)return;
  if(!SB_READY){tb.innerHTML='<tr><td colspan="20" style="text-align:center;padding:20px;color:#f59e0b;">Supabase not configured</td></tr>';return;}
  tb.innerHTML='<tr><td colspan="20" style="text-align:center;padding:20px;color:#94a3b8;">Loading...</td></tr>';
  try{
    const [items,inLines,outLines]=await Promise.all([
      fetchAllRows('items','*','name'),
      fetchAllRows('inward_lines','item_id,qty'),
      fetchAllRows('outward_lines','item_id,qty')
    ]);
    const inMap={},outMap={};
    inLines.forEach(r=>{inMap[r.item_id]=(inMap[r.item_id]||0)+Number(r.qty||0);});
    outLines.forEach(r=>{outMap[r.item_id]=(outMap[r.item_id]||0)+Number(r.qty||0);});
    sarvItemMasterRows=items.map(it=>{
      const inQty=inMap[it.id]||0,outQty=outMap[it.id]||0;
      return {it,inQty,outQty,bal:inQty-outQty,catKey:(it.category&&it.category.trim())?it.category.trim():'(No Category)'};
    });
    /* Column filters deliberately SURVIVE a Refresh. Someone narrowing down to
       one vendor's electricals and then hitting Refresh wants the same view
       back with fresh numbers, not a reset. The chip bar above the table keeps
       saying what is applied, so a filter can never go on quietly hiding rows
       after a reload. A value that no longer exists simply matches nothing —
       the chip is still there to clear. */
    renderItemMasterTable();
    refreshItemDatalist(items);
    refreshItemAttributeDatalists_(items);
    // Not awaited: the table is usable straight away and the column fills in
    // when the PR / PO lookup lands. The promise is kept for anything that
    // needs the figures (My Day › Below-MSV).
    sarvImPipePromise=imLoadPipeline_(items);
  }catch(e){dbError(e);tb.innerHTML='<tr><td colspan="20" style="text-align:center;padding:16px;color:#ef4444;">Error loading items</td></tr>';}
};

/* ══ ITEM MASTER › PENDING PR / PO QTY ════════════════════════════════
   For every item: how much is still to come into the store, from two places.
     • PO  — open POs (not Received / Closed (Short) / Cancelled / Rejected):
             ordered_qty − received_qty on each line.
     • PR  — open PRs (not Completed / Cancelled / Rejected / Closed): the part
             of each line that is not on a live PO yet and has not come in
             "without PO" either.
   The two never overlap. A PR line's qty that is already on a PO is counted
   once, on the PO side, using the same req_no|item-name key the Pending
   Items table uses (refreshPendingRequirements), so the two screens agree.

   Loaded after the table is drawn (four queries, paged), so Item Master opens
   as fast as it did before. Until it lands the cells show "…" and row.pipe
   stays null, which the sort and the column filter treat as "not set". */
let sarvImPipe=null;            // Map item id -> {po,pr,total,docs:[]}; null = not loaded
let sarvImPipeErr='';
let sarvImPipeSeq=0;            // a newer load wins over a slower older one
let sarvImPipePromise=null;     // the latest imLoadPipeline_ run, for code that has to wait on it
const IM_PIPE_PO_DONE=['Received','Closed (Short)','Cancelled','Rejected'];
const IM_PIPE_PO_DEAD=['Cancelled','Rejected'];
const imPipePrClosed_=s=>/^(completed|cancelled|rejected|closed)/i.test(String(s||'').trim());
const imPipeNorm_=v=>String(v==null?'':v).toLowerCase().trim();

// A select that names columns, with '*' as the fallback for a database that
// doesn't have one of them (PostgREST rejects the whole query otherwise).
async function imPipeFetch_(table,cols,order){
  try{return await fetchAllRows(table,cols,order);}
  catch(e){
    if(/column|does not exist|schema cache/i.test(e.message||''))return await fetchAllRows(table,'*',order);
    throw e;
  }
}
async function imPipePdfMap_(nos){
  const map={},list=[...new Set((nos||[]).filter(Boolean).map(String))];
  for(let i=0;i<list.length;i+=200){
    try{
      const q=await SB.from('pdf_documents').select('document_no,variant,public_url').in('document_no',list.slice(i,i+200));
      if(q.error)throw q.error;
      (q.data||[]).forEach(p=>{
        if(!p.public_url)return;
        const m=map[p.document_no]=map[p.document_no]||{};
        m[p.variant||'SINGLE']=p.public_url;
      });
    }catch(e){console.warn('[SARV] Pending PR/PO PDF lookup skipped:',e.message||e);}
  }
  return map;
}
function imPipePdfPick_(map,no,prefer){
  const m=map[String(no||'')];if(!m)return '';
  for(const v of prefer)if(m[v])return m[v];
  const k=Object.keys(m);return k.length?m[k[0]]:'';
}
async function imLoadPipeline_(items){
  if(!SB_READY)return;
  const seq=++sarvImPipeSeq;
  try{
    const [prs,prLines,pos,poLines]=await Promise.all([
      imPipeFetch_('purchase_requirements','id,req_no,request_date,required_by,requested_by,purchaser_name,department,priority,status','id'),
      imPipeFetch_('purchase_requirement_lines','id,requirement_id,item_id,requested_qty,uom','id'),
      imPipeFetch_('purchase_orders','id,po_no,po_date,delivery_date,vendor_name,status,pdf_url','id'),
      imPipeFetch_('purchase_order_lines','id,purchase_order_id,req_no,item_id,item_name,ordered_qty,received_qty','id')
    ]);
    if(seq!==sarvImPipeSeq)return;
    const list=items||sarvItemMasterRows.map(r=>r.it);
    const itemById=new Map(list.map(it=>[String(it.id),it]));
    // Name → id, for PO lines saved before item_id was written. A name that two
    // items share resolves to nothing rather than to the wrong one.
    const byName=new Map();
    list.forEach(it=>{const k=imPipeNorm_(it.name);if(!k)return;byName.set(k,byName.has(k)?null:String(it.id));});
    const resolve=(id,name)=>(id!=null&&itemById.has(String(id)))?String(id):(byName.get(imPipeNorm_(name))||null);

    const out=new Map();
    const bucket=id=>{let b=out.get(id);if(!b){b={po:0,pr:0,total:0,docs:[]};out.set(id,b);}return b;};

    // ── PO side ──
    const poById=new Map(pos.map(p=>[p.id,p]));
    const poOrderedByKey={};          // req_no|item name, live POs only
    poLines.forEach(l=>{
      const po=poById.get(l.purchase_order_id);
      const st=String((po&&po.status)||'Generated');
      if(IM_PIPE_PO_DEAD.includes(st))return;
      if(l.req_no){
        String(l.req_no).split(',').map(s=>s.trim()).filter(Boolean).forEach(no=>{
          const k=no+'|'+imPipeNorm_(l.item_name);
          poOrderedByKey[k]=(poOrderedByKey[k]||0)+pNum(l.ordered_qty);
        });
      }
      if(!po||IM_PIPE_PO_DONE.includes(st))return;
      const pending=pNum(l.ordered_qty)-pNum(l.received_qty);
      if(pending<=0.0001)return;
      const id=resolve(l.item_id,l.item_name);if(!id)return;
      const b=bucket(id);b.po+=pending;
      b.docs.push({type:'PO',no:po.po_no||'',date:po.po_date||'',status:st,party:po.vendor_name||'',
        ref:l.req_no||'',qty:pNum(l.ordered_qty),done:pNum(l.received_qty),pending,due:po.delivery_date||'',
        url:po.pdf_url||''});
    });

    // ── PR side ──
    const openPrs=prs.filter(p=>!imPipePrClosed_(p.status));
    const prById=new Map(openPrs.map(p=>[p.id,p]));
    let direct={};
    try{direct=await prReceivedQtys_(openPrs.map(p=>p.req_no));}
    catch(e){console.warn('[SARV] Pending PR/PO direct receipts skipped:',e.message||e);}
    if(seq!==sarvImPipeSeq)return;
    // One requirement can carry the same item on two lines, so the PO qty and
    // the "without PO" receipts are pooled per key and handed out in line order.
    const poPool={},directPool={};
    prLines.forEach(l=>{
      const pr=prById.get(l.requirement_id);if(!pr)return;
      const id=resolve(l.item_id,null);if(!id)return;
      const it=itemById.get(id)||{};
      const requested=pNum(l.requested_qty);if(requested<=0)return;
      const pk=String(pr.req_no||'')+'|'+imPipeNorm_(it.name);
      if(!(pk in poPool))poPool[pk]=poOrderedByKey[pk]||0;
      const onPo=Math.min(poPool[pk],requested);poPool[pk]-=onPo;
      const dk=String(pr.req_no||'').trim().toUpperCase()+'|'+String(l.item_id||'');
      if(!(dk in directPool))directPool[dk]=pNum((direct[dk]||{}).qty);
      const recv=Math.min(directPool[dk],requested-onPo);directPool[dk]-=recv;
      const pending=requested-onPo-recv;
      if(pending<=0.0001)return;
      const b=bucket(id);b.pr+=pending;
      b.docs.push({type:'PR',no:pr.req_no||'',date:pr.request_date||'',status:pr.status||'Pending',
        party:[pr.requested_by,pr.department].filter(Boolean).join(' · '),ref:pr.purchaser_name||'',
        qty:requested,done:onPo+recv,pending,due:pr.required_by||'',url:''});
    });

    // ── PDF links: the index first, then the PO's own pdf_url ──
    const allDocs=[];out.forEach(b=>b.docs.forEach(d=>allDocs.push(d)));
    const pdfMap=await imPipePdfMap_(allDocs.map(d=>d.no));
    if(seq!==sarvImPipeSeq)return;
    allDocs.forEach(d=>{
      const u=d.type==='PO'?imPipePdfPick_(pdfMap,d.no,['PO','SINGLE','TWO_PAGE'])
                          :imPipePdfPick_(pdfMap,d.no,['REQUIREMENT','SINGLE','TWO_PAGE']);
      d.url=u||d.url||'';
    });
    out.forEach(b=>{
      b.total=b.po+b.pr;
      // POs first, then PRs; oldest document first inside each.
      b.docs.sort((x,y)=>(x.type===y.type?0:x.type==='PO'?-1:1)
        ||String(x.date||'').localeCompare(String(y.date||''))
        ||String(x.no).localeCompare(String(y.no),undefined,{numeric:true}));
    });
    sarvImPipe=out;sarvImPipeErr='';
  }catch(e){
    if(seq!==sarvImPipeSeq)return;
    console.warn('[SARV] Pending PR/PO qty unavailable:',e.message||e);
    sarvImPipe=new Map();sarvImPipeErr=e.message||String(e);
  }
  sarvItemMasterRows.forEach(r=>{
    const b=sarvImPipe.get(String(r.it.id));
    r.pipe=sarvImPipeErr?null:(b?Number(b.total.toFixed(3)):0);
  });
  if(byId('itemMasterBody'))renderItemMasterTable();
  if(byId('imPipeOverlay')?.style.display==='flex'&&sarvImPipeOpenId!=null)imPipeFill_(sarvImPipeOpenId);
}
// The table cell. A button when there is something pending, a dash when not.
function imPipeCell_(it,q2){
  if(!sarvImPipe)return '<span style="color:#cbd5e1;" title="Loading pending PR / PO qty">…</span>';
  if(sarvImPipeErr)return '<span style="color:#cbd5e1;" title="'+escText('Could not load: '+sarvImPipeErr)+'">—</span>';
  const b=sarvImPipe.get(String(it.id));
  if(!b||b.total<=0)return '<span style="color:#cbd5e1;">—</span>';
  // Colour says where the qty sits: green = PO only, orange = PR only,
  // purple = both. The exact split is in the tooltip and the popup.
  const onPo=b.po>0,onPr=b.pr>0;
  const color=onPo&&onPr?'#7e22ce':onPo?'#15803d':'#c2410c';
  const split=[onPo?'PO '+q2(Number(b.po.toFixed(3))):'',onPr?'PR '+q2(Number(b.pr.toFixed(3))):''].filter(Boolean).join(' + ');
  return '<button type="button" class="im-pipe-btn" onclick="imOpenPipe(\''+escText(String(it.id))+'\')"'
    +' title="'+escText(split+'. Click for PR / PO details and PDFs')+'"'
    +' style="background:transparent;border:0;color:'+color+';padding:2px 6px;'
    +'font-size:11.5px;font-weight:700;cursor:pointer;text-decoration:underline;text-underline-offset:2px;">'
    +q2(Number(b.total.toFixed(3)))
    +'</button>';
}
let sarvImPipeOpenId=null;
function imClosePipe(){
  const ov=byId('imPipeOverlay');if(ov)ov.style.display='none';
  sarvImPipeOpenId=null;
}
window.imClosePipe=imClosePipe;
window.imOpenPipe=function(itemId){
  let ov=byId('imPipeOverlay');
  if(!ov){
    ov=document.createElement('div');
    ov.id='imPipeOverlay';
    ov.className='secure-modal-overlay';
    ov.style.cssText='display:none;align-items:center;justify-content:center;z-index:29500;padding:14px;';
    ov.innerHTML='<div style="background:#fff;width:min(1060px,97vw);max-height:92vh;border-radius:12px;'
      +'box-shadow:0 20px 50px rgba(15,23,42,.30);display:flex;flex-direction:column;overflow:hidden;">'
      +'<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:#0f172a;color:#fff;">'
        +'<div style="min-width:0;"><strong style="font-size:13px;">Pending PR / PO</strong>'
        +'<div id="impItem" style="font-size:11px;color:#cbd5e1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"></div></div>'
        +'<span style="flex:1;"></span>'
        +'<button type="button" id="impRefresh" style="border:1px solid #64748b;background:transparent;color:#fff;'
        +'border-radius:6px;padding:4px 10px;font-size:11px;font-weight:700;cursor:pointer;">Refresh</button>'
        +'<button type="button" id="impClose" style="border:1px solid #64748b;background:transparent;color:#fff;'
        +'border-radius:6px;padding:4px 9px;font-size:15px;cursor:pointer;">&#10005;</button></div>'
      +'<div id="impSummary" style="display:flex;flex-wrap:wrap;gap:8px;padding:10px 14px;background:#f8fafc;border-bottom:1px solid #e2e8f0;"></div>'
      +'<div id="impBody" style="flex:1;overflow:auto;padding:0 14px 12px;"></div>'
      +'<div style="padding:8px 14px;border-top:1px solid #e2e8f0;background:#f8fafc;font-size:10.5px;color:#64748b;line-height:1.5;">'
        +'<b>PO</b>: ordered minus received, on POs that are not yet Received / Closed / Cancelled / Rejected. '
        +'<b>PR</b>: requested qty not yet on a PO and not received without a PO. A qty is counted once, never on both.</div>'
      +'</div>';
    (byId('storeInterface')||document.body).appendChild(ov);
    byId('impClose').addEventListener('click',imClosePipe);
    byId('impRefresh').addEventListener('click',()=>{
      sarvImPipe=null;
      if(sarvImPipeOpenId!=null)imPipeFill_(sarvImPipeOpenId);
      renderItemMasterTable();
      imLoadPipeline_(null);
    });
    ov.addEventListener('click',e=>{if(e.target===ov)imClosePipe();});
    document.addEventListener('keydown',e=>{
      if(e.key==='Escape'&&byId('imPipeOverlay')?.style.display==='flex')imClosePipe();
    });
  }
  sarvImPipeOpenId=String(itemId);
  imPipeFill_(sarvImPipeOpenId);
  ov.style.display='flex';
};
function imPipeFill_(itemId){
  const row=sarvItemMasterRows.find(r=>String(r.it.id)===String(itemId));
  const it=row?row.it:{};
  const uom=it.uom||'PCS';
  const q=v=>{const n=Number(v);return !isFinite(n)?'—':(Number.isInteger(n)?String(n):n.toFixed(2));};
  const dt=v=>{
    if(!v)return '—';
    const s=String(v).slice(0,10),m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
    return m?m[3]+'/'+m[2]+'/'+m[1]:escText(String(v));
  };
  byId('impItem').textContent=[it.item_code,it.name].filter(Boolean).join(' · ')+(row?'  |  Balance in store: '+q(row.bal)+' '+uom:'');
  const sum=byId('impSummary'),body=byId('impBody');
  if(!sarvImPipe){
    sum.innerHTML='';
    body.innerHTML='<div style="padding:26px;text-align:center;color:#64748b;font-size:12px;">Loading pending PRs and POs...</div>';
    return;
  }
  if(sarvImPipeErr){
    sum.innerHTML='';
    body.innerHTML='<div style="padding:26px;text-align:center;color:#b91c1c;font-size:12px;">Could not load PR / PO data: '+escText(sarvImPipeErr)+'</div>';
    return;
  }
  const b=sarvImPipe.get(String(itemId))||{po:0,pr:0,total:0,docs:[]};
  const chip=(label,val,c,bg)=>'<span style="background:'+bg+';color:'+c+';border:1px solid '+c+'33;border-radius:8px;padding:5px 11px;font-size:11px;font-weight:600;">'
    +label+': <b style="font-size:13px;">'+q(val)+'</b> '+escText(uom)+'</span>';
  sum.innerHTML=chip('On PO, to be received',b.po,'#1d4ed8','#eff6ff')
    +chip('On PR, PO not yet made',b.pr,'#b45309','#fffbeb')
    +chip('Total pending',b.total,'#0f172a','#fff');
  if(!b.docs.length){
    body.innerHTML='<div style="padding:26px;text-align:center;color:#64748b;font-size:12px;">No open PR or PO for this item. Nothing is waiting to be received.</div>';
    return;
  }
  const th='padding:7px 8px;text-align:left;font-size:10px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.3px;border-bottom:1px solid #e2e8f0;background:#fff;position:sticky;top:0;white-space:nowrap;';
  const td='padding:7px 8px;font-size:11.5px;color:#0f172a;border-bottom:1px solid #f1f5f9;vertical-align:top;';
  const num=td+'text-align:right;white-space:nowrap;';
  const head='<tr><th style="'+th+'">Type</th><th style="'+th+'">Document No</th><th style="'+th+'">Date</th>'
    +'<th style="'+th+'">Status</th><th style="'+th+'">Vendor / Requested by</th><th style="'+th+'">Linked</th>'
    +'<th style="'+th+'text-align:right;">Qty</th><th style="'+th+'text-align:right;">Done</th>'
    +'<th style="'+th+'text-align:right;">Pending</th><th style="'+th+'">Due / Req. by</th><th style="'+th+'">PDF</th></tr>';
  const rows=b.docs.map(d=>{
    const isPo=d.type==='PO';
    const badge='<span style="display:inline-block;min-width:26px;text-align:center;border-radius:4px;padding:1px 6px;font-size:10px;font-weight:700;'
      +(isPo?'background:#dbeafe;color:#1d4ed8;':'background:#fef3c7;color:#92400e;')+'">'+d.type+'</span>';
    const pdf=d.url
      ?'<a href="'+escText(d.url)+'" target="_blank" rel="noopener" style="display:inline-block;background:#fff;border:1px solid #cbd5e1;color:#0f172a;border-radius:5px;padding:2px 9px;font-size:11px;font-weight:600;text-decoration:none;white-space:nowrap;">Open PDF</a>'
      :'<span style="color:#94a3b8;font-size:11px;">Not generated</span>';
    const done=isPo?'Received':'On PO / received';
    const overdue=isPo&&d.due&&String(d.due).slice(0,10)<today();
    return '<tr>'
      +'<td style="'+td+'">'+badge+'</td>'
      +'<td style="'+td+'font-weight:700;white-space:nowrap;">'+escText(d.no||'—')+'</td>'
      +'<td style="'+td+'white-space:nowrap;">'+dt(d.date)+'</td>'
      +'<td style="'+td+'">'+escText(d.status||'—')+'</td>'
      +'<td style="'+td+'">'+escText(d.party||'—')+'</td>'
      +'<td style="'+td+'color:#475569;">'+(d.ref?(isPo?'PR ':'Purchaser: ')+escText(d.ref):'—')+'</td>'
      +'<td style="'+num+'">'+q(d.qty)+'</td>'
      +'<td style="'+num+'color:#475569;" title="'+done+'">'+q(d.done)+'</td>'
      +'<td style="'+num+'font-weight:700;color:'+(isPo?'#1d4ed8':'#b45309')+';">'+q(d.pending)+'</td>'
      +'<td style="'+td+'white-space:nowrap;'+(overdue?'color:#b91c1c;font-weight:700;':'')+'"'+(overdue?' title="Delivery date has passed"':'')+'>'+dt(d.due)+'</td>'
      +'<td style="'+td+'">'+pdf+'</td>'
      +'</tr>';
  }).join('');
  body.innerHTML='<table style="width:100%;border-collapse:collapse;margin-top:2px;"><thead>'+head+'</thead><tbody>'+rows+'</tbody>'
    +'<tfoot><tr><td colspan="8" style="'+td+'text-align:right;font-weight:700;border-bottom:0;">Total pending</td>'
    +'<td style="'+num+'font-weight:800;border-bottom:0;">'+q(b.total)+'</td><td colspan="2" style="'+td+'border-bottom:0;color:#64748b;">'+escText(uom)+'</td></tr></tfoot></table>';
}

/* ── Item Master edit (Admin only) ────────────────────────────────
   Loads an existing item back into the Add New Item form. The Item Code is
   NOT editable: it is the stable handle this item is known by, and nothing
   would be gained by churning it.

   A rename has to reach the records already generated against the item. Two
   different mechanisms carry it:
     • inward_lines, outward_lines and purchase_requirement_lines hold only
       item_id and read the name back through a join, so IN / OUT / PR
       entries — and every report and PDF built from them — pick up the new
       name the moment items.name changes. Nothing to copy.
     • purchase_order_lines is the one table that keeps its own item_name
       copy, so that copy is rewritten explicitly by syncItemNameOnPoLines_.
       That is not cosmetic: the Pending Requirements screen matches PR lines
       to PO lines on req_no + item name, and a stale copy would make an
       already-ordered quantity look available again. */
let sarvEditingItemId=null;
window.editMasterItem=function(id){
  if(!sarvCan('EDIT'))return sarvDeny('EDIT');
  const row=sarvItemMasterRows.find(x=>x.it.id===id);
  const it=row&&row.it;
  if(!it)return showToast('Item data not found. Please refresh the list.','warn');
  sarvEditingItemId=id;
  const set=(fid,v)=>{const e=byId(fid);if(e)e.value=v==null?'':v;};
  set('mi_itemName',it.name);
  set('mi_itemDesc',it.description);
  set('mi_minStockQty',it.sub_category);
  set('mi_rate',it.rate!=null?it.rate:0);
  set('mi_make',it.make);
  // Read through the helpers, so an item saved before these columns existed
  // loads as blank instead of as the string "undefined".
  set('mi_itemSize',itemSize_(it));
  set('mi_materialType',itemMaterial_(it));
  set('mi_stdOrderQty',itemStdOrderQty_(it));
  // An item saved before the column existed shows (and re-saves) the 5 % default.
  set('mi_excessTol',itemExcessTol_(it));
  // A category or UOM that isn't one of the listed options would silently land
  // on the first option, so anything unknown is added to the dropdown first.
  ensureSelectOption_('mi_category',it.category);
  ensureSelectOption_('mi_uom',it.uom||'PCS');
  ensureSelectOption_('mi_gst',String(itemGst_(it)));
  set('mi_category',it.category||'');
  set('mi_uom',it.uom||'PCS');
  set('mi_gst',String(itemGst_(it)));
  const head=byId('mi_formHeading');
  if(head)head.innerHTML='Editing Item — <span style="color:#b45309;">'+escText(it.item_code||'')+'</span>';
  const btn=byId('addItemBtn');if(btn)btn.innerHTML='Update Item';
  const cancel=byId('mi_cancelEditBtn');if(cancel)cancel.style.display='';
  // The form may be collapsed — an edit that filled fields nobody could see
  // would look like the Edit button did nothing. Opened without remembering,
  // so the user's normal preference survives the edit (cancelItemEdit puts it
  // back).
  setAddItemForm(true,false);
  /* The name box now carries a "already in master" hint, and the item just
     loaded obviously matches itself — re-run it so that reads correctly for
     THIS item (sarvEditingItemId is set above, which is what excludes it). */
  miSyncItemNameHint_();
  byId('mi_itemName')?.scrollIntoView({behavior:'smooth',block:'center'});
  showToast(''+(it.item_code||it.name)+' is open for editing. Make your changes and press Update Item.');
};
// Keeps a value that isn't in a <select>'s option list from being silently
// dropped when an existing record is loaded into the form.
function ensureSelectOption_(selId,val){
  const sel=byId(selId),v=String(val||'').trim();
  if(!sel||!v)return;
  if([...sel.options].some(o=>o.value===v))return;
  const opt=document.createElement('option');
  opt.value=v;opt.textContent=v;
  sel.appendChild(opt);
}
window.cancelItemEdit=function(){
  sarvEditingItemId=null;
  ['mi_itemName','mi_itemDesc','mi_minStockQty','mi_make','mi_itemSize','mi_materialType','mi_stdOrderQty']
    .forEach(id=>{const e=byId(id);if(e)e.value='';});
  if(byId('mi_excessTol'))byId('mi_excessTol').value=String(SARV_DEFAULT_EXCESS_TOL);
  if(byId('mi_rate'))byId('mi_rate').value='0';
  if(byId('mi_uom'))byId('mi_uom').value='PCS';
  if(byId('mi_category'))byId('mi_category').value='';
  const head=byId('mi_formHeading');if(head)head.innerHTML='Add New Item';
  const btn=byId('addItemBtn');if(btn)btn.innerHTML='Add Item';
  const cancel=byId('mi_cancelEditBtn');if(cancel)cancel.style.display='none';
  // Back to however the user normally keeps the form — editMasterItem opened it
  // without remembering, so this is what undoes that.
  initAddItemForm_();
};

/* Rewrites the item_name copy that purchase_order_lines keeps. Rows are matched
   by item_id, plus — for PO lines typed in by hand, which carry no item_id —
   by the old name. Returns how many rows were rewritten. */
async function syncItemNameOnPoLines_(itemId,oldName,newName){
  let touched=0;
  const byItemId=await SB.from('purchase_order_lines').update({item_name:newName}).eq('item_id',itemId).select('id');
  if(byItemId.error)throw byItemId.error;
  touched+=(byItemId.data||[]).length;
  if(oldName){
    const byName=await SB.from('purchase_order_lines').update({item_name:newName}).is('item_id',null).eq('item_name',oldName).select('id');
    if(byName.error)throw byName.error;
    touched+=(byName.data||[]).length;
  }
  return touched;
}

window.addMasterItem=async function(){
  const name=(byId('mi_itemName')?.value||'').trim().toUpperCase();
  if(!name){showToast('Item Name required!','error');byId('mi_itemName')?.focus();return;}
  if(!SB_READY){showToast('Please configure Supabase','warn');return;}
  const editingId=sarvEditingItemId;
  if(editingId&&!sarvCan('EDIT'))return sarvDeny('EDIT');
  if(!editingId&&!sarvGuard('ADD_ITEM'))return;
  const before=editingId?sarvItemMasterRows.find(x=>x.it.id===editingId):null;
  const oldName=before?.it?.name||'';
  const code=before?.it?.item_code||'';
  const btn=byId('addItemBtn');
  if(btn){btn.disabled=true;btn.textContent=editingId?'Updating...':'Saving...';}
  try{
    // The name has to stay unique: the entry forms match typed item names back
    // to the master, and the Item Master pools balances by name, so two rows
    // sharing a name would merge two different items' stock.
    //
    // The check guards a NAME CHANGE, not a save. Editing only the description
    // or the MSV leaves the name alone, and an item must always be able to
    // re-save under the name it already carries — including where the database
    // still holds older duplicates of that name, which would otherwise make the
    // item permanently uneditable.
    const nameChanged=!editingId||oldName.trim().toUpperCase()!==name;
    if(nameChanged){
      // limit(1) rather than maybeSingle(): with pre-existing duplicates
      // maybeSingle() fails with a row-count error instead of this clear message.
      let chkQ=SB.from('items').select('id,name').ilike('name',name).limit(1);
      if(editingId)chkQ=chkQ.neq('id',editingId);
      const chk=await chkQ;
      if(chk.error)throw chk.error;
      if((chk.data||[]).length){showToast(`"${name}" already exists in Item Master!`,'warn');return;}
    }
    const payload={
      name:name,
      description:(byId('mi_itemDesc')?.value||'').trim()||null,
      category:byId('mi_category')?.value||null,
      // Minimum Stock Value. Kept in the legacy sub_category column because
      // that is where every existing item's MSV already lives — renaming the
      // column would need a migration and would orphan that data.
      sub_category:(byId('mi_minStockQty')?.value||'').trim()||null,
      rate:Number(byId('mi_rate')?.value||0),
      uom:(byId('mi_uom')?.value||'PCS').trim()||'PCS',
      make:(byId('mi_make')?.value||'').trim()||null,
      // Per-item GST. Dropped and retried without it if the column is not in
      // the database yet (see the catch below), so this save never fails on a
      // schema that predates it.
      gst_pct:Number(byId('mi_gst')?.value||SARV_DEFAULT_GST),
      /* Size / Material / Standard Order Qty — columns of their OWN, unlike
         MSV, which still rides in the legacy sub_category. These are new, so
         there is no existing data to orphan and no reason to overload a
         column. Each is dropped-and-retried by saveItemRow_ on a database
         where ITEM_MASTER_FIELDS_MIGRATION.sql has not been run yet.
         Blank saves as NULL, not as '' or 0 — "not recorded" and "zero" are
         different answers, and only NULL reads back as the first one. */
      item_size:(byId('mi_itemSize')?.value||'').trim()||null,
      material_type:(byId('mi_materialType')?.value||'').trim()||null,
      std_order_qty:(byId('mi_stdOrderQty')?.value||'').trim()===''?null:Number(byId('mi_stdOrderQty').value),
      excess_tol_pct:excessTolFromBox_('mi_excessTol')
    };
    if(editingId){
      // item_code is deliberately left out of the payload — it is the handle
      // this item is known by and does not follow a rename.
      const {error,dropped}=await saveItemRow_(payload,editingId);
      if(error)throw error;
      warnItemColumnsMissing_(dropped);
      const renamed=!!oldName&&oldName.trim().toUpperCase()!==name;
      // IN / OUT / PR lines point at item_id and read the name back through a
      // join, so they already show the new name — nothing to copy there. Only
      // purchase_order_lines keeps its own item_name, and that copy is
      // rewritten on EVERY save, not just a rename: writing the current name
      // over the current name costs nothing, makes re-saving the item a real
      // repair step if this ever fails, and heals any older drift.
      //
      // It runs after the rename is already committed and the client has no
      // transaction spanning the two, so a failure is reported as what it is —
      // a half-applied rename with a named next step — never swallowed.
      let poCount=0, poFailed=null;
      try{ poCount=await syncItemNameOnPoLines_(editingId,oldName,name); }
      catch(poErr){ console.error('[SARV] PO line name sync failed:',poErr); poFailed=poErr; }
      if(poFailed){
        showToast(`${code||name} was saved${renamed?` ("${oldName}" → "${name}")`:''}, but the name on older PO lines was not updated`
          +` (${poFailed.message||poFailed}). Press Update Item on this item again; it will re-sync those PO lines.`,'warn');
      }else if(renamed){
        showToast(`"${oldName}" → "${name}": IN / OUT / PR entries will show the new name automatically`
          +(poCount?`, ${poCount} PO line(s) also updated`:''));
      }else{
        showToast(`${code||name} updated`);
      }
      cancelItemEdit();
    }else{
      const newCode=(name.replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,28)||'ITEM')+'-'+String(Date.now()).slice(-4);
      const {error,dropped}=await saveItemRow_({item_code:newCode,...payload},null);
      if(error)throw error;
      warnItemColumnsMissing_(dropped);
      showToast(`"${name}" added to Item Master!`);
      cancelItemEdit();   // same field reset the add path always did
    }
    await loadItemMaster();
  }catch(e){dbError(e);}
  finally{
    if(btn){
      btn.disabled=false;
      // cancelItemEdit() has already restored the label on the success path;
      // on a failure the form must still read "Update Item".
      btn.innerHTML=sarvEditingItemId?'Update Item':'Add Item';
    }
  }
};

window.deleteMasterItem=async function(id){
  if(!sarvCan('DELETE'))return sarvDeny('DELETE');
  if(!confirm('Delete this item?\n\nIf it is linked to any Inward/Outward entry, you will get an error.'))return;
  if(!SB_READY)return;
  const{error}=await SB.from('items').delete().eq('id',id);
  if(error){
    if(error.code==='23503')showToast('Cannot delete: it is linked to Inward/Outward entries','error');
    else dbError(error);
    return;
  }
  showToast('Item deleted');
  await loadItemMaster();
};

/* ================================================================
   MASTER DATA — Supplier Master (Full Implementation)
================================================================ */
/* Every suppliers column except pin_hash, which the anon key may not read.
   Used anywhere the old code said select('*'). */
const SARV_SUPPLIER_COLS='id,supplier_code,supplier_name,contact_person,phone,email,gst_no,state,city,created_at';
window.loadSupplierMaster=async function(){
  const tb=byId('supplierMasterBody'),cnt=byId('supplierMasterCount');
  if(!tb)return;
  if(!SB_READY){tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px;color:#f59e0b;">Supabase not configured</td></tr>';return;}
  tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px;color:#94a3b8;">Loading...</td></tr>';
  try{
    // Columns are listed explicitly rather than '*' because pin_hash is no
    // longer readable by this key — selecting it would fail the whole query.
    // Whether a vendor HAS a PIN comes from an RPC instead, which answers the
    // question without handing over the hash.
    const{data,error}=await SB.from('suppliers').select(SARV_SUPPLIER_COLS).order('supplier_name');
    if(error)throw error;
    sarvSupplierMasterRows=data||[];
    try{
      const p=await SB.rpc('suppliers_with_pin');
      if(!p.error){
        const hasPin=new Map((p.data||[]).map(r=>[r.id,!!r.has_pin]));
        sarvSupplierMasterRows.forEach(s=>{s.has_pin=hasPin.get(s.id)===true;});
      }
    }catch(e){console.warn('[SARV] supplier PIN flags skipped:',e.message||e);}
    // Refresh supplier datalists everywhere a supplier/vendor name is picked.
    // Driven by the full set, never by what the search box is showing.
    refreshSupplierDatalist(sarvSupplierMasterRows);
    renderSupplierMasterTable();
  }catch(e){
    if(e?.message?.includes('does not exist')||e?.code==='42P01'){
      tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px;color:#f59e0b;">Suppliers table missing. Please run the SQL patch.</td></tr>';
    }else{dbError(e);tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:16px;color:#ef4444;">Error loading suppliers</td></tr>';}
  }
};
window.renderSupplierMasterTable=function(){
  const tb=byId('supplierMasterBody'),cnt=byId('supplierMasterCount');
  if(!tb)return;
  const q=(byId('supplierMasterSearch')?.value||'').toLowerCase().trim();
  const rows=!q?sarvSupplierMasterRows:sarvSupplierMasterRows.filter(s=>
    [s.supplier_code,s.supplier_name,s.contact_person,s.phone,s.gst_no,s.state,s.city]
      .map(x=>String(x||'').toLowerCase()).join(' ').includes(q));
  if(cnt)cnt.textContent=q?rows.length+' of '+sarvSupplierMasterRows.length+' suppliers':rows.length+' suppliers';
  if(!sarvSupplierMasterRows.length){tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px;color:#94a3b8;">No suppliers yet — Add your first supplier above</td></tr>';return;}
  if(!rows.length){tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px;color:#94a3b8;">No supplier matches this search.</td></tr>';return;}
  tb.innerHTML=rows.map((s,i)=>`<tr style="border-bottom:1px solid #f1f5f9;font-size:11px;">
      <td style="padding:5px 6px;text-align:center;color:#94a3b8;">${i+1}</td>
      <td style="padding:5px 6px;font-weight:700;color:#0369a1;">${escText(s.supplier_code||'—')}</td>
      <td style="padding:5px 6px;font-weight:700;">${escText(s.supplier_name)}</td>
      <td style="padding:5px 6px;color:#64748b;">${escText(s.contact_person||'—')}</td>
      <td style="padding:5px 6px;">${escText(s.phone||'—')}</td>
      <td style="padding:5px 6px;font-size:10px;">${escText(s.gst_no||'—')}</td>
      <td style="padding:5px 6px;">${escText(s.state||'—')}</td>
      <td style="padding:5px 6px;">${escText(s.city||'—')}</td>
      <td style="padding:5px 6px;text-align:center;">${isAdmin()?`<button onclick="setSupplierPin('${s.id}','${escText(s.supplier_name).replace(/'/g,"\\'")}')" style="background:${s.has_pin?'#eff6ff':'#fef9c3'};border:1px solid ${s.has_pin?'#93c5fd':'#fde68a'};color:${s.has_pin?'#1d4ed8':'#92400e'};border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;" title="${s.has_pin?'Change vendor login PIN':'Set vendor login PIN'}">${s.has_pin?'Change':'Set'}</button>`:(s.has_pin?'<span style="color:#16a34a;" title="PIN set">✓ Set</span>':'<span style="color:#cbd5e1;">—</span>')}</td>
      <td style="padding:5px 6px;text-align:center;">${sarvCan('EDIT')?`<button onclick="editMasterSupplier('${s.id}')" style="background:#eff6ff;border:1px solid #93c5fd;color:#1d4ed8;border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;" title="Edit supplier details">✎</button>`:'<span style="color:#cbd5e1;">—</span>'}</td>
      <td style="padding:5px 6px;text-align:center;">${sarvCan('DELETE')?`<button onclick="deleteMasterSupplier('${s.id}')" style="background:#fef2f2;border:1px solid #fca5a5;color:#dc2626;border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;" title="Delete">✕</button>`:'<span style="color:#cbd5e1;">—</span>'}</td>
    </tr>`).join('');
};

let sarvEditingSupplierId=null;
window.editMasterSupplier=function(id){
  if(!sarvCan('EDIT'))return sarvDeny('EDIT');
  const s=sarvSupplierCatalog.find(x=>x.id===id);
  if(!s)return showToast('Supplier data not found. Please refresh the list.','warn');
  sarvEditingSupplierId=id;
  const set=(fid,v)=>{const e=byId(fid);if(e)e.value=v||'';};
  set('ms_supplierName',s.supplier_name);set('ms_contactPerson',s.contact_person);set('ms_phone',s.phone);
  set('ms_email',s.email);set('ms_gstNo',s.gst_no);set('ms_city',s.city);
  if(byId('ms_state'))byId('ms_state').value=s.state||'HARYANA (LOCAL)';
  const pinEl=byId('ms_vendorPin');if(pinEl){pinEl.value='';pinEl.placeholder=s.has_pin?'leave blank to keep existing PIN':'optional — 4+ digits';}
  const saveBtn=byId('ms_saveBtn');if(saveBtn)saveBtn.innerHTML='Update Supplier';
  if(byId('ms_cancelEditBtn'))byId('ms_cancelEditBtn').style.display='';
  byId('ms_supplierName')?.scrollIntoView({behavior:'smooth',block:'center'});
  showToast('Editing "'+s.supplier_name+'". Make your changes and press Update Supplier.');
};
window.cancelSupplierEdit=function(){
  sarvEditingSupplierId=null;
  ['ms_supplierName','ms_contactPerson','ms_phone','ms_email','ms_gstNo','ms_city','ms_vendorPin'].forEach(id=>{const e=byId(id);if(e)e.value='';});
  if(byId('ms_state'))byId('ms_state').value='HARYANA (LOCAL)';
  const pinEl=byId('ms_vendorPin');if(pinEl)pinEl.placeholder='optional — 4+ digits';
  const saveBtn=byId('ms_saveBtn');if(saveBtn)saveBtn.innerHTML='Add Supplier';
  if(byId('ms_cancelEditBtn'))byId('ms_cancelEditBtn').style.display='none';
};
window.addMasterSupplier=async function(){
  const name=(byId('ms_supplierName')?.value||'').trim().toUpperCase();
  if(!name){showToast('Supplier Name required!','error');byId('ms_supplierName')?.focus();return;}
  if(!SB_READY){showToast('Please configure Supabase','warn');return;}
  const editingId=sarvEditingSupplierId;
  if(editingId&&!sarvCan('EDIT'))return sarvDeny('EDIT');
  if(!editingId&&!sarvGuard('ADD_SUPPLIER'))return;
  try{
    const pin=(byId('ms_vendorPin')?.value||'').trim();
    const payload={
      supplier_name:name,
      contact_person:(byId('ms_contactPerson')?.value||'').trim()||null,
      phone:(byId('ms_phone')?.value||'').trim()||null,
      email:(byId('ms_email')?.value||'').trim()||null,
      gst_no:(byId('ms_gstNo')?.value||'').trim().toUpperCase()||null,
      state:byId('ms_state')?.value||'HARYANA (LOCAL)',
      city:(byId('ms_city')?.value||'').trim().toUpperCase()||null
    };
    // pin_hash is deliberately NOT part of the payload — that column is not
    // writable with this key. A typed PIN goes through set_supplier_pin()
    // below, which authorises the write with the Admin PIN on the server.
    let supplierId=editingId;
    if(editingId){
      const{error}=await SB.from('suppliers').update(payload).eq('id',editingId);
      if(error)throw error;
      showToast(`"${name}" updated in Supplier Master!`);
      cancelSupplierEdit();
    }else{
      const code='SUP-'+name.replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,20)+'-'+String(Date.now()).slice(-4);
      payload.supplier_code=code;
      const{data,error}=await SB.from('suppliers').insert(payload).select('id').single();
      if(error)throw error;
      supplierId=data?.id||null;
      showToast(`"${name}" added to Supplier Master!`);
      ['ms_supplierName','ms_contactPerson','ms_phone','ms_email','ms_gstNo','ms_city','ms_vendorPin'].forEach(id=>{const e=byId(id);if(e)e.value='';});
    }
    if(pin&&supplierId)await applySupplierPin_(supplierId,pin,name);
    await loadSupplierMaster();
  }catch(e){
    if(e?.message?.includes('does not exist')||e?.code==='42P01')showToast('Suppliers table missing. Please run the SQL patch.','error');
    else dbError(e);
  }
};
window.setSupplierPin=async function(id,name){
  if(!isAdmin())return showToast('Only an Admin login can set a vendor PIN','warn');
  if(!SB_READY)return;
  // Same reason as verifyEditPassword: window.prompt() is blocked in embedded
  // hosts, so this went through askSecret's modal too.
  const pin=await askSecret({
    title:'Vendor Login PIN',
    subtitle:'Set / change the mobile approval PIN (4+ digits)',
    recordInfo:'Vendor: '+name,
    label:'New PIN',
    confirmText:'Save PIN',
  });
  if(pin==null)return;
  if(!pin.trim())return showToast('The PIN cannot be empty','warn');
  try{
    if(await applySupplierPin_(id,pin.trim(),name))await loadSupplierMaster();
  }catch(e){dbError(e);}
};

/* Writes a vendor's login PIN through set_supplier_pin(), which hashes it and
   authorises the write with the Admin PIN server-side. The hash is never
   computed in, or sent from, this page. Returns true on success. */
async function applySupplierPin_(supplierId,pin,name){
  const adminPin=await askSecret({
    title:'Confirm with Admin PIN',
    subtitle:'Setting a vendor PIN is authorised on the server with the Admin PIN',
    recordInfo:'Vendor: '+(name||'—'),
    label:'Admin PIN',
    confirmText:'Confirm &amp; Save PIN'
  });
  if(adminPin==null)return false;                  // cancelled
  if(!adminPin.trim()){showToast('The Admin PIN cannot be empty','warn');return false;}
  const r=await SB.rpc('set_supplier_pin',{p_supplier_id:supplierId,p_new_pin:pin,p_admin_pin:adminPin.trim()});
  if(r.error){dbError(r.error);return false;}
  if(!r.data){showToast('Incorrect Admin PIN; the vendor PIN was not saved','error');return false;}
  showToast('PIN updated for '+(name||'vendor'));
  return true;
}

